window.__D("text/hemshech-ayin-beis/c001",{"p":[[3601330227,"שע\"י הכלים, וכמ\"ש בבה\"ז אמאה\"ז דבמדבר דקי\"ח ע\"ב במ\"ש אתחם בתחומי שזהו מצד הכלים כו', והו\"ע המיעוט שבהספירה עצמה שמתמעט אורה בהמדרי' תחתונות שבה בכדי שיהי' אצי' הספי' שלמטה ממנה כו', דהגבלה הזאת הוא ע\"י הכלים כו', להיות שהכלים כשם שמגבילים את האור להיות בבחי' מציאות דבר כמו\"כ מגבילים את ההתפשטות דעד פה תבוא כו' (ועמשית\"ל פ'). וכללות המדידה בהע\"ס הוא ע\"י הקו שמודד אופני הגילוים בהע\"ס ועושה בהם מעלה ומטה בבחי' ריבוי ומיעוט בהאור והגילוי כו', וכמו\"כ בחי' המעלה ומטה בעצם מדריגתן שהחכ' תהי' באופן כך וכך ובינה באופן כך וכך כו' הכל הוא מן הקו, להיות שהקו בשרשו יש בחי' ע\"ס שהן ע\"ס הגנוזות כו'. והמשכת הקו הוא ע\"י הצמצום שנמשכים ספי' פרטיות כו', ועם היות שבהקו הן בבחי' פשיטות עדיין שז\"ע מה שהקו הוא מריבוי נקודות כו' כמשנת\"ל פל\"א, מ\"מ ה\"ה בבחי' קו המדה למדוד מהות הספי' להיות באופן כך וכך דוקא, שזה ניכר ביותר בע\"ס דאצי' להיותם בבחי' התלבשות בכלים וכמשנת\"ל פל\"ב, שנעשים עי\"ז בבחי' מציאות ע\"כ הם ג\"כ\nבמדרי' ניכרת בבחי' מעלה ומטה שבהם במהותם ומדריגתם כו'. וי\"ל שזהו מ\"ש בע\"ח שע\"י הקו נק' הנאצלים יו\"ד מדות וי\"ס כו', שזהו להיות ע\"ס בהתחלקות מהותים מיוחדים כו', וכ' שם שזהו לסיבת היותו קו דק ולא בהתחברות גדולה כו'. וי\"ל בשתי אופנים הא' לפי שהמשכתו הוא ע\"י צמצום להיות ספירות מיוחדות כו', והב' י\"ל ע\"פ משנת\"ל פכ\"ז דשרשי האורות ה\"ה מיוחדים באוא\"ס הבל\"ג והן מעין המאור (שז\"ע מין כנף כו'), דמשו\"ז הן בבחי' פשיטות ומ\"מ אין זה כמו פשיטות הא\"ס ממש כו', וזהו שאינו בהתחברות גדולה להיות בבחי' יחוד ממש כו', ועי\"ז הוא בבחי' קו המדה למדוד מדידת האורות דע\"ס להיות בבחי' מדה ושיעור כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ציון במשפט תפדה, דהנה ציון הוא ל' סימן וכמו הציבי לך ציונים דקאי על המצות שהן בחי' ציון וסימן על אוא\"ס שלמע' מהשתל' כו', וזהו ג\"כ שהמצות נק' עדות וכמו בדרך עדותיך ששתי. דהנה עדות שייך על דבר הנעלם, דכל מה שנראה ונגלה הרי א\"צ ע\"ז עדות, ואפי' על מילתא דעבידא לגלוי' א\"צ עדות כ\"א על דבר הסתום ונעלם צריכים עדות, והיינו שהעדות מגלה את הדבר הנעלם כו'. וכמו\"כ הוא למע' ענין העדות הוא לגלות בחי' אוא\"ס סדכ\"ס שסתום ונעלם מהשתל' ומתגלה ע\"י העדות והן המצות שה\"ה רצה\"ע ה\"ה מגלים האוא\"ס סדכ\"ס כו'. וזהו ג\"כ שנק' ציון שהן ציון וסימן לאוא\"ס הסתום והנעלם שבהם וע\"י מאיר בגילוי כו', וכן נש\"י נק' ציון שהן ציון וסימן לאוא\"ס שלמעלה מהשתל', והוא כח הסתום והנעלם שיש בנשמות שהו\"ע רעו\"ד בחי' רצון פשוט שלמע' מטו\"ד שזהו עיקר אלקות שבנשמות (דעש\"ז נק' ישראל שר אל כו' וכמ\"ש במ\"א) שזה נמצא רק בנש\"י כו', וה\"ז עדות וסימן על אוא\"ס הסתום ונעלם דמשם שרש ענין רעו\"ד וע\"י הרעו\"ד מתגלה בחי' אוא\"ס\nהסתום כו'. ועז\"א ציון במשפט תפדה, דציון זהו בחי' רעו\"ד שלמע' מטו\"ד, הנה בכדי לבוא לזה הוא ע\"י המשפט כו', דמשפט הוא שבא בסדר והדרגה והיינו בהאו\"פ שבא בסדר השתל' בסדר והדרגה דמעלה ומטה כו', וע\"י האו\"פ דוקא באים להאור שלמעלה מהשתל' כו'. ובעבודה הוא שצ\"ל תחלה העבודה שע\"פ טו\"ד שהן בכחות פנימיים מוח ולב ועי\"ז"],[3601330228,"באים לבחי' רעו\"ד כו'. וכמו\"כ משפט הו\"ע התורה שנק' משפט, וכמו כמשפט הראשון כהלכתא קמייתא כו', שהתורה היא בחי' או\"פ דאורייתא מחכ' נפקת כו'. וזהו שאמרו בירושלמי חזרנו על כל המקרא ולא מצינו ישראל נק' ציון אלא במקום הזה ואשים דברי בפיך ובצל ידי כו' ולאמר לציון עמי אתה, והן תורה ועבודה וגמ\"ח שעי\"ז הן בבחי' ציון כו', וזהו ציון במשפט תפדה כו'. ושבי' בצדקה וקאי על נר\"נ שהן הכחות פנימיים דבזה יכול להיות בחי' גלות בכחות דנה\"ב שמתגברים על הכחות דנה\"א ומעלימים ומסתירים עליהם כו'. והפדי' הוא בצדקה שזהו בעבודה ענין התעוררות ר\"ר על נפשו וכמו הצדקה שהיא רחמים על העני כו', כן בעבודה הו\"ע התעוררות ר\"ר שעי\"ז יהי' התגלות הכחות דנה\"א, וכמ\"ש ברחמיך הרבים רחם עלינו ותן בלבינו בינה כו'. וזהו ציון במשפט תפדה דבכדי שיהי' התגלות בחי' עצם הנשמה בחי' רעו\"ד זהו ע\"י המשפט, כי צ\"ל תחלה התגלות כחות הפנימיים שז\"ע משפט להיותם בסדר והדרגה כו', ושבי' היינו כאשר צריכים להוציא ממאסר והסתר את הכחות פנימיים זהו ע\"י הצדקה שהו\"ע התעוררות רחמים רבים. וזהו ושביה בצדקה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובזוהר אי' דבכל ספי' יש מדה וגבול ותחום, מדה היא בעצם מדריגתן, גבול הוא אופן הגילוי, ותחום הוא המיעוט בשביל אצילת המדרי' שלמטה, וכללות המדידה הוא ע\"י הקו מצד שרשו בע\"ס הגנוזות. וע\"פ הנ\"ל ית' הפסוק ציון במשפט תפדה.</span>"],[3601330229,"<h3>בס\"ד. ש\"פ ואתחנן, תער\"ב</h3>\n<b>נחמו</b> נחמו עמי יאמר אלקיכם דברו על לב ירושלים וקראו אלי', וצ\"ל מהו הכפילות נחמו נחמו עמי, ורש\"י פי' אתם נביאי נחמו את עמי והיינו שזהו הדבור לנביאים שינחמו את ישראל. וג\"ז אינו מובן מה\"ע הדבור לנביאים שינחמו והלא דבור הנבואה זהו גופא הנחמה, וכשאומר לנביאים נחמו הרי המשמעות שיש איזה נחמה לבד דבור הנבואה עצמה, וצ\"ל מהו הנחמה הזאת. ובמד\"ר אי' לקתה בכפליים ונחמה בכפליים, וא\"מ מה\"ע לקתה בכפליים איך שייך שיהי' ח\"ו העונש בכפליים על החטא, דבשלמא הנחמה בכפליים הוא מפני שמדה טובה מרובה כו', אבל מה שייך לקתה בכפליים כו', ומפני שלקתה בכפליים לכך ניחמה בכפליים צ\"ל מה\"ע הכפל כו'. גם צ\"ל מ\"ש דברו כו' וקראו כו', דלכאו' א\"ז כפי הסדר שצ\"ל קריאה קודם לדיבור וכמ\"ש ויקרא אל משה וידבר כו', ומפני מה אומר כאן תחלה דברו ואח\"כ קראו כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דהע\"ס דאצי' הן בבחי' התחלקו' מעומ\"ט שהחכ' היא בבחי' לגבי בינה והמוחין בכלל הן בבחי' מעלה לגבי ז\"א וכן ז\"א לגבי מל' שהיא בחי' סודכ\"ד דאצי' כו', ונת' דמעומ\"ט הוא בב' ענינים הא' בבחי' ריבוי ומיעוט שבהספירה העליונה הוא בחי' ריבוי האור"],[3601330230,"דהיינו בחי' הגילוי דאוא\"ס ב\"ה ומתמעט ומתעלם האור ממדרי' למדרי' כו', והב' בעצם מהותם ומדריגתם שהספי' העליונה היא בבחי' מעלה בעצם מהותה לגבי הספי' שלמטה ממנה כו'.\nמה) <b>והנה</b> לבד זאת שהע\"ס בפרטיות מדריגתן הן בבחי' מעלה ומטה כו', הנה כללות הע\"ס שבעולמות אבי\"ע הן בבחי' מעלה ומטה כו', שהרי הע\"ס ישנם בכל עולם ועולם דכשם שיש ע\"ס באצי' כמו\"כ יש ע\"ס בברי' ויצי' ועשי', שהע\"ס דבי\"ע הן שנמשכים מהע\"ס דאצי' כו'. ומ\"מ אינו דומה הע\"ס דברי' לגבי הע\"ס דאצי' כו', וכמ\"ש בהקדמת ת\"ז דהע\"ס דבריאה הן בחי' דיוקנא דמלכא בחותמא ולאו דיוקנא דמלכא ממש כמו הע\"ס דאצי', וע\"ס דיצירה הן כמו דיוקנא דחותמא בשעוה כו', באופן שהע\"ס דבריאה אינם כמהות הע\"ס דאצי' כלל כו'. והענין הוא דהנה נודע שיש פרסא בין אצי' לבריאה דענין הפרסא הוא כמו המשל שהוא ענין זר לגמרי מהנמשל, וע\"כ השכל שמובן ע\"י המשל אינו כמהות השכל המובן שלא ע\"י המשל כו', וכמו\"כ הו\"ע הפרסא שזהו מה שמדבר מענין אחר שלא מענין האצי', והיינו דבחי' חכ' דברי' היא באופן ומהות אחר ממהות החכ' דאצי' כו' וכמ\"ש בתו\"א ד\"ה פתח אלי'. ויובן זה עד\"מ בהשגה שלנו באלקות שהרי כל ההשגה באלקות היא מפעולותיו ית' שע\"י הפעולות אנו יודעים\nומשיגים את אלקות כו', והנה כל הפעולות למטה הן בזמן ומקום שהרי לא יש שום דבר בעולם התחתון שלא יהי' בבחי' זמן ומקום כו', וע\"כ כל השגתינו באלקות נתפס ג\"כ בבחי' מקום, והיינו שהציור שכלי שלנו באלקות הוא בבחי' מקום כו'. ויש בזה חילוקים בענין ההעלם והדקות (היינו באופן הציור אם הוא בהגשמה או בדקות או רק בהעלם), דבענין נעלה באלקות או בבעל שכל גדול אין הענין נתפס כ\"כ באיזה ציור ומאיר יותר הענין עצמו שהוא בחי' האור כו', אבל בהעלם הכל הוא נתפס בציור דמקום כו', והרי אנו יודעים שהאלקות אינו בבחי' מקום ח\"ו, מ\"מ כמה שאנו שוללים הציור וההגשמה מאלקות מ\"מ ה\"ז נתפס בציור בהעלם כו'. וידוע דענין המקום הוא רק עד גלגל התשיעי ולמע' מגלגל התשיעי מוסכם מכל החוקרים שאין שם מקום כלל, והרי ההשגה שם למע' מגלגל התשיעי והיא השגת המלאכים הוא ג\"כ מפעולותיו ית', אבל שם הוא מפעולות שאינם בבחי' מקום כו', וא\"כ הרי ההשגה שם באלקות אינו נתפס בבחי' מקום כו', אשר בהשגתינו אינו מושג כלל איך הוא דבר בלי מקום והוא למע' מגדר השגתינו\nלגמרי שאין אנו יודעים איך ומה הוא. וא\"כ הרי השגתינו באלקות שנתפס הכל בציור בחי' מקום אינו כלל כמהות ההשגה העליונה שאינו בבחי' מקום כלל כו'. ובדוגמא כזאת היא כללות ענין ההשגה דבי\"ע לגבי ההשגה דאצי' שאינו במהות זה כלל, דכמו שהשגתינו הוא מהות השגה אחרת לגמרי לגבי ההשגה דעולמות בי\"ע הרוחנים כו', כמו\"כ ההשגה דבי\"ע היא מהות אחרת מההשגה דאצי' כו', וזהו מה שמדבר מענין אחר שלא מענין האצי', היינו דהידיעה וההשגה האלקית דעולם הברי' הוא מענין אחר שאינו אלקות כו', דבאצי' הרי הכל הוא אלקות ממש ואינו שייך שם ענין הישות כלל כו'. ומה שמדבר בענין אחר שלא מענין האצי' הוא שמענין אחר שאינו אלקות מובן ומושג הענין האלקי כו', דהשגה הזאת הוא מהות אחר לגמרי לגבי ההשגה דאצי' כו'. וגם מה שאימא עילאה מקננא בכורסי' אינו דומה בחי' הבינה כמו שהיא בעולם הבריאה לכמו שהיא באצי' כו', דבאצי' ה\"ה בבחי'"],[3601330231,"יחוד עם בחי' החכ' וכמ\"ש ונהר יוצא מעדן דנהר הוא בחי' בינה, וכנודע דחו\"ב הן כמו מעין ונהר, דמעין הוא נביעה דקה שזהו בחי' אין דחכ' ובינה הוא בבחי' התפשטו' כו', וכתיב ונהר יוצא שהוא יוצא תמיד בלי הפסק היינו בבחי' יחוד ודביקות כו', ואח\"כ כתיב ומשם יפרד פי' אחר שנמשך מבחי' בינה לבחי' מל' ומתפשטת ומתלבשת בבי\"ע ה\"ה בבחי' פירוד כו' וכמ\"ש מזה בלק\"ת ד\"ה ששים המה מלכות דרוה\"ר. והגם דבעולם הבריאה יש השגה אלקית מ\"מ אינו דומה כלל לההשגה שבעולם אצי' כו', וי\"ל דכללות בחי' המוחין דברי' הן בחי' מוחין השייכים אל המדות. דהנה נודע שיש ב' מדרי' במוחין, מוחין בעצם ומוחין השייכים אל המדות, דמוחין בעצם הוא השגת עצם הדבר שמשיג בשכלו, ומוחין של המדות הוא שמשיג טוב הדבר, שמשו\"ז צריך לאהוב את הדבר כו', דעם היות שזהו ג\"כ שכל והשגה א\"ז בעצם הדבר כ\"א השייך אל המדה לבד כו'. ובכללות יותר בחי' המוחין השייכים אל המדות הן חיצוני' המוחין כמו שבא בלבושי השגה, דהגם שזהו ההשגה בעצם הדבר היינו בהשכלי לא רק בטוב הדבר, ה\"ז מ\"מ\nבקירוב אל המדות כו', וכמו בהתבוננות אלקי בהתלבשות לבושי ההשגה ה\"ה תופס רק בחיצוני' הענין האלקי השייך אל העולמות והנבראים כו', וע\"כ נרגש בזה הטוב דאלקות בבחי' הרגש עצמי איך שקרבת אלקים לי טוב כו', והיינו מפני שהתפיסא היא במדרי' האלקות שבבחי' קירוב אל הנבראים כו', ותופס הענין בלבושי השגה שאין האדם יוצא בזה מהגשמתו, אדרבה הענין בא בהגשמת שכלו (ואינו כמו הגשמת המדות כו', ובד\"כ בכל השגה שכלי' ה\"ה בבחי' עלי' והתקשרות לענין שלמע' ממנו כו' וכמ\"ש במ\"א. אך כאשר הוא בלבושי השגה אינו יוצא בזה ממהותו וה\"ה במעמדו ומצבו כו'), וע\"כ ה\"ז בקרוב אל ההרגש דקרבת אלקים לי טוב שזהו הבכן שהו\"ע מוחין שבמדות כו'. משא\"כ כשההשגה היא בבחי' הפשטה מלבושי ההשגה כ\"א בעצם הענין האלקי ה\"ה בבחי' קירוב יותר אל העצם דאלקות שלמע' מבחי' התלבשות בעולמות ונבראים כו', וגם שבזה הוא יוצא ממהות הגשמתו שבעצם מהותו הוא בבחי' הפשטה ובבחי' עלי' ודביקות יותר בעצם הענין האלקי כו', וע\"כ אינו שייך עדיין למדות כו', וזהו בחי' המוחין עצמן\nשלמע' מהמדות כו'. ולמע' יותר בחי' המוחין השייכים אל המדות הוא ההשגה באלקות שבא בבחי' התלבשות בעולמות דבד\"כ ה\"ז הארה לבד כו', וההשגה בזה באופן האור והגילוי בכל עולם כו', ומוחין בעצם הוא ההשגה במדרי' נעלות באוא\"ס ב\"ה שלמע' מבחי' התלבשות בעולמות כו'. וכללות ההשגה דעולם הבריאה י\"ל שזהו בבחי' המוחין השייכים אל המדות כו', דלבד זאת שבעצם מהותם מחולקים המוחין דברי' מהמוחין דאצי' כנ\"ל, הנה כללות המוחין דברי' הן השייכים אל המדות כו'. ובפרטיות יש בזה חילוקי מדרי' שהרי גם באצי' יש בחי' מוחין בעצם ומוחין השייכים אל המדות, רק בכללות ענין המוחין י\"ל דבבריאה הן השייכי' אל המדות הנק' מוחין דיניקה שהמדות יונקים ממדרי' זו כו' והן בחי' מוחין דקטנות כו', וזהו שבעולם הבריאה הן דו\"ר שכליים כמ\"ש בסש\"ב פל\"ט והן המדות הבאים מהבינה והדעת כו', ובאצי' בחי' מוחין דגדלות כו'. ועולם היצי' העיקר בחי' המדות והיינו בחי' רוח כו', ויש ג\"כ מוחין ורק מה ששייך להנהגת המדות, וכמו שיש הפרש בין קטן לגדול במדות טבעים שהרי גם\nהגדול נמשך אחר הטבע, אבל אין זה כלל כמו הקטן מפני השכל שבו שפועל בהמדות להיות הנהגתן ע\"פ השכל כו', והן מוחין"],[3601330232,"השייכים להנהגת המדו' לבד כו'. ועולם העשי' בחי' נפש והו\"ע המעשי' בפו\"מ, ויש בזה ג\"כ מוחין אבל הן בקטנות לגמרי דהיינו רק מה ששייך לעשי' לבד כו'. וכ\"ז הוא כמשנת\"ל פ\"ב במשל בנפש האדם שהשכל נמשך ומתלבש בכל הכחות, ועצמיות המוחין הוא במוח שבראש, ומה שמתלבש במדות הוא רק חיצוני' המוחין, ובפרט בכח התנועה וההילוך שיש בהם ג\"כ התלבשות השכל והוא רק שכל המעשי לבד בחי' היותר אחרונה שבשכל כו'. וכמו\"כ הוא בדוגמא למע' שבחי' החכ' וכן כל הע\"ס ישנם בכל העולמות, אך באצי' הוא בחי' העצמות ומה שנמשך בבי\"ע ה\"ז רק הארה לבד ואינו בחי' מהות האור דאצי' כו', וזהו בחי' התחלקות מעלה ומטה שבעולמות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו\"כ הוא התחלקות מעומ\"ט בעולמות, דע\"ס דברי' אינם מהות ע\"ס דאצי' וזהו שמדבר מענין אחר, וכמו השגתינו שהוא בציור דמקום שאינו מהות השגה עליונה כלל שהיא לא בבחי' מקום, וכמו אצי' הוא השגת עצם אלקות, וברי' השגת אלקות ע\"י ד\"א, גם אימא עילאה שמקננא בברי' אינו כמו באצי'. וי\"ל דמוחין דברי' הן רק השייכים להמדות, ויבאר דהמוחין השייכים למדות הוא השגת טוב הדבר, ולמעלה מזה הוא חיצוניות השכל, שבא בהגשמת שכלו, וע\"כ הוא בקירוב אל ההרגש דלו טוב, משא\"כ פנימיות השכל בקירוב יותר אל הרגש עצם האלקי, ולמעלה יותר שההשגה היא בהאלקות שבעולמות, ובכללות הוא בחי' מוחין דיניקה, ויצי' מדות והמוחין הן רק להנהגת המדות, ועשי' מעשה ושכל המעשי.</span>\nמו) <b>והנה</b> כ\"ז הוא בבחי' אור פנימי שבא בבחי' התלבשות בכלים, דבשרשו ומקורו באוא\"ס שלפה\"צ הוא מה ששיער אוא\"ס ב\"ה להאיר בבחי' מדה וגבול, דע\"כ אין הארתו בשוה בכל העולמות והספירו' והיינו שיש בו מעלה ומטה בבחי' ריבוי ומיעוט כו', וגם בהאור גופא יש בו מעלה ומטה והו\"ע הע\"ס שבו שמחולקים המה במהותן ומדריגתן כו', ובאים בבחי' התלבשות בכלים דע\"ס דאצי' בבחי' התלבשות פנימי, שעי\"ז נעשים בבחי' מציאות דבר, ובהע\"ס ניכר ביותר בבחי' ההתחלקות דמעלה ומטה שבהם כו' (עמשנת\"ל פל\"ב). אמנם בחי' האור מקיף הוא שאינו בא בבחי' התלבשות בכלים, משום דבשרשו ומקורו באוא\"ס שלפה\"צ הוא האור שבבחי' א\"ס ובבחי' בל\"ג, והוא בבחי' גילוי העצם שמעין העצם כו'. דהנה נת\"ל פט\"ז ופכ\"ז דשרשי האורות הם ג\"כ מיוחדים בהעצם שזהו\"ע שמי המיוחד בי כו' והן מין הכנף כו'. מ\"מ הרי האור הזה הוא מה ששיער אוא\"ס להאיר את העולמות, וזהו שהאור יש בו ע\"ס משום דכללות האור הוא להאיר את העולמות כו', ולולא העולמות אינם שייכים בחי' האלו כלל כו', וכמ\"ש בזהר\nברע\"מ פ' פנחס דרנ\"ז ע\"ב דאיהו אתקרי חכם בכל מיני חכמות כו' (וחושב שם כל הע\"ס), אלא קודם דברא עלמא אתקרי הוא בכל אינון דרגין על שם בריין דהוו עתידין להבראו' דאי לאו בריין דעלמא אמאי אתקרי רחום כו', והיינו שכל הע\"ס הן לצורך העולמות. וכמו בחי' המל' הרי ענין המלוכה שייך כשיש עם דוקא וכמא' אין מלך בלא עם כו', וסיבת הרצון דהתהוות העולמות הוא מפני שעלה ברצונו אנא אמלוך ואין מלך בלא עם, ע\"כ עלה ברצונו ית' להיות עולמות כו', ומש\"א אדון עולם אשר מלך בטרם כל יצור נברא כו', היינו בחי' המלוכה כמו"],[3601330233,"שהיא בעצמותו ית' שלמע' מבחי' גילוי כו', אבל בבחי' גילוי אור ענין המלוכה הוא ששייך לעולמות כו'. וכן המדות הן לצורך הזולת דוקא, וכידוע ההפרש בין מוחין למדות דמוחין א\"צ לזולת דהיינו שאינו מוכרח להשפיע אל הזולת, דגם כשלא יש זולת למי להשפיע יכול להשכיל השכלות לעצמו, והגם דמתלמידי יותר מכולם היינו שע\"י השפעה אל הזולת מתוסף אור שכל אצל המשפיע ובפרט ע\"י קושיות וכה\"ג וכמ\"ש במ\"א, אבל גילוי אור השכל בדרך אור ישר יכול להיות גם בלא זולת, וכאשר צריכים לבוא על איזה השכלה או השגה חדשה אדרבה הזולת מבלבל, וגם כשצריך לשקול בדעתו להכריע בין ב' סברות צריך להתיישב בינו לבין עצמו דוקא להתקשר אל הענין ולהכיר ולהרגיש אמיתית הסברות ולהכריע ביניהם ע\"פ ההכרה וההרגשה באמיתת הענין, שלכ\"ז הזולת מבלבל ורק בינו לבין עצמו יוכל לבוא על אמיתית הדבר כו'. וזהו דגם סנהדרין היו נושאין ונותנין ביניהם כאו\"א לעצמו או עם בן זוגו כו' וכמ\"ש במ\"א, וגם בעצמו צריך להשקיט הכחות האחרים שלבד כח השכל ולעכבם שלא יהיו בהתפשטות, ואז דוקא\nיבוא על אמיתת השכל או על השכלה חדשה, דגם התפשטות הכחות שלבד כח השכל מבלבלים אל השכל וצריך לעצרם ולעכבם כו'. וגם בכדי לבוא על איזה השכלה חדשה צ\"ל העלאת כלי שכלו, והו\"ע אשתומם כשעה חדא בהעדר התפשטות אדרבה בבחי' עלי' דוקא ועי\"ז בא על ההשכלה כו'. וטבע מוחין דגדלות להיות בבחי' הבדלה, ואין זה ענין הגבהה דגם מי שהוא ענו בעצם מ\"מ מצד טבע המוחין הוא בהבדלה שאינו מתערב עם הזולת כו'. וכ\"ז הוא בענין המוחין שהן לעצמו דוקא, אבל טבע המדות הוא להיפך שהן רק אל הזולת, כמו החסד והרחמים הרי אינו שייך שמתחסד או מתרחם על עצמו כ\"א על הזולת, וכשלא יש זולת למי להשפיע מתבטל המדה וה\"ה כאילו אינו כו'. והגם שיכול להתעוררות הטבה באיש הטוב גם כשלא יש למי להשפיע, זהו מ\"מ כאשר בכללות נמצאים מי שצריכים לקבל טובת השפעתו והמדה עומדת בהתגלות, תהי' ההתעוררות גם כשלא יש בעת ההיא למי להשפיע וכמו באאע\"ה שהצטער כשלא הי' לו למי להשפיע חסדו כו'. אבל כשלא יהי' בכלל למי להשפיע, הנה הגם שיש בנפשו מדת הטוב תתעלם לגמרי וה\"ה כאלו אינו,\nמשום דענין המדה הוא להשפיע אל הזולת דוקא וכשלא יש זולת מתבטל המדה כו'. והתעוררות המדה היא דוקא כאשר הוא בקירוב אל הזולת, ויודע עניניו ומתעורר ברחמים עליו, ולא תהי' התעוררו' המדה כשהוא בהבדלה כ\"א כשהוא בקירוב דוקא כו'. והדוגמא מזה למע' דענין המדות הן לצורך העולמות דוקא וכמ\"ש זכור רחמיך וחסדיך כי מעולם המה דרחמים וחסדים שייכים לעולמות דוקא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם כ\"ז הוא בבחי' או\"פ שהוא להאיר העולמות ולולא העולמות אינם שייכים כלל, וכמו המל' הוא למלוך על עם, ומדות הן לצורך הזולת, דבמוחין הרי יכול להיות התגלותן גם לעצמו, ולהשכיל או להכריע דבר הזולת מבלבל, ומוחין דגדלות הן בהבדלה, והמדות התגלותן והתעוררותן הוא דוקא כשיש זולת והוא בקירוב אליו.</span>\nמז) <b>והפרד\"ס</b> שע\"ד פ\"י בביאור מאה\"ז הנ\"ל כ' דגם בחי' חו\"ב שהן כחות שאינם שייכים אל הזולת דוקא, וכנ\"ל ההפרש בין המוחין"],[3601330234,"למדות כו', מ\"מ גם הם רק לצורך העולמו' כו'. וי\"ל דע\"י חו\"ב דוקא המדות הן בבחי' אור פנימי דלולא בחי' חו\"ב היו המדות בבחי' אור מקיף וכמו המדות שלמע' מהשכל כו', ובכדי שיהי' אור פנימי, הוא ע\"י המוחין דוקא, שהמוחין הן בעצם בחי' פנימי ועושין ג\"כ בהמדות שיהיו בבחי' אור פנימי כו' (ומ\"ש במ\"א דעיקר הפנימי הן המדות והמוחין הן בבחי' מקיף עדיין כו', הנה שם הכוונה בענין התפיסא וההתלבשות (שז\"ע פנימי כו'), דבמדות ה\"ה נתפס בהדבר משא\"כ במוחין אינו נתפס כ\"כ, ולכן במדות אינו יכול לסבול הדבר השנאוי מפני שע\"י המדות ה\"ה נתפס בהדבר וע\"כ לא יוכל לקבל דבר ההפכי ונגדי השנאוי איליו, ובמוחין לפי שאינו בבחי' תפיסא כ\"כ יכול לסבול דבר השנאוי כו' וכמ\"ש במ\"א. וכמו שהתפיסא בכלים הוא במדות דוקא ובמוחין אינו כ\"כ בבחי' תפיסא בכלים כנודע, והלא כל ענין ההשגה היא תפיסא בכלי דוקא רק שהכלים אינם כאלו להיות בבחי' תפיסא ממש כו'. וכמו\"כ הוא בכללות שהמוחין אינם בבחי' תפיסא כ\"כ בהדבר שיודע ומשיג, ובמדות הוא בבחי' תפיסא כו'. אבל באמיתת\nענין פנימי ומקיף הנה המוחין הן בבחי' פנימי בעצם והמדות אינם בבחי' פנימי בעצם, ועמשית\"ל פ' שהמדות הן בחי' הרצון בשרשן כו', רק שע\"י המוחין נעשים בבחי' פנימי כו'), ולהיות שהכוונה הוא להיות בחי' או\"פ ע\"כ צ\"ל בחי' חו\"ב כו'. ולפי\"ז מה שחו\"ב הן לצורך העולמות היינו בשביל המדות שיהיו בבחי' או\"פ לא שהחו\"ב עצמן הן לצורך העולמות, ומהפרד\"ס משמע דחו\"ב עצמן הן לצורך העולמות. וע\"כ י\"ל דהנה ידוע דענין האצי' הוא שיהי' גילוי אלקות בעולם, דלולא האצי' לא הי' התגלות אלקות כלל, שהרי המדרי' שלמע' מאצי' ה\"ה בבחי' סתימות והעלם לגמרי כו' (וההתהוות דעולמות הי' לא בבחי' גילוי אור כו'), וע\"ז הוא התהוות האצי' להיות בחי' גילוי אור בעולמות והיינו שיהיו כחות אלקיים בעולמות כו'. אמנם בזה יש ב' ענינים התפעלות אלקי והשגה אלקית, דמהמדות העליונות נמצא התפעלות אלקי בעולם, ומחו\"ב נמצא השגת אלקי כו'. וזהו שחו\"ב הן לצורך העולמות (הגם ששייכים גם אם לא היו העולמות כו'), בכדי שיהי' ידיעה והשגה אלקית בעולמות כו' וכמשנת\"ל פ\"ו. וכ'\nהפרד\"ס שם וז\"ל כי קודם התפשטות המדות הי' מתחכם בעצמותו וחכמתו בהשגת עצמותו כי הוא וחכמתו הכל עצם א' עכ\"ל, ונר' הכוונה על חו\"ב הכלולים בא\"ס ב\"ה, וי\"ל דהו\"ע ידיעת עצמו וכמ\"ש באגה\"ק דבידיעת עצמו יודע את התורה כו', ומבו' במ\"א שזהו עד\"מ כמו המח' ודיבור דענין הדיבור הוא רק בשביל הזולת, משא\"כ המח' היא לגלות העלם העצמי לגבי עצמו כו'. וכמו\"כ הוא הדוגמא בענין ז\"ת וג\"ר דז\"ת הן בשביל העולמות וג\"ר הן מה שבידיעת עצמו יודע שהו\"ע לגלות העלם העצמי לעצמו כבי', ועמ\"ש בהוספות לקו\"ת ד\"ה להבין מ\"ש באוצ\"ח ספ\"ג בענין מח' ודיבור שהכל לעצמו, רק שהדיבור הוא לעצמו בשביל הזולת וכמו אמרה ד\"פ בינו לבין עצמו, והמח' הוא הגילוי לעצמו כו'. ומ\"מ גם בחי' ידיעת עצמו היא בשביל ההשתל'. דהנה לכאו' א\"מ מאחר שזהו רק לגלות העלם העצמי לגבי עצמו א\"כ לאיזה צורך נאצל דהרי לעצמותו ית' ידוע גם קודם שנאצל כו'. אך הענין הוא דבכדי שיהי' מציאות בחי' חכ' שגם זולתו יוכל להבינה, הי' צ\"ל נאצל תחלה מציאות שם חכ' שעדיין אינו שייך כלל לגילוי\nהזולת, רק מה שבידיעת עצמו יודע את התורה, דע\"י שנמצא ש' חכ' נתהווה אח\"כ בחי' החכ' דאצי', שהו\"ע בחי' חכ' דתורה כמו שהוא למע' עדיין ושאינה"],[3601330235,"בשביל הזולת רק שיכולה להיות בהשגת הזולת כו', וכנ\"ל פמ\"ו שבחי' החכ' אינה בשביל הזולת שהרי יכול לישב לעצמו ולהשכיל השכלות, אמנם היא חכ' במציאו' מורגשת שגם זולתו יוכל להבינה, רק שאינו מוכרח שישפיע לזולתו, כמו המדות עד\"מ שבהעדר ההשפעה מתבטל המדה, משא\"כ החכ' שיכול להיות מציאותה גם בלי השפעה אל הזולת, אבל עצם מציאותה הוא באופן שיכולה להביא בהשגת הזולת כו'. וכמו\"כ הוא הדוגמא בח\"ע דאצי' שנק' חכ' ידיעא להיותה בחי' חכ' דתורה שיכולה לבוא בגילוי אל הזולת, וכשבא הזמן דשני אלפים תורה התחיל לבוא לידי גילוי בחי' אור ושפע דחכ' זו, וכמ\"ש בלק\"ת מהאריז\"ל דהתחלת יחו\"ע דמ\"ת הוא מאאע\"ה דאז הי' התחלת זמן שני אלפים תורה, עד שבאה לידי גילוי ממש בבי\"ע ע\"י מרע\"ה. ובכדי שתהי' בחי' חכ' זו הי' צ\"ל ש' בחי' חכ' שאינה יכולה לבוא כלל אל הזולת והוא בחי' ידיעת עצמו מה שבידיעת עצמו יודע את התורה כו' (נת\"ל פט\"ו דהע\"ס הגנוזות הן בחי' עתיק דא\"ק, וי\"ל דעיקר בחי' עתיק הן הג\"ר וז\"ת דעתיק נק' עתיק יומין ומתלבשים בא\"א כמ\"ש בע\"ח שער\nסדר האצי' רפ\"א, ונודע דעתיק הוא בבחי' סתום בעצם שאינו בא לידי גילוי כלל ונק' מתן בסתר כו' וכמ\"ש במ\"א), וזהו בחי' לא בחכ' ידיעא כו' (והגם שנת\"ל דחכים ולא בחכ' ידיעא שייך רק בההתגלות דע\"ס אחר הצמצום וכמשנת\"ל פכ\"ט בהג' מדרי' שבאורות כו', הנה מש\"א כאן ולא בחכ' ידיעא היינו בחי' לא ידע שאינו מהות ידוע בעצם כו' וכמ\"ש בסי' בפי' ברוך שאמר), וע\"י שנאצל שם חכ' וידיעה נמצא אח\"כ בחי' חכ' דאצי' שהיא בחי' חכמה ידיעא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והפרדס כ' שגם חו\"ב הן לצורך העולמות, והיינו דבכדי שיהיו המדות בבחי' או\"פ הוא ע\"י המוחין (מוחין פנימים בעצם ומדות רק בענין התפיסה) גם דענין המוחין הוא להיות השגה אלקית בעולם, והמדות להיות התפעלות אלקי, ומובן בפרדס דגם ידיעת עצמו כבי' הוא לצורך העולמות, והענין הוא דחכ' דאצי' היא חכמת התורה שלמעלה שנאצלה באופן שיכולה להיות בהשגת הנשמות, ובשביל זה נאצל תחילה בחי' ידיעת עצמו, והוא בחי' ג\"ר דשרשי האורות.</span>\nמח) <b>ועוי\"ל</b> דהנה נת\"ל פ\"ח דאמצעית אצי' הוא בשביל ההתהוות דבי\"ע וגם בשביל שיהי' הגילוי בבי\"ע כו', וי\"ל דהע\"ס הגנוזות שהן בחי' אצי' דכללות כו' בחי' הז\"ת דהע\"ס הן לצורך ההתהוות והג\"ר הן לצורך הגילוי כו' (ובד\"כ הו\"ע ש' הוי' הב' שהוא ל' מהווה כמו שנת\"ל פט\"ז, ובזה גופא יש ב' המדרי' הנ\"ל). דהנה ב' ענינים הנ\"ל דהגילוי לעצמו והגילוי לזולתו מבו' במ\"א שז\"ע בחי' חיוהי וגרמוהי, דגרמוהי הוא בשביל הזולת שנעשה מקור להתהוות וחיוהי הוא מה שלמע' מבחי' מקור להתהוות, והו\"ע החכ' תעוז לחכם יותר מעשרה שליטים להיות בחי' הגילוי כו'. וכמו\"כ י\"ל בע\"ס הגנוזות דז\"ת הן בשביל ההתהוות וג\"ר הן בשביל הגילוי כו' (ועמ\"ש בד\"ה יונתי, תר\"מ, וי\"ל שז\"ת זהו בחי' איהו המתייחד עם גרמוהי וג\"ר זהו בחי' איהו המתייחד עם חיוהי כו', והוא בחי' כח ההתהוות וכח הגילוי כו' ועמשית\"ל פ'). ונמצא דהע\"ס הגנוזות שכלולים ונעלמים באוא\"ס ב\"ה הן בשביל להאיר בעולמות לאחר הצמצום כו',"],[3601330236,"אבל האור הא\"ס אינו בשביל להאיר כ\"א הוא בחי' גילוי מן העצם, וכמו מראה וגוון איזה דבר שאינו לפעול איזה דבר כ\"א רק שמורה על העצם כו', ואין זה כמו אור וזיו השמש שהוא דבוק בהעצם ומעין העצם שהעצם הוא בהירי וע\"כ גם ההתפשטות ממנו הוא אור וזיו כו', הרי מ\"מ האור ענינו הוא לפעול פעולת האור כו', וכמ\"ש ויתן אותם אלקים ברקיע השמים להאיר על הארץ כו', דאור השמש אינו לתאר את העצם כ\"א לפעול דבר כו'. והדוגמא מזה למע' הוא האור שלהאיר העולמו' שג\"כ מיוחד בהעצם ומעין העצם ומ\"מ ענינו הוא להאיר כו', אבל עצמות האור הוא רק בבחי' גילוי כו' כמו מראה וגוון העצם כו', וכמו אור פני האדם דחכמת אדם תאיר פניו שאור חכמתו ניכר בהארת פניו, הרי אור פניו אינו פועל איזה פעולה שיאיר ויגלה חכמה לזולתו רק שמורה על עצם החכ' שבו כו' (ולעיל פמ\"ג נת' דע\"י ראיית פני המשפיע מתוסף לו חכמה כו'. הרי נת' שם שעי\"ז מקבל מעצמיות החכ' של המשפיע, והיינו שהארת פני המשפיע מורה ומגלה עצם החכ' שלמע' מהגילוי דחכ' כו' וגם שזהו בעת ההשפעה, אבל בלא\nהשפעה הוא רק שמורה על העצם דהכרת פניו ענתה בו שהוא חכם גדול כו'). וכמו\"כ הו\"ע אור א\"ס שהוא בחי' גילוי מן העצם לבד, וגם אם לא היו עולמות שייך בחי' זו כו', וגם בחי' האור והגילוי הזה אינו הכרחי ח\"ו כ\"א הוא גילוי רצוני שכך הוא רצונו ית' להיות גילוי אור כו', אמנם ענין הגילוי הוא להיות התגלות מן העצמות כו'. וי\"ל שזהו בחי' אור שנברא ביום ראשון דאי' בגמ' חגיגה די\"ב ע\"א ואור ביום ראשון איברי והכתיב ויתן אותם אלקים כו', ומתרץ כר\"א דאר\"א אור שברא הקב\"ה ביום ראשון אדם צופה בו מסוף העולם עד סופו כיון שנסתכל הקב\"ה כו' עמד וגנזו כו', ונודע דביום הראשון בגימ' כתר והיינו בחי' האור שלמעלה מהשתל', והי' אדה\"ר מביט בו מסוף העולם כו', דבמדרי' זו לא יש חילוקי מדרי' ומאיר בכל העולמות בשוה כו' וכמשי\"ת. ובזח\"ג דר\"ד ב' אי' נהורא קדמאה דברא קוב\"ה הוה נהיר עד דלא הוו עלמא יכול למסבלי' כו', והיינו שאינו בערך העולמות והכלים לקבל אור זה בבחי' אור פנימי כו', וענין עמד וגנזו כ' בעה\"מ ש\"ו פי\"ט שנעשה בבחי' אור מקיף כו'.\n<b>ולפ\"ז</b> י\"ל דבשרשן באוא\"ס שלפה\"צ ענין ויתן אותם אלקים כו' שהוא אור השמש להאיר הוא מה ששיער אוא\"ס להאיר העולמות, והו\"ע הע\"ס הגנוזות שמשם נמשך אור הקו שבא במדה ומשקל לפ\"ע העולמות כו', והאור שנברא ביום הראשון הוא בחי' האוא\"ס הבל\"ג שהוא רק בבחי' גילוי מן העצם, ואינו בא בבחי' מדה וגבול לפ\"ע העולמות שאין בו חילוקי מדרי' ומאיר בכולם בשוה, ואינו בבחי' התלבשות פנימי בכלים כ\"א בבחי' אור מקיף כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש נחמו נחמו עמי, ופרש\"י נחמו אתם נביאי נחמו את עמי. דהנה ידוע דכל נבואה הוא מנו\"ה דאצי', ונבואת ישעי' שהיתה מנו\"ה דברי' היינו התלבשות אצי' בבריאה ויחזקאל ביצי' כו' ונבואת משה הי' מאצי' עצמו כו', וכ\"ז הוא בבחי' אור פנימי דהיינו מבחי' ע\"ס דאצי' כו'. אמנם ידוע דבביהמ\"ק הי' גילויים מלמעלה מאצי', וכמ\"ש במ\"א בענין הג' דיורים שהי' בבמקד\"ש דבקדה\"ק הי' גילוי אוא\"ס שלמע' מאצי' כו', ובד\"כ הי' מאיר שם אוא\"ס הסובב בבחי' גילוי ממש כו', וזה\"ע העשרה נסים שהיו בבהמקד\"ש כו' וכמ\"ש במ\"א. וזהו דבסילוק השכינה בזה\"ג אמרו בגלותא קוב\"ה סליק לעילא"],[3601330237,"ולעילא דלעילא הוא בחי' בינה ולעילא בחי' הכתר כו'. וזהו לקתה בכפליים היינו סילוק האו\"פ והאו\"מ כו', וע\"כ בהנחמה אמר ב\"פ נחמו. דהנה כתי' כאיש אשר אמו תנחמנו כן אנכי אנחמכם, פי' אשר אמו תנחמנו הוא ההמשכה מבחי' בינה שמשם עיקר התחלת ההשתל' דהיינו גילוי בחי' אור פנימי, כן אנכי אנחמכם בבחי' גילוי או\"מ שהוא האור שבבחי' א\"ס ממש כו', וזהו נחמו אתם הנביאים בגילוי הנבואה שהוא גילוי האצי' כו'. ויש עוד נחמה שלמע' מזה והוא מבחי' עצמות א\"ס הבל\"ג, ועז\"א נחמו את עמי בחי' אנכי אנחמכם כו'. וזהו דברו על לב ירושלים וקראו אלי', דברו על לב הוא בחי' או\"מ וקראו אלי' היא בחי' או\"פ וכמ\"ש בלקו\"ת בהביאור הב' דוידעת. וי\"ל דהנה לעתיד שיהי' המקיף בבחי' פנימי ממש, וכמ\"ש במ\"א בענין שמו במחול שיהי' התחברות המקיף והפנימי כו' (וי\"ל שזהו מה שגם הנחמה העליונה היא ע\"י הנביאים כו'), וזהו דברו תחלה ואח\"כ קראו אלי' שיאיר בבחי' פנימי ממש כו'. וזהו כי מלאה צבאה בחי' או\"פ כי נרצה עונה בהמשכת או\"מ דמשם הוא סליחת עוונות כידוע ומבואר\nבמ\"א. וזהו נחמו נחמו עמי נחמו אתם נביאי בגילוי הנבואה שהוא המשכת האו\"פ, ועוד נחמו את עמי בבחי' נחמה העליונה דאנכי אנחמכם בהמשכ' גילוי האו\"מ שיאיר בפנימיות ממש. וזהו דברו על לב ירושלים וקראו אליה בבחי' או\"פ כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ועוי\"ל דהנה נת' דאמצעית האצי' הוא בשביל ההתהוות וגם בשביל הגילוי, וזהו בבחי' ז\"ת וג\"ר, גרמוהי וחיוהי, וכמו\"כ הוא גם בשרשי האורות בחי' אצי' דכללות, אמנם האו\"מ בשרשו הוא אור הא\"ס, והוא רק גילוי העצם, וכמו מראה וגוון, ולא כמו אור השמש, ושייך גם בלא עולמות, והוא האור דיום ראשון שגנזו להיות רק בבחי' או\"מ. וע\"פ הנ\"ל ית' פסוק נחמו נחמו עמי.</span>"],[3601330238,"<h3>בס\"ד. ש\"פ עקב, תער\"ב</h3>\n<b>ועתה</b> ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה כו', והקשו בגמ' אטו יראה מלתא זוטרתי היא, ותי' אין לגבי משה מלתא זוטרתי היא. וידוע הקושיא ע\"ז והלא מעמך כתי' ומהו התי' דלגבי משה מלתא זוטרתי היא כו', ובגמ' דברכות אי' תניא ר\"מ אומר חייב אדם לברך מאה ברכות בכל יום שנאמר ועתה ישראל מה ה' אלקיך שואל מעמך א\"ת מה אלא מאה, וצ\"ל מהו שייכות דמאה ברכות לזה דמה ה\"א שואל מעמך כ\"א ליראה כו'. גם מה\"ע א\"ת מה אלא מאה והלא כתי' מה כו'. ולהבין כ\"ז יש להקדים משנת\"ל דכללות ענין הע\"ס גם בשרשם ומקורם הראשון באוא\"ס שלפה\"צ הוא ההשערה להאיר בעולמות, והיינו שאין זה בבחי' גילוי מן העצם כ\"א להאיר את העולמות כו', וע\"כ באים במדה ובמשקל ובבחי' התלבשות בכלים ובבחי' התחלקות דמעומ\"ט, הן במדידת האורות והן במדידת"],[3601330239,"הכלים כו'. ועיקר ענין ההתחלקות ניכר בהם בהתלבשותם בהכלים שנעשים בבחי' מציאות דבר כו', אבל האור שבבחי' א\"ס ובבחי' בל\"ג הנה בשרשו ומקורו לפני הצמצום אינו בכדי להאיר בעולמות רק בבחי' גילוי מן העצם כו', וע\"כ אין בו התחלקות בבחי' מדה ושיעור בעצם, וגם כמו שמאיר בעולמות אינו בא בבחי' התלבשות והתחלקות רק בבחי' או\"מ שמקיף לכולם בשוה כו'.\nמט) <b>וביאור</b> הענין הוא דהנה כתי' קדוש כו' ה' צבאות מלא כל הארץ כבודו, ות' זיו יקרי' שמה שנמשך ומתלבש בעולמות הוא בחי' זיו והארה לבד כו', דעצמות אוא\"ס קדוש ומובדל וכמ\"ש והקדוש בשמים ובארץ שאינו בגדר התלבשות בעולמות כ\"א רק הארה כו'. ובזה הוא הביטול של השרפים והרצוא שלהם שרוצים להכלל באוא\"ס ב\"ה, ע\"י השגתם שמשיגים איך שכללות האור והחיות המאיר בעולמות ה\"ז רק הארה לבד ועצמות אוא\"ס קדוש ומובדל כו', וביותר שמהשגת הזיו וההארה ה\"ה משיגים את ענין ההפלאה דאוא\"ס איך שהוא מופלא ומרומם מאד, ומשיגים ג\"כ אופן ההפלאה דאוא\"ס כו', ועי\"ז הן בבחי' רצוא להכלל בעצמות אוא\"ס ב\"ה וכמ\"ש מי לי בשמים כו', והיינו שאינם רוצים לישאר בההארה כ\"א להכלל בעצמותו ית' כו'. הרי שכללות האור שבעולמות הוא רק הארה לבד, וכמ\"ש כי נשגב שמו דגם בחי' שמו הוא נשגב ומרומם רק הודו וזיוו על ארץ ושמים כו'. ובנש\"י כתי' וירם קרן לעמו דקרן הוא המשכת העצמיות, והיינו שע\"י תומ\"צ נמשך להם בחי' עצמות אוא\"ס ב\"ה, אך מה שנמשך בעולמות הוא רק\nהארה לבד כו'. ולפעמים כתיב את השמים ואת הארץ אני מלא דאני מורה על עצמות כו', וה\"ז סותר לכאו' למ\"ש מלא כה\"א כבודו שהוא הארה לבד כו', וכתיב הן השמים ושמי השמים לא יכלכלוך כו', וזה סותר לכאו' למ\"ש אני מלא כו'. וידוע הענין בזה דמ\"ש אני מלא אין הכוונה שבא בבחי' התלבשות פנימי ממש, שהרי אומר את השמים ואת הארץ אני מלא דשמים וארץ הן בשוה, והרי בהאור וחיות פנימי א\"א להיות בשוה, וכמשנת\"ל מפ\"ב עד כאן דהאו\"פ בא בבחי' התחלקות בעולמות וכלים באופן האור והגילוי שמחולקי' המה במעלתן ומדריגתן כו', וכמ\"ש אף ידי יסדה ארץ וימיני כו' נטה ימינו וברא שמים כו', הרי בשמים הגילוי יותר מבארץ כו', וכתי' אני אענה את השמים והם יענו את הארץ כו', הרי ההמשכה בארץ הוא ע\"י השמים כו', והו\"ע סדר ההשתל' שנמשך ממדרי' למדרי', וכמו בעו\"ע שהעלול מקבל ע\"י אמצעית העילה דוקא לא מהעצמי כו' (וממילא גם העילה אינו מקבל מן העצמי כ\"א ג\"כ מהארה שלמע' ממנו כו'). וכאן אומר את השמים ואה\"א אני מלא שהכל מקבל מבחי' העצמות כו', א\"כ מובן שאין זה\nבבחי' התלבשות פנימי כ\"א בבחי' מקיף כו'. ומ\"ש אני מלא הוא מפני שהאור מקיף ג\"כ בא בתוך כל העולמות בפנימיותם, וכמ\"ש בסש\"ב פמ\"ח דסובב אין פי' שהוא סובב ומקיף מלמעלה דבאמת הוא בתוך כל נברא בתוכיותו ופנימיותו רק שאינו מתצמצם לפ\"ע הנברא להיות בו בבחי' תפיסא והתלבשות ממש כו', וזהו שא' איהו תפיס בכולהו עלמין ולית מאן דתפיס בי' איהו תפיס בכולהו עלמין שנמצא בתוכם ופנימיותם והוא עיקר החיות שלהם כו' כמ\"ש בסש\"ב שם, ולית מאן דתפיס בי' לתפוס ולהשיג באוא\"ס ב\"ה. וזהו ג\"כ מ\"ש הן השמים ושמי השמים לא יכלכלוך להיות בבחי' כלי לאוא\"ס ב\"ה להיות בבחי' התלבשות פנימי כו', וע\"כ הוא בשמים"],[3601330240,"ובארץ בשוה, משום דאור המקיף אין בו בעצמו התחלקות מדרי', ומה שנמשך בעולמות אינו בבחי' התלבשות פנימי אור בכלי וע\"כ הוא בכל העולמות בשוה כו'. ויובן זה עד\"מ הרצון שבנפש דעם היות שהוא ג\"כ כח מהנפש מ\"מ ה\"ה חלוק מכל הכחות בזה שאינו בבחי' מציאות דבר, והיינו שאינו מציאות לעצמו חוץ מהנפש כו'. דהנה כל הכחות ה\"ה בבחי' מציאות לעצמן חוץ מעצמות הנפש, וכמו כח השכל שהוא להשכיל ולהתחכם בכל דבר שכל וחכ', ה\"ה במציאות לעצמו שאינו עצמות הנפש והוא מציאות שכל וחכ' כו', והגם שהנפש הוא המתחכם, ה\"ז שהנפש מתחכם בכח השכל שבו שהכח אינו עצמות הנפש כו'. משא\"כ הרצון אינו מציאות לעצמו חוץ לעצמות הנפש, שהרי הרצון הוא רק הטיית והמשכת הנפש לאיזה דבר לא בבחי' מציאות דבר לעצמו כו'. ולכן בכל הכחות גם כשהנפש מסתלקת מהם נשאר מהם איזה דבר וכמו בכח השכל כשמשכיל איזה ענין הרי גם כשהנפש מסתלקת מהענין נשארה ההשכלה אצלו, ומכ\"ש כשמשפיע השכל לזולתו או כשבא בכתב ונחקק בספר הרי נשארה לעולם, וגם בעצמו נשארה ההשכל' גם כשמסתלק מהענין, ובכל\nעת יכול לזכור עלי' מפני שנשארת במוחו כידוע (וגם דבר הנעלם לגמרי נשאר ממנה רשימה במוח וכידוע בענין החלומות שהן מהרהורי דיומא גם במשך זמן רב כו'). וכן הוא במדות שנשארה ההטבה וכה\"ג, ואין הכוונה על ההטבה בפו\"מ (דהיינו ההשפעה הגשמיות שמשפיע לו), כ\"א הכח רוחני שבזה, וכמו מה שנותן לו בסבר פנים יפה ומפייסו שארז\"ל והמפייסו בי\"א כו', דהפיוס עושה הגבהה בהמקבל, דהגבהה זו נשאר גם אח\"כ כו', וכן הוא בגבו' כו'. הרי מכל הכחות נשאר דבר מה, דמפני שהן בבחי' מציאות לעצמן לחוץ מהנפש ע\"כ גם כשהנפש מסתלקת מהם נשאר מהם דבר כו', אבל ברצון אינו כן דכשרוצה איזה דבר הנה כשמסתלק הנפש מזה לא נשאר כלום, לפי שהרצון הוא רק הטיית והמשכת הנפש, וע\"כ כשהנפש מסתלק מזה לא נשאר מאומה כו'. והיינו לפי שכל הכחות הן במציאות דבר בעצמן ובפעולת הכח הוא שנעשה דבר מה (ואין הכוונה שנעשה איזה דבר ממשי שהרי אין זה בחיק הנבראים כלל כו' (והתהוות איזה דבר ממשי זהו דוקא מבחי' אין, וכמא' דהתהוו' הגשמי מהרוחני אין לך בריאה יש מאין גדול מזה\nכו'), רק הכוונה שנעשה דבר רוחני כפי מהות הכח ההוא כו'). וכמו בפעולת כח השכל נעשה מציאות השכלה ובמדות נעשה ההטבה וכדומה, והיינו להיותם בבחי' מציאות בעצם כו', משא\"כ ברצון אינו נעשה דבר לפי שאינו בבחי' מציאו' בעצם רק גילוי מן העצם והוא בבחי' אין בעצם כו', וע\"כ בעת שישנו להרצון לא יש איזה מציאו' דבר וכשמסתלק לא נשאר מאומה כו'. ולמעלה שכל ההתהוות הוא מהרצון וכמ\"ש כל אשר חפץ ה' עשה, הנה אם הי' הרצון מסתלק ח\"ו הי' אין ואפס לגמרי כו', דבסילוק האורות פנימיים הגם שנעשה העלם מ\"מ נשאר קצת כו'. וכידוע בענין דכד אנת תסתלק מנייהו כו' דמ\"מ נשאר בהעלם כו', וכמ\"ש במ\"א על מאמר הזה, גם י\"ל שז\"ע הספיחים דאי' בזהר ע\"פ אור זרוע לצדיק אור שנזרע כבר, וקאי על זה\"ג דגננא לא אעיל בגינתא, ומ\"מ ישנם יחודים גם בזה\"ג והן מהאור שנזרע כבר כו' וכמ\"ש במ\"א באורך. משא\"כ הרצון אם הי' מסתלק ח\"ו הי' הכל מתבטל לגמרי כו'. וזהו דבר\"ה שאז חוזר הכל לקדמותו וצריכים להמשיך רצון חדש למלוכה ולבריאת והתהוות העולמות כו', הנה ידוע שהסילוק הוא רק בפנימיות ולא בחיצוני', שאם הי' הסילוק גם בחיצוני' הי' הכל אין ואפס ח\"ו. וכ\"ז הוא לפי"],[3601330241,"שהרצון הוא בבחי' גילוי מן העצם והוא בבחי' אין בעצם כו'. ובזה יובן איך שענין אין עוד הוא במציאות היש דוקא, דהתהוות היש הוא מבחי' הרצון כמ\"ש כל אשר חפץ ה' עשה, והרצון הוא בחי' אין, ובפעולתו הוא ג\"כ שלא נעשה מציאות דבר בפ\"ע, וע\"כ כשמסתלק הרצון מתבטל הפעולה לגמרי, וא\"כ גם בעת היותו הרי באמת הוא בחי' אין ממש, לא בבחי' מציאות דבר כלל כו'. ובמ\"א מבו' דלהיות שההתהוות הוא מעצמות א\"ס, דהוא לבדו בכחו ויכולתו להוות יש מאין ואפס המוחלט כו', וע\"כ כמו שהעצמות הוא נמצא בבחי' בלתי מציאות נמצא, כמו\"כ ההתהוות הוא בחי' מציאות שבאמת אינו בבחי' מציאות כלל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וביאור הענין דהנה אוא\"ס הסובב הגם דאת השוה\"א אני מלא ה\"ה קדוש ומובדל, ויובן עד\"מ הרצון שמובדל מכל הכחות שהן בבחי' מציאות חוץ לעצמות הנפש, והוא שהנפש משכלת בכח השכל ומתעורר בכח המדות, ובפעולתן הוא שנעשה דבר כמו השכלה או הטבה, וע\"כ גם כשמסתלק הכח נשארה הפעולה, אבל הרצון הוא רק הטיית הנפש, והוא אין בעצם, וע\"כ כשמסתלק הנפש לא נשאר מאומה, ולמעלה הוא דמאו\"פ נשאר גם כשמסתלק וכמו הספיחים, אבל אם הי' מסתלק ח\"ו הרצון מהעולמות הי' אין ואפס, ולכן בר\"ה הסילוק רק בפנימיות.</span>\n<b>נו\"ן)</b> וזהו שהרצון אינו בא בבחי' התלבשות בכלים והיינו שלא יש כלי מיוחדת באיברי הגוף ששם מתלבש הרצון, כמו כל הכחות שיש להם כלים מיוחדים כמו אור השכל שחומר המוח הוא כלי לאור השכל שנתפס ונתלבש בו כו' וכמשנת\"ל פ\"ב, משא\"כ הרצון אין לו כלי מיוחדת כו'. והראי' שהרי הרצון פועל בכל האיברים גם באיברים החיצונים תומ\"י בלי שום שהיית זמן, וכמו כשעולה ברצונו לנענע רגלו או לפשוט ידו ה\"ה עושה מיד, ואם הי' להרצון כלי מיוחדת והיינו שהי' בבחי' התלבשות בהכרח הי' צ\"ל שהיות זמן בפעולתו בשארי האיברים והכחות. וכמו השכל שנמשך ג\"כ בכל הכחות גם בכח התנועה שביד ובכח ההילוך שברגל כו', אך לפי שהוא כח שבבחי' תפיסא והתלבשות הרי גם פעולתו היא בבחי' התלבשות, וע\"כ בהכרח שיהי' בזה שהיית זמן, הן מצד השכל גופא צ\"ל שהיית זמן דהיינו השערה בשכל באיזה אופן יהי' המשכת אור השכל בהאבר והכח הפרטי ההוא, וגם בהכח הפרטי שנמשך שם השכל צ\"ל הכנה שיקבל את ההארה השכלית, להיות שבא בו בבחי' אור פנימי וממילא בהכרח שיהי' בו הכנה והוא\nשיהי' כלי לקבל כו', והו\"ע האולפנא והלימוד שהשכל מלמד את הכח ההוא להיות כלי לקבל אור השכל כו'. וכמו במלאכת הציור הרי יש בזה לימוד בעשיית הקוין וכה\"ג, לבד ההשכלה בגוף ענין הציור בהדבר היוצא ממנו, שגם מי שיש לו חוש בציור צריך לימוד בזה, ויש בזה השערת השכל איך שיהי' תנועת היד, וגם הכנה בכח התנועה איך להתנענע כפי השערת השכל כו', דכ\"ז צריך שהיות זמן ואימון ידיו ורגילות כו'. וכמו בכל משפיע ומקבל צריך להיות השערה בהמשפיע איך להשפיע שיהי' לפ\"ע המקבל, וצ\"ל הכנה בהמקבל שיוכל לקבל את השכל, וג\"ז הוא מן המשפיע שהמשפיע מלמד את המקבל איך לקבל דבר שכל (ווי צוא נעמען א ענין), גם יש בזה סדר והדרגה דמתחלה מלמד אותו שכל הנמוך במדרי' והולך מן הנמוך אל הגבוה כו'. וכמו\"כ הגדלת האדם בשכל ומדות שבא במשך השנים וכמו ימים ידברו ורוב שנים כו', ותכלית ההגדלה הוא בעשרים שנה כו' כנודע, וכן המשכת המוחין במדות"],[3601330242,"להגדיל המדות הוא במשך שנים דוקא כו'. וכמו\"כ כל השפעת השכל צ\"ל בשהיית זמן דוקא, וגם המשכת השכל בא בסדר השתל' בהתלבשות הכחות זב\"ז, דהשפעת השכל צריך להיות דרך מעבר המדות, והיינו שירצה להשפיע או שירצה בהדבר שיעשה וכה\"ג וכמ\"ש במ\"א, והגם שזהו רק בבחי' מעבר ה\"ז ג\"כ התלבשות שעי\"ז דוקא יוכל להיות התלבשות השכל בהכח התחתון כו' וכמ\"ש במ\"א. משא\"כ ברצון שאינו תלוי במשך השנים הן בהגדלתו בעצמו והן בהשפעתו בשארי הכחות, שהרי הרצון יש בו תומ\"י ואינו תלוי בשנים כו', וכשיגדל מתעלם הרצון זהו מפני התגלות הכחות פנימיים, דכאשר הכחות פנימיים מתגלים יותר מתעלמים הכחות עצמיים שהן הכחות מקיפים כו' וכמ\"ש במ\"א, ופעולת הרצון הוא תומ\"י בלי שום שהיית זמן כלל ואינו בא בסדר והדרגה ובסדר השתל' כו'. וכ\"ז הוא מפני שכל הכחות הן כחות פנימיים שהן בבחי' התלבשות בכלים דוקא, וכן פעולתם הוא בבחי' התלבשות פנימי, וע\"כ תלוי התגלות הכח בהגדלת הכלי שיוכל להיות בו בבחי' או\"פ, והוא במשך הימים דימים ידברו כו'. וזהו ג\"כ שבפעולתו בשארי כחות\nואיברים צ\"ל שהיות זמן דהיינו ההשערה והכנה הנ\"ל, מפני שהוא בבחי' או\"פ (והרי גם הכח במקומו צריך השערה והכנה, דהיינו הכנת הכלי והגדלתה במשך השנים, וגם איכותה ודקותה וכמו בחומר המוח כשהוא בדקות יותר הוא בבחי' כלי ביותר כו', וכן צ\"ל השערה בכח השכל להיות מאיר ומתלבש בבחי' פנימי כו', וכ\"ש שהוא כן בהתלבשות הכח הזה כמו כח השכל בשארי הכחות כו'). וזהו ג\"כ הסיבה שצ\"ל בסדר והדרגה דוקא מפני שע\"י התלבשות דוקא (שהו\"ע המיעוט וההגבלה שבא ממדרי' למדרי') יוכל להתלבש בכח שהוא תחתון לגבי' כו'. אבל הרצון אינו כח פנימי כ\"א כח עצמי דהיינו התגלות הנפש, כי אינו בא בהתלבשו' בעצמו ובפעולתו, וע\"כ הוא פועל בכל האיברים והכחות בשוה ובלי שום שהיית זמן כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו שכל הכחות באין בהתלבשות בכלים ולכן הגדלתן תלוי בשנים, ובהתלבשות כח עליון בתחתון צריך שהיית זמן, דהיינו השערת הכח הנמשך והכנת המקבל, והו\"ע האולפנא והלימוד, וכמו במשפיע, ובאים בסדר והדרגה דוקא, אבל הרצון אינו תלוי בשנים, ובא בכל הכחות בלי שהיות זמן ובלי סדר והדרגה, והוא מפני שאינו בהתלבשות בכלי.</span>\nנא) <b>והנה</b> אופן ההמשכה דהרצון בכל הכחות והאברים הוא שעצמותו נמשך לא רק הארה לבד, כמו בשארי כחות דמה שנמשך בכח התחתון הוא רק הארה לבד. וכמו השכל שנמשך ג\"כ בכל האיברים גם ביד וברגל הרי אין עצמות אור השכל נמשך ביד וברגל כ\"א רק הארה חיצוניו' לבד כו', וכמשנת\"ל פ\"ב דמה שמתלבש מהשכל בכח המעשה וההילוך הוא רק חיצוניות דחיצוניות בלבד מהשכל ועצמו' השכל הוא במוח שבראש כו'. והוא להיות שהמוח הוא כלי לאור השכל שהוא שם בבחי' התלבשו' ממש ומאיר שם עצמות השכל, ובשארי איברים שהן רק מקבלים מהמוח לא שהן בעצמם כלים אל אור השכל (ומ\"מ יש בהם הכנה לזה והוא המוח שבעצמות ובד\"כ הלחלוחיות והשמנוניות שבאברים), מאיר בהם רק הארת השכל וחיצוניותו לבד כו'. משא\"כ הרצון שאין לו כלי מיוחדת הנה אופן"],[3601330243,"המשכתו הוא שעצמותו נמשך בכל מקום כו'. ולכן אופן פעולת הרצון שפועל בכל האיברים והכחות הוא בדרך שליטה וממשלה, ולא כמו פעולת השכל שפועל ג\"כ בכל הכחות שאין זה בדרך שליטה, וכמו מה שהמוח שליט על הלב שאין זה בדרך ממשלה כ\"א בבחי' אור פנימי שפועל בהמדות שיהיו כפי הנהגת השכל כו' וכמשנת\"ל בפ' הנ\"ל, והוא ג\"כ ענין אולפנא ולימוד שהשכל מלמד ומנהיג את המדות כו'. ויש ג\"כ שהמוחין פועלים ביטול בהמדות דלהיות שהמוחין בעצם הם בחי' ביטול ה\"ה פועלים ביטול בהמדות ג\"כ (והעיקר הוא מבחי' החכ' כו' וכמ\"ש במ\"א). וזהו כאשר המדות אינם בהתגברות אז המוחין פועלים בהם הביטול, והיינו שהן כמו כלים אל המוחין, דכאשר המדות הן בהתגברות א\"א להמוחין לפעול בהם הביטול כ\"א כאשר אינם בהתגברות כו'. דהנה פעולת המוחין בהמדות היא בב' אופני', או שפועלים חלישות בהמדות, וזהו בבחי' חיצוני' המוחין והיינו המוחין השייכים אל המדות, דהארת המוחין מושג בהמדה שעי\"ז נעשה חלישות המדה להתנהג כפי המוחין כו'. או שהמדות מתבטלים ממילא ע\"י המוחין שזהו דוקא\nבבחי' פנימיות המוחין (והעיקר בבחי' החכ' כו'), שמאיר האור גם בהמדות ולהיותן בעצם בחי' ביטול ה\"ה פועלים ביטול בהמדות כו' ועמשית\"ל פ', והיינו דוקא כשהמדות הן באופן כזה שנרגש בהם אור המוחין וה\"ה מתבטלים מפני האור והגילוי כו'. דכ\"ז הוא בדרך התלבשות לא בדרך שליטה וממשלה (רק שבאופן הב' הנ\"ל אינו בדרך התעסקות כו'), דפעולה שבדרך שליטה אין זה שיש להם איזה ערך ושייכות שיהי' נרגש אור הפועל כו', כ\"א מפני שהוא כח עליון וחזק ה\"ה פועל מצד התוקף שבו כו', ובמוחין ומדות אינו מצד התוקף כ\"א מצד הערך ושייכות אם בחיצוני' המוחין והמדות בבחי' חלישות או בפנימיות שלהם בבחי' הביטול כו'. ויש שמוח שליט על הלב גם על פנימיות הלב והיינו בבחי' התגלות והתגברות המוחין ביותר, וזה במי שהוא שכלי בעצם שכל עניניו וכל הנהגותיו הם רק שכליים, הנה בהתגלו' אור המוחין ה\"ז שולט גם על פנימיו' הלב שלא יהי' התפשטות בהמדות גם בתוקף ההתפעלות שלהם, שזהו ג\"כ בדרך התלבשות, דלכן מי שאינו שכלי בעצם (דאור המוחין אינו בהתגלות אור עצמי והמדות\nאינם במדרי' מוחין כו'), א\"א לו להתגבר על תוקף התפעלות המדות כו'. משא\"כ פעולת הרצון הוא בדרך שליטה שלהיותו כח עליון ותקיף ה\"ה פועל הביטול בכל הכחות שמתבטלי' מפני הרצון כו'. ויובן זה יותר בהתעלמות הכחות שהרצון בכחו לפעול שיתעלם איזה כח לגמרי שאין זה בכח השכל שאין בכחו להעלים איזה כח לגמרי, כ\"א להגבילו שלא יתפשט רק במקצת ומגבילו בפרט זה ומניח ההתפשטות בפרט אחר, ובכח הרצון הוא להעלים לגמרי. וכמו שבהתפשטות והתגלות הכחות הרי בשכל הם בהגבלה וכמו בהתהוות המדות מהשכל ה\"ה בהגבלה, וע\"י הרצון יהי' ההתגלות בלתי מוגבלת כו', כמו\"כ הוא בהתעלמות הכחות שע\"י השכל א\"א להיות ההתעלמות לגמרי, וע\"י הרצון יהי' ההתעלמות לגמרי כו'. וכמו באאע\"ה שכבש את רחמיו מעל בנו יחידו, דבכדי להעלים מדה טבעית לגמרי אין זה בכח השכל כ\"א בכח הרצון, שהי' נתון ומסור לרצה\"ע שע\"י הרצון האלקי כבש את רחמיו כו'. וכן הוא בענין המס\"נ שזהו בהכרח או ע\"י התעלמות כל הכחות לגמרי שלא ירגיש א\"ע כלל, או ע\"י התגלות יתירה דכל הכחות שבשביל אלקות הכל\nכדאי כו', שזהו רק בכח הרצון לבד כו'. וכ\"ז הוא לפי שאופן התגלות הרצון הוא שעצמותו מתגלה ע\"כ הוא פועל"],[3601330244,"בדרך שליטה בבחי' תוקף הכח שבו, הן התעלמות הכחות לגמרי והן התגלות הכחות בהתגלות יתירה (כמו במס\"נ וכן בד\"כ בהתגלות הכחות שע\"י הרצון שיכול להיות בלי גבול וכמו במקום שלבו חפץ כו'). וזהו ג\"כ הטעם מה שכללות תנועת האיברים הוא ע\"י הרצון דוקא, ומפני מה אין התנועה בהאיברים מצ\"ע, היינו מהחיות המלובש בהם שיש בהם ההטבעה לתנועה דכל חי מתנענע כו', ומ\"מ לא ינועו מעצמם ממזג החיות שבהם כ\"א ע\"י הרצון דוקא, דכאשר עולה ברצונו לנענע ידו ורגלו אז דוקא מתנענע (והתנועה עצמה היא מהכח המלובש בהאברים, אבל להיות התנועה הוא ע\"י הרצון דוקא כו'). וגם תנועה פתאומית שבאה בלי בחירה גם היא באה מן הרצון דוקא ונק' תנועה רצונית כו', גם בעת השינה התנועה היא רצונית ולא נפשיות כו', שזהו מצד הדמיון שנשאר בגידי הרצון גם בעת השינה כו', וההסכם בכל דבר שעושין קודם השינה פועל גם בעת השינה כו' (ולכן האדם מועד לעולם בין ער בין ישן, לפי שתנועתו היא רצונית כו'), ובלתי הרצון לא תהי' התנועה, וכידוע בחולי מאניע שהוא שמסתלק הרצון מן התנועה\nאז ינוח כאבן דומם בלי שום תנועה, הגם שיש בו כח התנועה החיונית כו'. והענין הוא שענין התנועה הוא בדרך שליטה וממשלה על האיברים והכחות שיתפשטו או יתכווצו כו', והממשלה הזאת היא בכח הרצון דוקא, דהאור והחיות המתלבש בהאיברי' אין בהם הכח הזה להכריח את האברים להתנענע כ\"א הרצון, לפי שהוא כח עצמי שמובדל בערך מהכחות יש בו כח השליטה והממשלה על התנועה החיונית לפשוט או לכווץ כו'. וגם מה שהרצון פועל גילוי הכחות גם גילוי אור השכל ה\"ז ג\"כ בדרך ממשלה כו', דמה שארז\"ל לעולם ילמוד אדם במקום שלבו חפץ הוא שהרצון גורם ממילא פתיחת אור השכל שישכיל ויתחכם בהענין, דמפני העילוי של הרצון על השכל ע\"כ בדבר שרצונו בו נמשך גילוי אור השכל ממילא כו', ואין זה כמו השכלה הבאה ע\"י יגיעה שזהו מה שהזדככות הכלי מביא וממשיך גילוי אור השכל ע\"י שנעשה כלי לזה כו', אבל הרצון פועל בדרך כח עליון להיות גילוי אור השכל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה אופן המשכת הרצון הוא שעצמותו נמשך, וע\"כ פעולתו הוא בדרך שליטה, דפעולת המוחין במדות להנהיגם ולעשות בהם הביטול, הוא בבחי' קירוב, ולכן תלוי במעלת המוחין ואופן התגלותם, ובמעלת הנפעל שהן המדות, אבל הרצון פועל בדרך כח עליון, הן בהתגלות הכחות, והן בהתעלמות הכחות, ומשו\"ז יכול להיות התעלמות הכחות לגמרי ע\"י הרצון, וגם ההתגלות הוא בתוקף, ובדרך ממילא שלא ביגיעה כמו התגלות השכל מעצמו שהוא ביגיעה, ולכן גם תנועת האברים, הגם שהיא מהחיות המלובש בהם, ה\"ז תלוי בכח הרצון מפני שזהו בדרך שליטה שזהו בכח הרצון דוקא.</span>\nנב) <b>וכ\"ז</b> הוא מפני שעצמות הרצון נמשך לפעול בכל אבר ובכל כח (ואין הכוונה שעצם הרצון ממש נמשך בזה, דבאמת כללות ההמשכה הזאת היא רק הארה כו', רק הכוונה היא שאין זה הארה הבאה בדרך השתל' ממדרי' למדרי', כמו בכחות פנימי' המתלבשים בכלים דעצמות הכח הוא בהכלי שמתלבש בה, ומה שנמשך לפעול בכח אחר הוא רק הארה כנ\"ל פנ\"א בפעולת השכל, ואם הי' ברצון ג\"כ באופן כזה לא הי' בו כח השליטה והממשלה כו', אבל להיות שהמשכת הרצון אינו באופן כזה שבא בסדר והדרגה דהשתל' הכחות, כ\"א שעצמות הארתו"],[3601330245,"נמשך בכל כח כו'), ע\"כ יש בו כח השליטה והממשלה לפעול בכל הכחות ופועל בכולם בשוה כו'. ומובן ג\"כ דהמשכת הרצון שנמשך בכל איברי הגוף ופועל בהם אין זה בבחי' התגלות ממש, כמו התגלות האור פנימי להיות בבחי' התערבות והתאחדות עם הכחות, מאחר שאינו בבחי' אור וכלי וההמשכה הוא מעצמות הרצון שאינו בגדר התגלות ממש, כ\"א זהו מה שהעצמות נמשך ונמצא הוא בהאבר והכח שפועל בו, אבל הוא בבחי' מקיף לבד שאינו מתחבר עם הכח ההוא כו'. והגם שא\"א לומר שאינו מתחבר כלל שה\"ה פועל בהם, ואם הי' בבחי' ריחוק לגמרי איך הי' פועל בהם, וגם לא הי' נופל בזה שם המשכה כלל, והרצון ה\"ה נמשך עכ\"פ בהכחות לפעול כו'. הענין הוא שאינו בבחי' התחברות כמו אור וכלי שהכלי תופסת בהאור ופועל בו שינוי להיות כמו הכלי, וגם שחיזוק והגדלת הכלי גורם תוס' האור והגילוי כו', משא\"כ הרצון שאין האיברים והכחות תופסים בו לפעול בו איזה שינוי ע\"י ההמשכה בהם ולא תוס' וריבוי ע\"י הגדלת האיברים כו'. ועם היות שהרצון תופס בהכחות ופועל בהם, מ\"מ הכחות אינם תופסים בהרצון\nלפעול בו איזה שינוי, מפני שאינו בא בהתלבשות ממש כ\"א בבחי' הבדלה כו', ולכן הוא פועל בכל הכחות בשוה מן כח השכל שבראש עד כח ההילוך שברגל, הן בתנועה חיצוניו' שפועל ברגל כמו בהראש וכן בהתגלות הכחות כו' וכמ\"ש כ\"ז באריכות בד\"ה יו\"ט של ר\"ה, רס\"ו (ולכאו' יש שינוי ברצון בתוספת וגרעון ע\"י הכחות פנימיים, דאנו רואין כאשר יש התגלות כחות הפנימיים אז מתגלה ג\"כ הרצון בתוס' אור, וכמו כשמשכיל איזה השכלה גדולה בכח שכלו ה\"ה אז מרוצה ביותר, וכן איש הטוב כשעושה טוב וחסד כו', וכמו\"כ הוא ע\"י תוס' חיות פנימי כמו ונשבע לחם ונהי' טובים, דכאשר הוא רעב ה\"ה מתרגז ומתכעס וע\"י השביעה נעשה טוב ומרוצה כו'. אמנם מה שהוא מרוצה אין זה התגלות הרצון כי הרי אין כאן עדיין איזה רצון שרוצה באיזה דבר רק מה שהוא מרוצה, וה\"ז רק בדרך סיבה שיוכל להיות איזה התעוררות כו'. ועיקר הדבר שייך זה לתענוג שלפי שמתענג בההשכלה או בההטבה וכה\"ג עי\"ז נעשה מרוצה כו', וה\"ז מה שהעונג ממשיך את הרצון לא הכחות מצ\"ע כו'). וכ\"ז הוא מפני שהרצון הוא גילוי\nמעצם הנפש שאינו בגדר התלבשות בכלים, וגם אין בו חילוקי מדרי' בעצם כ\"א הוא כח ואור פשוט, ע\"כ בהמשכתו בכל מקום שנמשך הוא שעצמות הכח נמשך בזה ואינו מתערב ומתאחד עמהם ופועל בכל הכחות בשוה כו'. והדוגמא מזה יובן באוא\"ס הסוכ\"ע שזהו בחי' רצה\"ע שאינו בא בבחי' התחלקות, וכמארז\"ל אל תהי יושב ושוקל במצותי' של תורה דקלות שבקלות וחמורות שבחמורות הכל שוין, הרי גם שיש קלות וחמורות מצד האו\"פ מ\"מ מצד הרצה\"ע שבהם הכל שוין כו', וכן גם בהחיוב דעשיי' המצוות הכל שוין, ואין זה כמו בתורה שיש בזה חילוקי מדרי' וכמו פנימיות וחיצוניו' שבתורה וכן בפרטי הענינים שבה כו'. גם בהחיוב דלימוד התורה אין הכל שוין דיושבי אהל החיוב שלהם לעסוק בתורה כל היום שעליהם נא' והגית בה יומם ולילה כו', ובעלי עסקים פ\"א שחרית ופ\"א ערבית כו'. משא\"כ הרצון דמצות עצם הרצון אין בו התחלקות מדרי' וגם בהחיוב בזה אין התחלקות כו', והיינו לפי שהרצון הוא בחי' גילוי העצמות לכן אין בו בעצם התחלקות ואינו בא בבחי' התחלקות כו'. והנה התגלות הרצון הוא ע\"י\nהמצות שהן רצה\"ע, והעיקר הוא ע\"י ההקדמה דאהבה דבכל מאדך שז\"ע עושין רצונו ש\"מ שממשיכי' גילוי הרצון כו', דע\"י המצות הגם"],[3601330246,"שנמשך הרצון ה\"ה בהעלם, וכמ\"ש בסש\"ב ע\"פ אני בער ולא אדע בהמות כו' שאין הרצון מורגש כלל כו'. ומ\"מ ג\"ז פועל להיות מצוה גוררת מצוה כמש\"ש, וגם כמ\"ש טוב טעם ודעת למדני כי במצותיך האמנתי שע\"י קיום המצות בבחי' אמונה פשוטה עי\"ז טוב טעם ודעת למדני כו'. אך בכדי שיהי' התגלות הרצון זהו ע\"י הקדמת האהבה דבכל מאדך כו', והתגלות הרצון הוא במצות מעשיות שאינו בבחי' כלי, כמו התורה שהיא בידיעה והשגה שזהו בחי' כלי כו', משא\"כ הרצון אינו בהתלבשו' בכלים כו' (ומ\"מ ה\"ז בא ג\"כ בבחי' הרגש פנימי כו'), וההתגלות היא בכל מקום, וכמא' נתאווה הקב\"ה להיות לו דירה בתחתונים שלמטה יהי' גילוי אור כו', וזהו דוקא בבחי' הרצון שאינו בא בהתלבשות בכלים והוא בכ\"מ בשוה כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ועתה ישראל כו' כ\"א ליראה כו', וידוע דיראה הו\"ע הביטול והנחת עצמותו, יר\"ע הוא בבחי' ביטול עצמי ויר\"ת בבחי' קבעומ\"ש כו' וכמ\"ש במ\"א. וכח זה הוא בנש\"י מצד עצמות נפשם שלמע' מטו\"ד כו', וע\"כ יש בהם בעצם בחי' הביטול כו', והאהבה עיקרה הוא ע\"י התבוננות והשגה אלקית שזהו בחי' או\"פ כו'. וזהו ועתה ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה דזה יכול להיות בכאו\"א מישראל, דמדת האהבה מה שתלוי' בהשגה הרי לא כאו\"א שייך לזה, ויש בזה הרבה חילוקי מדרי' באופן ההשגה כמה שביכולתו להשיג כו', אבל יראה שזהו מכח העצמי שבנפש הרי כל או\"א יכול להגיע לזה כו', וג\"ז בנקל יותר מהשגה פנימיות שלזה צריכים כלים ויגיעה בהזדככות הכלי כו', משא\"כ הביטול מצד עצם הנשמה ה\"ז בנקל יותר כו'. וזהו שאמרו מלתא זוטרתי היא, דבאמת הוא כן בכל ישראל, ואמרו אין לגבי משה כו', שהוא בחי' הדעת שבכאו\"א מישראל כו' כמ\"ש בסש\"ב, אבל באמת בנקל לכאו\"א לבוא לזה (והעיקר הוא כשלא יהי' עכ\"פ התגברות החומריות ביותר שמעלים על הכח העצמי\nוכמו פר\"ע ר\"ל וכה\"ג). וענין המאה ברכות הוא שיהי' התגלו' הרצון, וכמשנת\"ל שע\"י המצות נמשך הרצה\"ע אבל הוא בהעלם עדיין כו', וענין ברכת המצות הוא שיהי' גילוי הרצון ע\"י המצות כו', וכאשר ע\"י המצות הוא התגלות הרצון היינו שנמשך בבחי' פנימי כמו שהוא בעצם כו'. וזהו א\"ת מה אלא מאה דמאה הוא בחי' כתר כנודע, וא\"ת מה אלא מאה הוא שהאו\"מ יאיר בבחי' פנימיות כו' וכמ\"ש במ\"א. וכ\"ז הוא ע\"י הקדמת היראה בבחי' ביטול והנחת עצמותו כו'. וזהו ועתה ישראל כו' כ\"א ליראה שזה ביכולת כאו\"א מישראל מבחי' כחות המקיפים שבנפש שבכולם בשוה כו', וא\"ת מה אלא מאה דחייב אדם לברך מאה ברכות להיות גילוי הרצון שיאיר בגילוי בפנימיות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכ\"ז הוא מפני שעצמות הרצון נמשך בלי הדרגה, ומשו\"ז אינו בהתאחדות עם הכחות להיות נתפס בהם לפעול בו תוס' וגירעון (ומה שע\"י התגלות הכחות הוא מרוצה, הוא מהתענוג), והרצון תופס בהם לפעול עליהם, ולכן הוא בכולם בשוה, וכמו\"כ אוא\"ס הסוכ\"ע אינו בבחי' התחלקות, ולכן בתורה יש התחלקות, וחילוקים בחיוב הלימוד, והרצון דמצות הוא בלי התחלקות, והכל חייבים בזה בשוה וההמשכה במצות מעשיות, ועיקר הגילוי הוא ע\"י הקדמת בכל מאדך. ובזה ית' פסוק ועתה ישראל כו' כ\"א ליראה.</span>"],[3601330247,"<h3>בס\"ד. ש\"פ שופטים, תער\"ב</h3>\n<b>שופטים</b> ושוטרים תתן לך בכל שעריך כו', ושפטו את העם משפט צדק, ואי' במד\"ר משל למלך שהיו לו בנים הרבה והי' אוהב את הקטן יותר מכולם והי' לו פרדס א' והי' אוהבו יותר מכל מה שהי' לו, אמר המלך אני נותן את הדבר שאני אוהב לזה שאני אוהב. כך אמר הקב\"ה אני אוהב את ישראל מכל האומות שבראתי שנא' כי נער ישראל ואוהבהו, ומכל מה שבראתי אני אוהב את המשפט שנא' כי אני ה' אוהב משפט, אני נותן את הדבר שאני אוהב לזה שאני אוהב. הה\"ד שופטים ושוטרים תתן לך כו', אמר הקב\"ה בזכות המשפט אני משרה שכינתי בתוכם שנא' ויגבה ה' צבאות במשפט והאל הקדוש נקדש בצדקה, ובזכות המשפט אני גואל אתכם גאולה שלימה שנא' שמרו משפט ועשו צדקה כי קרובה ישועתי לבוא כו'. ומשמעות הענין דזה שאוהב את הקטן הוא לפי שהוא קטן, דלכן הביא ע\"ז פסוק כי נער ישראל ואוהבהו, דמשמע שהאה' היא לפי שהוא נער, דכללות ענין האהבה לישראל הרי נא' ע\"ז כמה פסוקים וכמו אהבתי אתכם אמר ה', ואוהב את יעקב, ומה שהביא פסוק כי נער ישראל משמע שזהו לפי שהוא נער כו', וצ\"ל מהו\nמעלת הקטן הלא לכאו' גדול הוא חשוב יותר. גם צ\"ל מהו שייכות ענין כי נער ישראל לענין המשפט שאני נותן המשפט לישראל לפי שהוא נער כו'. גם מה\"ע שבזכות המשפט אני משרה שכינתי כו' ובזכות המשפט נגאלים בגאולה שלימה מהו שייכות הענינים זל\"ז. גם מה\"ע ושפטו את העם משפט צדק כו'. ולהבין כ\"ז ילה\"ק משנת\"ל ההפרש בין הרצון לכל הכחות דכל הכחות הן במציאות לעצמן חוץ לעצמות הנפש והיינו שהן במציאות דבר בעצמן, משא\"כ הרצון שאינו במציאות לעצמו חוץ לעצמות הנפש שהוא רק הטיית והמשכת הנפש ובעצמו הוא בבחי' אין כו'. והיינו לפי שכל הכחות הן להיות בחי' כחות והרצון הוא רק גילוי מן העצם כו'. ולכן הרצון אין בו התחלקות בעצם, וכמו שמאיר בהאיברים והכחות אינו בא בבחי' התלבשות ובבחי' התחלקות שנמשך בכל מקום, והמשכתו הוא שעצמותו נמשך ופועל בכל מקום בשוה כו'.\nנג) <b>והנה</b> להבין הדוגמא מכ\"ז למעלה, צ\"ל תחלה ענין אוא\"ס. דהנה ידוע דאוא\"ס אין הכוונה אור של הא\"ס כ\"א שהאור הוא א\"ס, שאם נא' אור של הא\"ס הרי א\"ס קאי על העצמות, והעצמות אין לכנות רק בש' א\"ס כ\"א בשם אין לו תחלה שזה מעלה יתירה על א\"ס, דכל שאין לו תחלה ממילא אין לו תכלה, ועצמותו ית' שמציאותו מעצמותו הרי אין לו תחלה ממילא אין לו תכלה, אבל ענין הא\"ס אינו מחייב שלא יהי' לו תחלה דיכול להיות דהגם שאין לו תכלה מ\"מ יהי' לו תחלה. וזה באחת משתי פנים או בבחי' גילוי מן העצם שהוא כמו העצם וע\"כ אין לו תכלה כמו העצם, ויש לו תחלה שהרי הוא רק גילוי לבד מן העצם כו'. או גם בדבר שאינו כלל גילוי מן העצם לא יהי' לו תכלה, מצד שרצון הבורא כך הוא שלא יהי' לו תכלה, וכמ\"ש בפלח הרמון דכל קדמון נצחי ולא כל נצחי קדמון שרבים מן הנמצאים יהיו נצחיים ברצון הבורא ואין שום אחד מהם קדמון. וכמו שצבא מעלה קיימין באיש וצבא מטה קיימין במין, וכמ\"ש מרוב אונים ואמיץ"],[3601330248,"כח איש לא נעדר כו', וי\"ל דלולא החטא דעה\"ד היו גם צבא מטה קיימין באיש, ומ\"ש ועתה פן ישלח ידו ולקח מעה\"ח וחי לעולם זהו לאחר החטא, דמ\"מ אם הי' אוכל מעה\"ח הי' חי לעולם, ומפני שנעשה תערובות טו\"ר לא רצה הקב\"ה שיחי' לעולם לפי שיהי' ח\"ו קיום גם אל הרע, אבל לולא החטא הי' גם צבא מטה קיימין במין כו'. ואופן הקיום דצבא מעלה שקיימין באיש הוא כמו קיום דבר נצחי בעצם. וכידוע שיש הפרש בין הקיום דדבר הנפסד להקיום דדבר נצחי, דדבר הנפסד הנה גם בשעת קיומו הוא בהפסידות והיינו שהוא תמיד בהפסידות וכמ\"ש הבחיי שהתינוק משעה שנולד מתחיל להתייבש, והדבר הנצחי הוא שאין בו הפסידות כלל. וכן הוא בצבא מעלה שבעת קיומם אין בהם הפסידות כלל, וכדאי' בירושלמי ע\"פ אלה תולדות השוה\"א בהבראם שהם חזקים כיום הבראם. וכ\"ז הוא רק מצד רצון הבורא דהרי מצד עצמן ה\"ה הווים ונבראים ומאחר שהם הווים ה\"ה נפסדים מצד עצמן, וקיומן הוא רק מצד רצון הבורא כו'. ומה שארז\"ל שית אלפי שני הוה עלמא וחד חרוב דקאי על כללות העולמות וההשתל', וכמ\"ש כי כאשר השמים\nהחדשי' והארץ החדשה אשר אני עושה כו' וכמ\"ש במ\"א, זהו מפני שכך יהי' רצון הבורא שיפסדו יהיו נפסדים, וכ\"ז שהרצון בהם שיהיו בקיומן בלי הפסידות ה\"ה קיימין כמו דבר הנצחי כו'. הרי שאפשר להיות שאין לו סוף אף שיש לו תחלה, וכל שאין לו תחלה ממילא אין לו סוף, וא\"כ אם הי' הכוונה על עצמותו ית' הול\"ל אין לו תחלה. ועוד דעל עצמות לא יתכן לומר כינוי א\"ס דפירושו הוא שא\"ס להתפשטותו, והרי עצמות אינו בבחי' התפשטות דכל עצמי אינו מתפשט כו'. אלא הכוונה באוא\"ס על האור, דהאור יש לו תחלה שהוא העצמי רק שאין לו סוף להיותו בבחי' גילוי העצם שכמו העצם כו', וגם האור הוא בבחי' התפשטו' דשייך לומר עליו א\"ס להתפשטותו כו'. ולהבין זה צ\"ל תחלה ההפרש בין אור לשפע שהמקובלי' משתמשים ע\"פ הרוב בל' אור והחוקרים בל' שפע, וההפרש ביניהם הוא דשפע מורה דההשפעה היא איזה מהות דבר שנשפע מן המשפיע אל המקבל, וכמו השפעת הצדקה מעשיר לעני שמהות דבר נשפע ונמשך, וכמו המשכת המים ממקום למקום שנא' ע\"ז ל' שפע וכמו שפע ימים, שפעת מים, הרי עצם מהות המים\nנמשכים ממקום למקום כו', דהשפעה זו פועלת שינוי וחסרון בהמשפיע, וכמו המים הנמשכים ה\"ה חסרים ממקום שנמשכו כו'. וכמו\"כ בכחות הנפש וכמו בכח הזריקה כשזורק אבן למע' הרי נבדל ונפרש ממהות כח היד המתלבש בהאבן ונושאו למע', דהרי הזריקה היא לאחר שיוצא האבן מן היד, הרי נבדל ונפרש בזה ממהות כח היד על האבן שמקיפו (וואס נעמט עם ארום) מכל צד, שעי\"ז הוא נושא למע', וכשנכלה הכח ה\"ה נופל למטה, דכח זה הוא בבחי' התלבשות הן מצד הזורק והן מצד הדבר הנזרק, דהרי הזורק נתפס בהזריקה בזה שצריך לזרוק שלא תהי' הזריקה מעצמה, וגם שבשעה שזורק את האבן אינו יכול לעשות דבר אחר, וכן הפעולה בהדבר הנזרק הוא בדרך התלבשות בו, שהרי פועל בו התחדשות, והוא שילך האבן למע' היפך טבעו דטבע האבן הוא לירד למטה, ובכדי לפעול התחדשות א\"א להיות בדרך ממילא כ\"א בהתלבשות דוקא. דעד\"ז הוא למע' ההפרש בין עו\"ע ליש מאין, דבעו\"ע יש אופן שמהתפשטות העילה בא העלול בדרך ממילא (וכמו האי חכמתא אתפשטת ואפיק מינה בינה כו', וי\"ל דלמע' כן הוא במוחין ומדות גם בחיצוניות שלהם כו', ובאדם למטה בבחי' הפנימיות שלהם כו'), וכמו במוחין ומדות בבחי' הפנימיות והגדלות"],[3601330249,"שלהם שהמדות הן בערך המוחין, הרי בבחי' התפשטות והתגלות המוחין באים המדות בדרך ממילא כו', וכן משארז\"ל אא\"כ הי' חכם ומבין מדעתו כו'. אבל בהתהוות יש מאין אין זה בדרך ממילא, כ\"א ע\"י התלבשות האין האלקי להוות את היש כו'. וכידוע ההפרש בין נבראו לברא, דנבראו הוא שנעשה בדרך ממילא ואין זה בבחי' יש עדיין (שזהו ההתהוות כמו שהיא מש' הוי' כו' וכמ\"ש במ\"א), ובהתהוות היש ממש כתיב בראשית ברא אלקים בבחי' התלבשות כח הפועל בהנפעל כו'. רק שההתלבשות אינה בבחי' התלבשות פנימי ממש דענין ההתלבשות הוא שבא בגילוי ממש, ואם הי' באופן כזה בהתהוות יש מאין שהי' כח הפועל בגילוי ממש בהנפעל, הרי הי' הנפעל בערך הפועל, וענין יש מאין הוא בדרך אין ערוך כו', אבל מ\"מ הוא בבחי' התלבשות בהנפעל כו'. וזהו א' מהפלאים שבענין התהוות יש מאין שהאין האלקי הוא בבחי' התלבשות בהיש לפעול בו ההתחדשות היינו מציאות ישותו, ומ\"מ מתעלם ומסתתר ממנו שלא יהי' נרגש בהיש באופן שיתהווה במציאות יש כו' (ועמשית\"ל פ'). וכמו\"כ בענין הזריקה שכח התנועה שביד הוא\nבהתלבשות בהאבן לפעול בו רק שהוא בהעלם כו'. וכ\"ז הוא לפי שמהות כח היד נמשך בזה, לכן הוא בבחי' התלבשות מצד הזורק דהיינו שנתפס בזה כו', ומפני שענינו הוא לפעול דבר ע\"כ הפעולה בהנפעל היא ג\"כ בבחי' התלבשות כו'. והנה כח הזריקה היא בד\"כ כח היותר תחתון בכח התנועה ובא בדבר הנבדל לגמרי שאין לו יחס ושייכות אליו, ע\"כ ההתלבשות היא בבחי' העלם לגמרי כו'. אמנם באיזה מלאכה כמו בציור וכה\"ג ניכר יותר ההתלבשות, דבמלאכת הציור הרי ההתגלות דכח התנועה והתפיסה בזה היא ביותר, וכמו\"כ הפעולה היא בהתלבשות יותר מפני שיש יחס יותר להדבר הנפעל עם הפועל כו' (וכידוע שנשאר רושם מהפועל בהפעולה, וכנודע שהה\"מ ז\"ל הכיר מהכלי איך שהי' הפועל כו', הנה זה שייך במלאכת כלי וכה\"ג יותר מבזריקה מפני ההתייחסות זל\"ז שיש בזה התגלות והתלבשות יותר כו', וכן אדם חס על מעשה ידיו כו'), והחילוק הוא בגסות ודקות דכאשר הדבר הנפעל הוא דבר גס אין ההתגלות בזה כ\"כ וההתלבשות בהפעולה היא בהעלם יותר, ובדבר דק יש בזה יותר התגלות הפועל וההתלבשות היא בהתגלות יותר כו' (דבמדרי' הרוחניות הוא שבא בהנפעל בגילוי ובהרגש יותר כו').\n<span data-k=\"ks\"><b>קיצור.</b> יבאר ענין אוא\"ס דקאי על האור, כי העצמות אין לו תחלה וממילא אין לו סוף, וא\"ס יכול להיות גם שיש לו תחלה, כמו גם בנמצאים ברצון הבורא שיהיו קיימים כמו דבר נצחי, או באור להיותו גילוי העצם, וגם א\"ס הוא בהתפשטות, והעצם אינו מתפשט, ויבאר ענין אור ושפע, דשפע הוא מהות דבר, ולכן פועל שינוי, וכמו בזריקה שהזורק נתפס בזה, וגם הפעולה היא בבחי' התחדשות שזהו בבחי' התלבשות, וכמו עו\"ע שלפעמים הוא בדרך ממילא ויש מאין הוא בבחי' התלבשות בהעלם להיותו בבחי' התחדשות, וכ\"ה בזריקה שענינו לפעול דבר, וכמו\"כ במלאכת הציור עד\"מ ששם נתפס הכח יותר.</span>\nנד) <b>ויובן</b> זה יותר מענין ההתלבשות בכחות הרוחניים, וכמו בהתלבשות השכל בכח התנועה, דהרי בזריקה שהיא מכח התנועה שביד יש בזה התלבשות השכל שצריך לכוין במוחו ומחשבתו איך לזרוק ושתגיע למקום שרוצה"],[3601330250,"לזרוק והיינו שתהי' הזריקה מכוונת, וכן במלאכת הציור עד\"מ יש התלבשות השכל, הרי אינו דומה התלבשות השכל שבציור לההתלבשות שבזריקה, דלהיות שזהו כח היותר תחתון שבתנועה לא יש בזה התגלות השכל כ\"כ ואינו בהרגש פנימי בכח התנועה, וע\"כ כשמרגיל א\"ע בזריקה אינו צריך לכוין איך לזרוק, ובאמת גם אז יש בזה התלבשות השכל רק שהוא בהעלם בתכלית, ובמלאכת הציור יש בזה התלבשות והתגלות השכל יותר ובבחי' הרגש פנימי יותר, ובכל פעם ופעם צ\"ל בזה התלבשות השכל כו'. והדוגמא למע' כדאי' בס' הבהיר נטל צרורות וזרקן ומהם נעשה הארץ, וידוע שזהו בחי' כח הגבול שבא\"ס שבא בבחי' התלבשות בעולמות רק שהוא בהעלם כו', ובגמ' דחגיגה אי' בעשרה דברים ברא הקב\"ה את עולמו בחכ' ובתבונה ובדעת בכח ובגערה כו', דהעשרה דברים כולם הוא שבאים בבחי' התלבשות כו'. ויש בזה חילוקי מדרי' בנבראים דעם היות דכללות ההתהוות היא מעשרה דברים הנ\"ל, מ\"מ יש נבראים שעיקרם הוא מבחי' חב\"ד, ויש שעיקרם הוא מבחי' המדות שז\"ע בכח ובגערה כו', ולפי אופן כזה הוא ההפרש בההתלבשות\nותפיסא שהו\"ע ההתגלות הן מצד הפועל והן בהנפעל כו'. ומבו' במ\"א משל ע\"ז כמו א' המצווה לזולתו לעשות דבר ה\"ז בקול ודבור, וכן כשמדבר דברי אהבה או דברי שכל ה\"ז ג\"כ בקול ודבור, ואינם דומים כלל זה לזה, דבהציווי הרי אין המשפיע נתפס בכחותיו כ\"כ בזה וכן המקבל אינו נתפס בזה רק לשמוע הציווי, וכשמדבר דברי אהבה הרי המשפיע נתפס בזה במדותיו שבאים בהתגלות, וכן המקבל נתפס בזה בההרגש שבו שנרגש בו כח המשפיע ומתקרב אליו עי\"ז, וביותר הוא בהשפעת השכל שנתפסים בזה ביותר בבחי' התלבשות והתגלות כו'. והכל הוא בקול ודבור כו', ולכן הציווי הוא בקול רם דהיינו התגברות הקול, ובהשפעת השכל א\"צ להיות בקול רם ואדרבה דברי חכמים בנחת נשמעים כו', והיינו דשם עיקר הוא הקול, ובהשפעת השכל העיקר הפנימי שהוא השכל כו'. ועד\"ז הוא למע' בהעשרה דברים שזהו מה שבא בבחי' התלבשות, ויש בזה חילוקים בנבראים מאיזה מדרי' עיקר מקורם והתהוותם דלפי אופן כזה הוא ההתלבשות וההתגלות כו', אך כללות כח התנועה הוא כח אחרון שבנפש. ויובן כמו\"כ בהשפעת השכל מן\nהמשפיע אל המקבל דג\"כ מהות השכל נשפע בזה והוא ג\"כ בבחי' התלבשות כו', ועם היות דכללות ענין השפעת השכל ה\"ז הארה לבד, וכנודע ההפרש בין השפעת השכל להשפעה עצמיות, דבהשפעה עצמיות העצם ממש נשפע בזה שהרי נעשה מזה מהות שכל ממש אצל הבן, משא\"כ בהשפעת השכל הרי דוקא כאשר התלמיד הוא בר שכל בעצמו הרי הוא מקבל שכל הרב ומתלמד עי\"ז, אבל אם אינו בר שכל בעצמו לא יתהווה אצלו מהות שכל עי\"ז, וכמא' העולם א קא(קען מען ניט ארוף שטעלין והיינו לפי שהוא הארה לבד, מ\"מ הנה מהות ההארה נשפע בזה שהרי משפיע לו מהות שכל, והוא ממהות שכלו של הרב והתלמיד מקבל בזה שכל משכלו של הרב כו'. וזהו שההשפעה היא בקיומה גם לאחר הפסק ההשפעה וגם לאחר סילוק המשפיע מפני שמהות ההארה נמשך בזה, ע\"כ גם אפי' לאחר שמסתלק המשפיע יכול לעיין בה ולמצוא בזה החיות שהי' לו בעת שקיבל את ההשפעה מן המשפיע כו', דבאור הרי כשמסתלק העצם מסתלקת גם ההארה, ובהשפעת השכל נשארה ההשפעה, והיינו לפי שמהות ההארה נמשכה בזה כו'. ולכן אופן ההשפעה היא בבחי' התלבשות ותפיסא, שהמשפיע נתפס בזה ועושה בו שינוי והתפעלות, שע\"י ההשפעה מתוסף"],[3601330251,"שכל אצל המשפיע וכמו ומתלמידי יותר מכולם, דלבד זאת שיש תלמיד המחכים את רבו ע\"י הקושיות וכה\"ג הנה ע\"י עצם ההשפעה מתוסף אצלו שכל, וכן העדר ההשפעה עושה גרעון בהמשפיע כו' (והיינו כשאינו משפיע גם לעצמו, דהרי השפעת השכל אין צריך אל הזולת ויכול להשכיל השכלות לעצמו, ועי\"ז לא יהי' בו גירעון, ומ\"מ בכדי שיתוסף העיקר הוא ע\"י ההשפעה אל הזולת כו'), והוא מוגדר בההשפעה שבעת ההשפעה א\"א לו להשכיל שכל אחר. וגם הוא מוטרד בההשפעה שהרי לא תהיה ההשפעה מעצמה כ\"א צריך להשפיע את השכל, וגם הטרדא היא איך להשפיע והו\"ע כליות יועצות איך להשפיע, דלהיות שענין ההשפעה אינו בבחי' גילוי העצם היינו לגלות עצמותו כ\"א לפעול אצל המקבל, ע\"כ צ\"ל העצה בזה איך להשפיע באופן שיתקבל אצל המקבל. שזהו ההפרש בין מלמד בר פועל לאינו בר פועל, דעם היותו בעל שכל גדול יותר מ\"מ אינו בר פועל, ולכאו' ענין הלימוד תלוי בשכל והשגה ומי שהוא בר שכל גדול ביכולתו ללמד יותר, שהרי כשיגדל התלמיד צריך למלמד גדול והמלמדו מקרא אינו יכול ללמדו משנה וגמ' כו'. מ\"מ\nבכדי לפעול בהמקבל זהו דוקא כשהוא בר פועל, והיינו שיודע לכלכל דבריו ולסדר הענינים באופן שיהיו מובנים ויתקבלו אצל המקבל, וגם צריך להמציא ענינים במה להלביש את השכל בכדי שיהי' מובן אל המקבל, וזה שאינו בר פועל הגם ששכלו הוא בעילוי אם אינו יודע לכלכל דבריו אינו פועל בהתלמיד, וכשיגדיל התלמיד צריך למלמד גדול יותר אך שיהי' בר פועל כנ\"ל. וז\"ע הטרדא שבהמשפיע בהעצה איך להשפיע. ומובן שההשפעה גופא ג\"כ משתנית בזה, שזהו ההפרש בין הבר פועל לשאינו בר פועל, דזה שאינו בר פועל ה\"ה משפיע את השכל כמו שהוא אצלו ואין זה בערך המקבל, והבר פועל הוא שמשנה את ההשפעה שתהי' לפ\"ע המקבל, ובכללות זהו בהשכל השייך אל המקבל, וכידוע דבכל ענין שכלי יש כמו שהשכל הוא לעצמו שהוא הפנימיות וחיצוניו' השכל הוא ששייך אל המקבל, ובזה צריך לשנות ההשפעה שתהי' בערך המקבל, ואין זה שינוי המהות שה\"ה אותו השכל ממש רק שבא בבחי' מיעוט ובהתלבשות בענינים שבערך המקבל, ולפעמים בא בציור אחר שעי\"ז דוקא מתקבל אצל המקבל כו'. ונמצא דלבד זאת שהמשפיע\nמוטרד בעצם ההשפעה להשפיע את השכל ה\"ה מוטרד ג\"כ בזה שתהי' ההשפעה לפ\"ע המקבל. וכ\"ז הוא לפי שמהות ההארה נמשך בזה לכן המשפיע נתפס בזה שצריך להשפיע, ולפי שענין ההשפעה היא לפעול בהמקבל היינו שתהי' בו בבחי' התלבשות פנימי', ע\"כ צ\"ל בזה הטרדא וההתעסקות איך שתהי' השפע באופן שתתקבל כו', וגם ההשפעה משתנית בזה להיות לפ\"ע המקבל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויותר יובן מהתלבשות השכל דבמלאכת הציור הוא בהתגלות והתלבשות יותר מבזריקה, ולמעלה הו\"ע בעשרה דברים ברא הקב\"ה כו', ויש שעיקרם מבחי' חב\"ד או שעיקרם מבחי' חג\"ת, ועצם התהוותם הוא כמו מבחי' זריקה עד\"מ, ונת' משל ע\"ז, וכ\"ה בהשפעת השכל שנמשך מהות הארה, ולכן פועל שינוי בהמשפיע בתוס' וגירעון והוא מוגדר בזה ומוטרד להשפיע, ומפני שהוא לפעול בבחי' פנימי ה\"ה מוטרד ג\"כ איך להשפיע שז\"ע כליות יועצות, ובזה משתנה ג\"כ ההשפעה.</span>"],[3601330252,"נה) <b>אמנם</b> ענין האור הוא שזהו רק הארה לבד שאין בו מן העצם, וכמו אור וזיו השמש, הרי אין עצם השמש מתפשט להאיר כ\"א הארתו לבד (שאינו בבחי' מהות דבר, והראי' שכאשר מסתלק העצם וכמו בשקיעת השמש אין האור נמצא, והיינו לפי שהוא רק הארה לבד כו'), וע\"כ אין האור פועל שום שינוי בהעצם, שהרי בהשמש אינו נוגע אם האור מאיר א\"ל דכאשר מאיר האור אינו נעשה תוס' בהשמש, וכמו\"כ כשאינו מאיר אינו נעשה גרעון בהשמש, וכמו כשמעמידין מסך נגד אור השמש או כשיש עננים שאין האור מאיר בעולם או בבית, אין זה עושה שום שינוי וגרעון בהשמש, וגם לא בהגילוי מאתו. דבהשפעה כשהמקבל אינו כלי לקבל אין המשפיע יכול להשפיע, ובאור אינו כן דגם כשאין האור מאיר אין שום שינוי בהשמש, ונמשך ממנו האור והזיו בשוה כמו אם הי' מאיר בעולם והיינו אם לא היו עננים כו'. וגם אין השמש מוטרד להאיר אור שהאור ממילא בו, וכמו אור הנר כשמכניסי' אותו בבית ממילא הבית מאיר וא\"צ להיות התעסקות מהנר להאיר את הבית, וכמו שמחממים מתכת באש הרי המתכת מתחמם ממילא מחום\nהאש בלי שום התעסקות מהאש, דהחום בא מהאש בדרך ממילא וכן המתכת ע\"י שמתקרב אל האש מתחמם ממילא כו', ומה שהנפחים נופחים במפוח בהאש זהו רק לקרב האש אל המתכת או להגדיל את האש להוציאו מההעלם אל הגילוי, אבל החום וחימום המתכת בא בדרך ממילא. וכן הוא באור כו', והיינו לפי שהוא הארה לבד אין זה עושה שינוי והתפעלות בהמאור, שאינו נתפס ומתלבש להיות מוטרד ומוגדר בזה, וגם א\"צ הכנת המקבל שאינו בא בו בהתלבשות כו'. אמנם יש מעלה יתירה באור לגבי שפע שהאור הוא מעין המאור, וכמו אור וזיו השמש ה\"ה מעין השמש שהוא בהירי ולכן האור מאיר, ולכן יש חילוקים באור כמו אור השמש ואור הלבנה ואור הנר, דלפי שהעצמיים מחולקים ע\"כ גם ההארות אינם דומים זל\"ז לפי שהן כמו העצם כו'. והגם דשפע הוא ג\"כ לפי אופן העצם וכמו בהשפעת השכל הרי מי שהוא חכם גדול מגלה שכליים נעלים ביותר, זהו רק שההשפעה לפי אופן העצם והיינו מה שהעצם מראה כחו בההשפעה, דלפי אופן עצם כח חכמתו מראה כחו בההשפעה (דבאמת זהו לפי עצם כח חכמתו הנעלמה דלפי אופן כזה מראה כחו הן\nבהשכלתו לעצמו והן בההשפעה אל הזולת, והרי גילוי החכמות מעצם כח חכמתו הנעלמת אין זה בבחי' גילוי ההעלם ממש היינו מעין העצם, שהרי העצם הוא רק היולי ומושלל ממציאות שכל וההתגלות הוא שכל כו', א\"כ זהו רק שהעצם מראה כחו בההשפעה כו'), דכשהוא חכם גדול בעצם ה\"ה מגלה שכליים נעלים ביותר, ובכל ענין בעומק ופנימיות, ומביא הכל לידי גילוי להיות מתקבל אל המקבל כו'. דכ\"ז הוא רק שההשפעה היא לפי אופן העצם לא כמו העצם כו', והראי' משיחת חולין של ת\"ח שצריכים לימוד מפני שיש בהם חכמה, דשיחות חולין של אדם פשוט א\"צ לימוד שאין בהם שום שכל ות\"ח גם בשיחות חולין שלו יש בהם חכ', ומ\"מ ה\"ה שיחות חולין, ואינן כמו העצם רק שהן לפי אופן העצם, דלפי שהוא חכם גדול יש חכמה גם בשיחות חולין שלו, ולפי אופן חכמתו כן הוא החכ' שבהשיחות חולין כו'. וכן הוא בהשפעת השכל שהוא לפי אופן העצם לא כמו העצם, שהרי אין ההשפעה אל הזולת כמו שיודע אותו הענין גופא לעצמו, דגם בשכליים הנעלים הרי לעצמו הוא יודע אותם באופן אחר לגמרי כו', ולצורך ההשפעה הרי צריך לשנות גם חיצוניות השכל כו' וכמשנת\"ל פנ\"ד. הרי שאינו כמו העצם רק שהוא"],[3601330253,"לפי אופן העצם כו', אבל האור הוא כמו העצם ממש כו'. והגם דאי' בתניא שהאור כמו שהוא כלול בגוף כדור השמש הוא ביתר שאת וביתר עז דהיינו שהוא בעילוי ביותר כו', זהו רק מצד ההתגלות שהאור ע\"י ההתגלות הוא מתמעט כו', שכן הוא גם בהאור העצמי דכשהוא כלול במקורו ה\"ה בעילוי ביותר דהיינו שאינו במציאות אור כלל, וכשמתגלה ה\"ה מתמעט והיינו שהוא במציאות אור עכ\"פ כו', וכמ\"ש במ\"א בענין אין זולתך ואפס בלתך כו' (וית' לקמן פ'), ובפרט כפי הידוע דאור השמש הוא ע\"י הנרתק כו', ומ\"מ גם כמו שהוא ע\"י הנרתק ה\"ה כמו העצם שהעצם הוא בהירי והאור מאיר כו' (צ\"ל שהכוונה כאן כפי המבואר במ\"א דאור הסובב הגם שנמשך ג\"כ ע\"י הצמצום אין הצמצום פועל בו וה\"ה כמו העצם, רק מה שנעשה בבחי' מקיף לעולמות עכ\"פ כו' וכמשי\"ת). והנה כמו באור וזיו השמש כמו\"כ הוא באור וחיות הנפש להחיות את הגוף שהוא ג\"כ רק הארה לבד, שהרי עצם הנפש אינו נמשך להחיות את הגוף רק הארתו לבד, ולכן אינו פועל שינוי בהעצם אם מאיר או אינו מאיר כו', וכמו\"כ מה שמחי' את הגוף ה\"ז שלא\nע\"י התעסקות שע\"י התלבשותו בגוף ממילא הגוף חי כו'. ומה שצ\"ל צמצום בכדי להתלבש בגוף, זהו רק בכדי שיהי' לו שייכות אל הגוף, כי גם הארת הנפש אין לו שייכות אל הגוף (וחיות הנפש בד\"כ הוא בבחי' או\"פ כו' וכמ\"ש במ\"א), וע\"כ צ\"ל צמצום בנפש שיהי' לו שייכות אל הגוף כו', וה\"ז כמו שהנפח נופח במפוח לחמם את המתכת שזהו רק לקרב את האש אל המתכת כנ\"ל, כמו\"כ ענין הצמצום בהנפש הוא בכדי שיהי' לו שייכות אל הגוף כו', וכשמתלבש בהגוף ה\"ה מחי' את הגוף שלא ע\"י התעסקות כו'. ומה שצ\"ל הכנה בגוף לקבל חיות הנפש, ה\"ז הכנה כללית מה שנברא כך להיות מוכן לקבל צורת נפש האדם, ואין זה כמו הכנת הכלים ואיברי הגוף לקבל הכחות, שזהו הכנה פרטיות להיות בו גילוי הכח בבחי' אור פנימי ממש שזהו תלוי בזיכוך הכלי כו'. וכמו בחומר המוח כשהוא חומר דק ה\"ה כלי יותר לקבל אור צורת השכל שמתגלה בו יותר מכמו במוח עב, וכל מה שמזכך חומרו יותר הרי מתגלה בו אור השכל ביותר כו'. וכמו בכל אדם אחר האכילה אינו כלי כ\"כ לאור השכל מפני האידים העולים מהמאכל שמעלימים\nומסתירים על השכל, ואח\"כ כשנח נעשה מוחו מזוכך והוא כלי לקבל כו', ה\"ז הכנה ממש בהכלי להיות כלי לקבל את האור והגילוי כו'. וכמו\"כ יש השערה באור השכל איך שיומשך ויאיר בהכלי, דכשם שיש הכנה בהכלי לקבל אור השכל כמו\"כ יש השערה ג\"כ בכח השכל איך שיומשך בהכלי (וכמשנת\"ל פ\"ו), רק שזה אין אנו מרגישים כו', וכמו במשפיע ומקבל שיש השערה בהמשפיע איך להשפיע וכן בהמקבל הכנה לקבל את האור וכמו\"כ הוא בהכחות כו'. משא\"כ בכללות אור וחיות הנפש המחי' את הגוף אין חילוק כלל בין גוף גס לגוף דק, וכמו שבגוף א' אין חילוק בהאיברים פרטים שבו כמו הראש שהוא היותר דק שבאיברים והעקב שהוא היותר גס הרי כולם חיים מהנפש בשוה. כמו\"כ אין הפרש בכללות חיות הנפש בין גוף גס לגוף דק והכנת הגוף הוא רק בכללות, דכמו שגוף הבהמה מוכן לקבל צורת נפש הבהמה, כמו\"כ גוף האדם מוכן לקבל צורת נפש האדם, אבל אופן החיות אין זה לא ע\"י הכנת הגוף ולא ע\"י התעסקות מהנפש להחיות כו'. וכ\"ז הוא לפי שההמשכה מהנפש הוא בבחי' אור לא בבחי' שפע, ע\"כ אינו בבחי' תפיסה והתלבשות כו'."],[3601330254,"<span data-k=\"ks\"><b>קיצור.</b> אמנם אור הוא שאין בו העצם, רק גילוי העצם, וכמו אור השמש, ולכן אין מזה שינוי בהעצם ולא בהגילוי מאתו, ואינו מוטרד ומתעסק להאיר, וכמו חימום המתכות מהאש שהוא בדרך ממילא ואינו תלוי בהכנת המקבל, והמעלה באור שהוא כמו העצם (רק שבהתגלותו מתמעט), משא\"כ שפע הוא רק לפי אופן העצם, וכמו באור השמש כ\"ה באור וחיות הנפש שאינו עושה שינוי בהעצם, ואינו מוטרד בזה, והצמצום הוא רק שיהי' שייך אל הגוף, והכנת הגוף הוא רק הכנה כללית (לא כמו בשפע שצ\"ל הכנה פרטיות), לכן מחי' כל הגוף בשוה.</span>\nנו) <b>אך</b> הנפש הוא מוגדר בגוף דכשמחי' גוף זה אינו יכול להחיות גוף אחר, וכדאי' בזהר שהרשב\"י שאל מאלי' למה לא הי' בהאדרא והשיב לו שהי' צריך להציל את רהמ\"ס וחביריו, ואי' בקול ברמה משום דלכבודו של רהמ\"ס הי' צריך להתלבש בגוף וכן לכבודו של הרשב\"י הי' צ\"ל בגוף, וא\"א לנפש אחת להיות בשני גופים. ומה שאלי' נמצא בכל ברית מילה, אי' בקול ברמה שם שזהו רק ניצוצות לבד כו', הרי שהנפש מוגדר בגוף כו'. וזה יובן מאור וזיו השמש שאין השמש מוגדר שהרי ממגד תבואות שמש כו', ופועל בכולם בשוה, וכן כמה פעולות כאחת כו'. אך השמש הוא מוכרח בהגילוי, וזה יובן מאור וחיות הנפש שאין הנפש מוכרח בהגילוים וביכולתו להעלים כחותיו, וכמו אאע\"ה שכבש רחמיו מעל בן יחידו שבהכרח הוא שיהי' התעלמות הכח לגמרי, דאל\"כ לא הי' אפ\"ל העשי' כדבעי כו'. וגם ביכולתו להעלים לגמרי את האור והגילוי מאתו, וכמו בגלגולים ר\"ל דנפש האדם בגוף הבהמה שאין הבהמה חי' מנפש האדם מפני שמתעלם האור והגילוי בעצמה כו' (ושם הוא מצד העדר הכלים שאין גוף הבהמה מוכן\nלזה כו', ויותר מובן הוא מהתעלמות הכחות כו', אמנם באמת גם התעלמות כללות האור (כמו בגלגולים ר\"ל), אין זה רק מצד העדר הכלים (היינו מה שגוף הבהמה אינו מוכן לקבל צורת נפש האדם), שאם הי' מוכרח בהאור והגילוי הי' נמשך הגילוי מאתו גם כשהוא בכלי הבלתי מוכנת לזה, וכמו באור השמש הרי גם כשעננים מסתירים ואינו מאיר בעולם מ\"מ נמשך ממנו האור כו' וכנ\"ל פנ\"ה (והגם ששם נת' שזהו מפני שהוא בבחי' אור, והיינו שאינו תלוי בכלים, מ\"מ ג\"ז מובן מזה שהוא מוכרח בהגילוי, והיינו שאין בו ענין ההתעלמות והעדר הגילוי. שהרי הגילוי מהנפש הוא ג\"כ בבחי' אור, והראי' מזה שאינו עושה שינוי בהעצם, ואין הגילוי והחיות בבחי' טרדא והתעסקות, ומ\"מ צ\"ל הכנה כללית בהגוף כנ\"ל. ומה שנת\"ל שהוא בבחי' או\"פ הרי אין זה בבחי' פנימי ממש כמו הכחות בהאברים, שאינם דומים הן באופן הגילוי והן מצד ההרגש בגוף, והיינו דהן מצד האור והן מצד הכלים אינם דומים זל\"ז, ולכן מספיק לזה גם הכנה כללית כו'), ואם הי' הנפש מוכרח בהגילוי, הי' נמשך ממנו הגילוי גם בגוף הבהמה\n(רק שהי' בבחי' מקיף בלבד) והעדר גילוי האור לגמרי, ה\"ז הוראה שהוא גילוי רצונית כו'), הרי שהגילוי הוא רצונית. ועם היותו גילוי רצונית ה\"ה מ\"מ בדרך ממילא כו'. והדוגמא מכ\"ז יובן למע' בבחי' אוא\"ס שהוא בבחי' גילוי העצם שמעין העצם כו'. דהנה בד\"כ ב' המדרי' דאור ושפע למע' הוא האור המתלבש בכלים ועולמות והאור שלמעלה מהתלבשות כו', דהאור המתלבש בכלים הוא שבא בבחי' שפע כו', ובשרשו ומקורו הוא בחי' האור להאיר את העולמות לא בבחי' גילוי העצם כו', והיינו להיות בבחי' מציאות אור כו', וה\"ה"],[3601330255,"בא בבחי' התלבשות בכלים, ובהתלבשותו בתוך הכלי ה\"ה נעשה בבחי' מהות ומציאות דבר כו'. וההמשכה היא בס' והדרגה ובבחי' התחלקות דמעלה ומטה בריבוי ומיעוט ושמחולקי' בעצם מהותם ומדרי' כו', והיינו מפני שכללות האור הוא רק להאיר את העולמות ובא בבחי' התלבשו' כו'. אבל האור שבבחי' א\"ס הוא שבא מן העצמות לא בשביל להאיר את העולמות, כ\"א בבחי' גילוי העצם, שהוא בבחי' אין בעצם לא בבחי' מהות ומציאות דבר כלל כו', וה\"ה בבחי' א\"ס ובבחי' פשיטות ממש ואינו בא בבחי' התלבשות כלל כו', דכשם שהעצמות אינו בגדר התלבשות כמו\"כ הגילוי מן העצמות אינו בא בהתלבשות כו'. והגם שהוא רק גילוי העצם ולא העצם (שאין בו מן העצם כו'), ה\"ה כמו העצם דכשם שהעצם הוא בבחי' א\"ס ובבחי' פשיטות, כמו\"כ האור הוא בבחי' א\"ס ובבחי' פשיטות כו', דבאמת מצד הפשיטות שבהאור אינו שייך בו שום שם רק א\"ס, אמנם כשנכנה אותו בשם (והיינו כמו שבא בגילוי כו' וכמשי\"ת) א\"א לכנותו רק בשם רצון, לפי שהרצון הוא שבא בבחי' גילוי מן העצם כו' וכמשנת\"ל פמ\"ט.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש שופטים ושוטרים תתן לך. דהנה הפרד\"ס כ' שהע\"ס דאצי' נק' משפט מצד הבינה. והענין דהנה המשפט הוא מה ששופט אם באופן כך או באופן כך, וברוחניות ענין המשפט הוא ההשערה בהאור באיזה אופן יומשך בהמקבלים אם באופן כך או כך כו', וגם בהכנת המקבל אם הוא ראוי לההשפעה ובאופן הראוי שלו כו'. דכ\"ז שייך רק בהאו\"פ שבא בבחי' התלבשות אור בכלי ע\"כ שייך בזה המשפט כו', ומש\"כ שזהו מצד הבינה, זהו כמשנת\"ל דעיקר התחלת ההשתל' הוא מהבינה כו'. אמנם מש\"כ במד\"ר שהוא אוהב את הקטן יותר מכולם הוא שכאן הכוונה להמשיך בחי' עצמות אוא\"ס היינו האור שבבחי' א\"ס ובבחי' בל\"ג כו', דבכדי להמשיך בחי' עצמות אוא\"ס זהו דוקא ע\"י העדר הכלים דהעדר הכלי זהו כלי לעצמות אוא\"ס כו', והו\"ע הביטול שלמע' מטו\"ד שזהו אמיתת ענין הביטול כו'. דהנה הביטול שע\"פ טו\"ד אינו ביטול אמיתי שהרי השכל מחייב כן (וממילא הוא בבחי' מציאות בביטולו כו'), וגם דענין הביטול הוא בשביל שעי\"ז נעשה כלי לגילוי אור כו', שג\"ז השכל מחייב שצריכים להיות כלי\nכו', וגם יש בזה הגבלה לפי אופן השכל שמחייב ומביא את הביטול, ולפי אופן שרוצה להיות כלי לפי אופן כזה הוא הביטול שלו כו', דמשום כ\"ז אינו ביטול אמיתי כו'. ואמיתית הביטול הוא בהביטול דהנחת עצמותו שאינו ע\"פ טו\"ד ואינו בבחי' הגבלה כו'. והו\"ע ביטול הקטן לגבי הגדול שמתבטל בכל עצמותו (ער פארלירט זעך), דמשפיע ומקבל הרי המקבל בטל אל המשפיע ועי\"ז הוא כלי לקבל כו', אך הוא עפ\"י טו\"ד בכדי להיות כלי כו'. משא\"כ הביטול דקטן לגבי הגדול אינו ע\"פ טו\"ד, והביטול הוא בכל עצמותו כו' (והיינו לפני גדול שמובדל בערך כו'). וז\"ש במד\"ר שהי' אוהב את הקטן היינו בחי' ביטול הנ\"ל, והוא מה שהגדול עושה א\"ע לקטן, דקטן אין לו דעת, והגדול בדעת בבחי' מוחין ומדות שעושה א\"ע לקטן, היינו שמניח א\"ע בבחי' הנחת עצמותו ה\"ז ביטול שלמע' מטו\"ד כו'. וז\"ע קבעומ\"ש דר\"ה, דהנה ענין קבעומ\"ש בדרך כלל הוא שאינו ע\"פ טו\"ד, וכידוע ההפרש ביטול דאוהב אל הנאהב לביטול העבד לאדונו, דבאוהב ונאהב הוא מפני שיודע העילוי שלו ומפני שמקבל ממנו, וע\"כ הביטול הוא לפי אופן הידיעה וההשגה שלו, ולפי אופן כזה נעשה כלי לקבל"],[3601330256,"ממנו כו'. אבל הביטול דעבד אינו מצד העילוי של האדון ולא לקבל איזה דבר, רק מפני שהוא עבד כו'. דכמו\"כ הוא בקבעומ\"ש בכלל ובפרט בר\"ה ויו\"כ דהקבעומ\"ש הוא בבחי' הנחת כל עצמותו לאלקות (וואס ער לייגט זעך אין גאנצין אוועק לאלקות), כי בר\"ה הוא זמן המשכת הרצון למלוכה והרצון לבריאת והתהוות העולמות, שזהו בחי' כתר מל' שממשיכים בר\"ה שהו\"ע המשכת עצמות אוא\"ס, שזהו דוקא ע\"י ביטול הנ\"ל. וזהו שארז\"ל ע\"פ ארץ אשר ה' אלקיך דורש כו' מראשית השנה כו' רשית חסר כתיב, דכל שנה שהיא רשה בתחלתה ה\"ה מתעשרת כו', ופרש\"י שישראל עושין עצמם כרשין וכדלים בר\"ה ויו\"כ ומבקשים תחנונים כאילו אינם ראוים ח\"ו ומבקשים רק רחמים כו', וכן מבקשים סליחה ומחילה, ואפי' צ\"ג שאינם שייכים כלל לשום חטא ח\"ו מבקשים ג\"כ סליחה ואומרים וידוים כו' שעושין עצמן כחוטאים ופושעים והם בהתעוררות תשובה בלב נשבר ממש כו', ומקבלים עליהם עומ\"ש שלימה בביטול כל עצמותם כו'. וגם בזה יש ענין המשפט והוא לשפוט א\"ע מהדברים המותרים דבזה הזמן צ\"ל בזה זהירות יתירה כנודע,\nוגם ענין ההנחה בכלל הו\"ע המשפט ששופט ומכניע א\"ע כו'. וענין מ\"ש שאוהב את המשפט י\"ל שזהו מה שיש מעלה בפנימי על המקיף (והיינו לפי משנת\"ל שהמשפט הוא בע\"ס כו'), וכידוע במעלת היושר על העיגולים כו'. וענין שאני נותן מה שאני אוהב לזה שאני אוהב הוא שע\"י המשכת אור העצמי נמשך ממילא הפנימי כו', וגם י\"ל הכוונה במ\"ש שנותן דבר האהוב לזה שאוהב היינו מה שניתן לישראל דוקא כח זה דהביטול שלמע' מטו\"ד (וזהו כנ\"ל שההנחה גופא הו\"ע המשפט, ובאמת הביטול הנ\"ל דלמע' מטו\"ד הוא ג\"כ בבחי' פנימי שז\"ע הנחת עצמותו כו'), מפני שהם מושרשים בעצמות אוא\"ס כו'. ומדרי' זו יש בכאו\"א מישראל ובנקל לבוא לזה, יותר מלהעבודה שע\"פ טו\"ד שאין הכל שייכים לזה כ\"א מי ששייך להשגה והתבוננות וצריך עבודה ויגיעה רבה, ויש בזה כמה חילוקי מדרי' אם העבודה היא באופן כך או כך כו', אבל הביטול שלמע' מטו\"ד זה יש בכאו\"א ובנקל יותר לבוא לזה כו'. וזהו שופטים ושוטרים תתן לך בכל שעריך, ופי' בש\"ך עה\"ת שהן חושי הנפש, וכדאי' בס\"י ז' שערים בנפש ב' עינים ב' אזנים ב'\nנקבי החטם והפה שצ\"ל המשפט וההגדרה בכל חושי הנפש להיות עוצם עיניו מראות ברע ואוטם אזנו משמוע ובולם פיו מלדבר כו', וכ\"ז מצד הביטול בבחי' הנחת עצמותו כו' וכמ\"ש במ\"א (שזהו מצד הביטול דחכ' וכח הרצון שבנפש כו'), ועי\"ז נעשה ממילא ההגדרה בכל איברי הגוף, וזהו ושפטו את העם משפט צדק דהיינו המשפט באיברי הגוף כו', וע\"י כ\"ז ממשיכים בחי' עצמות אוא\"ס ב\"ה. וז\"ש במד\"ר דבזכות המשפט אני משרה קדושתי ביניכם, דהנה ידוע דקדושה זהו בחי' עצמות אוא\"ס שקדוש ומובדל מהשתל' כו' ונמשך ע\"י המשפט דוקא כו'. ובזכות המשפט אני גואל אתכם גאולה שלימה, דגאולה היא ג\"כ מבחי' עצמות אוא\"ס, וכמ\"ש אם יגאלך כו' גאלתיך אנכי כו', דענין הגאולה הוא היציאה מההגבלה שזהו דוקא מבחי' עצמות אוא\"ס כו'. וכ\"ז ממשיכים ע\"י המשפט כו'. וזהו שופטים ושוטרים תתן לך כו' בחי' המשפט והביטול בבחי' הנחת עצמותו, שזה\"ע כי נער ישראל שהן מקטינים א\"ע בבחי' ביטול והנחה כו', שממשיכים עי\"ז בחי' עצמות אוא\"ס כו'. וזהו שבזכות המשפט אני משרה קדושתי ביניכם ואני גואל אתכם בגאולה שלימה כו'."],[3601330257,"<span data-k=\"ks\"><b>קיצור.</b> אך הנפש הוא מוגדד, והשמש אינו מוגדר, רק שהוא מוכרח בהגילוי, ובנפש הגילוי הוא רצוני ומ\"מ הוא בבחי' אור, והדוגמא למעלה דהאור שלהאיר הוא עד\"מ השפע, ואור הא\"ס הוא רק גילוי העצם שכמו העצם, וא\"א לכנותו אלא בשם רצון שהוא גילוי העצמות. וע\"פ הנ\"ל ית' פסוק שופטים ושוטרים תתן לך.</span>"],[3601330258,"<h3>בס\"ד. ש\"פ תצא, תער\"ב</h3>\n<b>כי</b> תצא למלחמה על אויביך ונתנו ה' אלקיך בידיך, וצ\"ל מהו הל' כי תצא ולכאו' הול\"ל כי תלך כו'. וגם מ\"ש ונתנו ה' אלקיך בידיך ה\"ז סותר לכאו' למ\"ש כי תצא למלחמה דמשמע שזה בכח עצמן וממ\"ש ונתנו ה' אלקיך הרי שזהו מה שנותנים מלמע' כו'. והנה במד\"ר אי' ע\"פ צא הלחם בעמלק מכאן שהיו נתונים תחת ענני הכבוד דאין אומרים צא אלא למי ששרוי בפנים, וא\"כ כמו\"כ כאן שנאמר כי תצא ה\"ז ג\"כ במי ששרוי בפנים כו', ומשמעות הענין דבפנים אינו שייך מלחמה כ\"א ביציאה לחוץ דוקא. ולכאו' אינו מובן למה צריכים להיות היציאה מבפנים בכדי להלחם כו'. וגם משמע שהכח להלחם הוא ע\"י ששרוי בפנים וע\"י היציאה מבפנים יש בכח להלחם כו', ולהבין כ\"ז ילה\"ק משנת\"ל דאור א\"ס הוא בחי' גילוי העצם ועש\"ז נק' א\"ס שהוא פשוט בבחי' פשיטות העצמית כו'. ונת' ההפרש בין אור ושפע דשפע הוא שמהות דבר נשפע ונמשך וכללות ענין ההשפעה היא בכדי לפעול כו', וע\"כ ה\"ז בבחי' תפיסא והתלבשות שהמשפיע נתפס בזה מאחר שמהות דבר נמשך, וגם מפני שזהו לפעול ע\"כ גם הפעולה היא בבחי'\nתפיסא והתלבשות כו' (וגם מצד המקבל צריך להיות הכנה לתפוס ההשפעה כו'). משא\"כ באור שהוא הארה לבד וע\"כ אינו בבחי' תפיסא והתלבשות כו', והמעלה באור שהוא בבחי' גילוי מן העצם שמעין העצם וע\"כ גם האור הוא בבחי' פשיטות כו', ונת' שזהו בד\"כ האור שלהאיר העולמו' והאור שבבחי' גילוי העצם שהוא בבחי' א\"ס ובבחי' בל\"ג כו'.\nנז) <b>אמנם</b> עדיין צ\"ל דהלא בהמשלים דאור וזיו השמש ואור וחיות הנפש הרי ג\"ז הוא בכדי לפעול לא בבחי' גילוי מן העצם כו', שהרי נת\"ל פמ\"ח דאור השמש אין ענינו לתאר את העצם כ\"א לפעול פעולת האור כו', הרי שאינו בבחי' גילוי מן העצם כו', וכן אור וחיות הנפש הרי ענינו הוא לפעול פעולת החיות כו', וכמו\"כ למע' הלא נודע שגם האור מקיף פועל פעולות בעולמות כו', וא\"כ מהו ההפרש בין האו\"מ להאו\"פ כו'. אך הענין הוא דהנה המובן מהמשלים הנ\"ל דכל שהוא בבחי' אור גם מה שפועל דבר אין זה כמו פעולת השפע, דפעולה שבבחי' שפע הוא בבחי' תפיסא והתלבשות, משא\"כ פעולת האור אינו בבחי' תפיסא והתלבשות. וכמו באור וזיו השמש וכן הוא ג\"כ באור וחיות הנפש"],[3601330259,"וכמשנת\"ל פנ\"ה, דמצד אור וחיות הנפש אין חילוק בין גוף גס לגוף דק דכשם שבגוף א' אין חילוק בין איברים הגסים לאיברים הדקים כמו\"כ אין חילוק בין גוף גס לגוף דק כו', הרי שהפעולה היא שלא בבחי' התלבשות ותפיסא כו'. והנה עיקר ההפרש בין אור לשפע היינו בין אור פנימי לאור מקיף, דאור פנימי המשכתו מן העצמות הוא בבחי' מהות מציאות דבר והאו\"מ המשכתו הוא בבחי' אין כו', והיינו דתחלת אופן ההמשכה וההתגלות שלהם מן העצמות הנה האו\"פ נמצא מן העצמות בבחי' מציאות דבר והאו\"מ נמצא מן העצמות בבחי' אין כו'. וזהו ג\"כ מה שזה בא לפעול וזה אינו בא לפעול, דהאור פנימי מפני שכללות ענינו הוא לפעול ולהאיר את העולמות, ע\"כ תחלת מציאותו הוא שנמצא בבחי' מציאות דבר כו', דכל פעולה שייך כשהוא במציאות דבר דוקא כו', והאו\"מ הוא נמצא בבחי' אין לפי שאין ענינו לפעול כ\"א הוא בבחי' גילוי מן העצם כו'. וזהו המובן מהמשל דאור ושפע, דשפע הוא בדבר שהוא בבחי' מהות ומציאות, וע\"כ ההמשכה והגילוי מאתו אינו רק בבחי' אור, כ\"א שנמשך מהות דבר מה, רק שהוא\nבחי' חיצוניותו בלבד. ונק' ג\"כ הארה, מפני שהחיצוניות היא רק הארה לבד מהפנימיות, והיינו שהפנימיות היא עצמית והחיצוניות אינה עצמית, ומ\"מ הוא ממהות הפנימיות כו', וכמו פנימיות השכל שהוא לעצמו וחיצוניות השכל השייך אל המקבל (וכמו\"כ עצמיות המוחין והמוחין השייכים אל המדות שנת\"ל פנ\"ה), שזה עצמי וזה אינו עצמי, ומ\"מ הרי החיצוניות הוא מהפנימיות כו' (וכ\"ז הוא בדבר שבכללותו הוא בחי' הארה לבד, כי במה שהוא עצמי ממש, הנה גם מקצת מן העצם הוא עצם ממש כו'). ועמ\"ש בהבי' דוישובו בענין בצלמנו כדמותנו שזהו עד\"מ צלם האדם שעושין ממתכת או עץ ומציירים בו גם החיות, דחתוך האברים הוא כמו אברי האדם, אבל החיות הוא רק דמות בלבד כו', ויעו\"ש בהנמשל, ועמשית\"ל פ' (ולפ\"ז יובן דמה שאצי' הוא הארת הקו ה\"ז ממהות עצמיות הקו שלמעלה מאצי', רק שהוא בחי' חיצוניות כו', ומ\"מ ה\"ה בחי' מציאות לבד כמשנת\"ל פל\"ח להיותו בחי' הארה חיצוניות כו' וכנ\"ל. וכ' הפרדס דלמטה ידיעת המציאות אינו אפי' זיו מהעצמות ולמעלה המציאות הוא זיו מהעצמות כו' והיינו\nמהות גילוי כו', ואפשר דהכלים דא\"ק הן בבחי' אור כו'). ולכן פעולת השפע (שזהו ע\"י ההמשכה וההתפשטות כו') הוא בבחי' התלבשות ותפיסא וגורם שינוי והתפעלות בהפועל כו', אבל אור הוא שאינו מהות דבר מה, וההמשכה והגילוי הכל הוא בבחי' אור כו' (ועמ\"ש לקמן פנ\"ט), וע\"כ הפעולה היא לא בבחי' התלבשות ותפיסא, ואינו עושה שום שינוי והתפעלות כו'. וה\"ז ע\"ד הידוע בב' בחי' אין האין של היש האמיתי והאין של היש הנברא שזהו האין דד\"ע והאין דד\"ת. דהאין דד\"ת אינו בבחי' אין ממש (אז עס איז ניט פראהן קיין זאך כלל), שהרי הוא מקור ליש וא\"א לומר שהוא בבחי' אין ממש כו', ונק' אין רק בשם המושאל כו'. והאין דד\"ע הוא בבחי' אין ממש שהוא הארה והוא כלא ממש כו'. ועד\"ז הוא בבחי' או\"פ ואו\"מ דהאו\"פ הוא לפעול ה\"ה בבחי' מציאות דבר בעצם כו', והאו\"מ הוא רק בבחי' גילוי מן העצם ה\"ה בבחי' אין בעצם כו', וזהו בעצם מציאותם מן העצמות, אך בהתפשטות שלהם גם האו\"מ ה\"ה פועל דבר כו', רק שהפעולה דהאו\"מ אינו דומה כלל להפעולה דאו\"פ שאינו בבחי' תפיסא והתלבשות\nכו'. והענין הוא דהנה בכל דבר יש עצמות והתפשטות דגם באור הא\"ס יש בחי' העצמות דאוא\"ס ובחי' ההתפשטות שלו, דהעצמות הוא רק בבחי' גילוי מן"],[3601330260,"העצם ובחי' ההתפשטות הוא שבא לפעול כו'. וזהו משנת\"ל פנ\"ו דבאוא\"ס בעצם אינו שייך שום שם כלל ואם נכנהו בשם ה\"ה בשם רצון, הכוונה בזה דבחי' העצמות דאוא\"ס אינו שייך בו שום שם כלל, ובחי' ההתפשטות לפי שבא לפעול שייך שם שם, אבל רק שם רצון דענין הרצון הוא ששייך עכ\"פ להדבר שהוא רוצה ואינו בבחי' מציאות דבר לעצמו, ע\"כ הפעולה היא שלא בבחי' תפיסא כו' וכמשנת\"ל פנ\"ב (וי\"ל דבנפש ג\"כ עצם הרצון הוא להיות מרוצה, שזה אינו לפעול דבר ולא בבחי' שייכות לאיזה דבר, והוא רק סיבה שיהי' רצון כו' וכמשנת\"ל פ' הנ\"ל). וכן הוא בבחי' אור דבעצם הוא בבחי' אין ובבחי' פשיטות לגמרי ואינו בבחי' שייכות לשום דבר כו', ובהתפשטות ה\"ה בבחי' שייכות ופועל דבר כו', אבל הוא לא בבחי' תפיסא והתלבשות כו', והיינו לפי שבעצם מהותו הוא רק בבחי' גילוי מן העצם ובבחי' אין הנה גם בהתפשטות שלו הוא בבחי' אין. ועם היות שפועל בעולמות ה\"ז בבחי' מקיף שאינו בבחי' תפיסא והתלבשות והוא בכ\"מ בשוה כו'. וכידוע דאוא\"ס הגם שפועל בעולמות וכמשי\"ת שהאו\"מ פועל כמה\nפעולות בעולמות כו', אין זה בבחי' התלבשות, דזהו מ\"ש הנה השמים ושמי השמים לא יכלכלוך שאינם בבחי' כלי לאוא\"ס ב\"ה לקבל את האור בבחי' או\"פ, כ\"א מה שמאיר עליהם בבחי' מקיף לבד כו', ומקיף לכולם בשוה, מאחר שאינם בבחי' כלי לאור זה, שגם המדרי' היותר עליונה שבעולמות וכמו בחי' פרצוף דא\"ק שזהו בחי' שמי השמים בחי' טה\"ת שאחר הצמצום כו', ג\"כ אינו כלי לאור זה להיות בו בבחי' פנימי רק בבחי' מקיף מרחוק כו', וממילא כמו\"כ הוא סובב גם המדרי' היותר אחרונה וכמ\"ש ומתחת זרועות עולם כו'. והוא בחי' סובב הכללי שסובב ומקיף כללות ההשתל' דקו\"ח כולם בהשוואה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולכאורה אור השמש ואור וחיות הנפש הן ג\"כ לפעול, אך המובן מהמשלים הנ\"ל הוא שהאור פועל לא בבחי' התלבשות, והוא מפני שאינו מהות דבר, דשפע היא מהות דבר ונמשך מהות הארה לפעול מה, ה\"ז בא בהתלבשות ותפיסא, ולמעלה הוא דהאו\"פ שמפני שענינו לפעול ה\"ה נאצל בבחי' מציאות אור (והארת הקו שבאצי' הוא ממהות האור שלמע' מאצי') וע\"כ פועל בבחי' התלבשות ותפיסא, אבל אור ענינו הוא בחי' גילוי העצם, ויש בו עצם והתפשטות, שההתפשטות היא לפעול, ופועל שלא בבחי' התלבשות והיינו בבחי' מקיף, וע\"כ מקיף הכל בשוה.</span>\nנח) <b>והנה</b> אין הכוונה שהוא בבחי' מקיף ואינו נמשך כלל בעולמות. דבאמת גם האור הזה ה\"ה נמשך בעולמות בתוכם ובפנימיותם עד גם בכל הנבראים שלמטה כו', ואדרבה כל עיקר מקור ההתהוות דכל העולמות הוא מבחי' אור המקיף, וכן גם הגילוים דס' השתל' שרשם מבחי' האו\"מ ובו וע\"י הוא בחי' הגילוי בבחי' תוס' אור וחיות כו'. וע\"ד שנת\"ל פנ\"א במשל הרצון שבנפש דבהתגלות הרצון עי\"ז הוא דוקא התגלות הכחות כו', דהרצון עם היותו מובדל בערך מכל הכחות מ\"מ התגלות הכחות הוא ע\"י הרצון דוקא (ואדרבה להיותו מובדל מהם ע\"כ ה\"ה פועל דוקא ההתגלות דהיינו פעולה שבדרך הכרח כו'). וכמו בתנועה הגשמיות שהתנועה עצמה ה\"ה מהאור וחיות פנימי, ובכדי שתהי' התנועה"],[3601330261,"זהו ע\"י הרצון דוקא, ולכן ע\"י חולי ר\"ל בגידי הרצון נפסקה התנועה כו' כמשנת\"ל, וכן הוא גם ברוחניות הכחות דהתגלות שלהם הוא ע\"י הרצון, וכמארז\"ל לעולם ילמוד אדם במקום שלבו חפץ דכשיש לו חפץ בהענין ישכיל ויתחכם בו כו'. אך בנפש הרי אין התהוות הכחות מן הרצון וכ\"ש שאין האיברים התהוותן מן הרצון כו', משא\"כ למע' עיקר ההתהוות הוא מן הרצון כו', ובשרשו הוא בחי' הרצה\"ע שבאוא\"ס שלפני הצמצום מה שעלה ברצונו ית' להאציל ולברוא כו', דהרצון הוא עיקר הסיבה להתהוות העולמות שנתהוו לאחר הצמצום כו' (ולעיל פט\"ז נת' דהרצון להאציל הוא בכלל בחי' ממכ\"ע כו', וית' לקמן בעזהשי\"ת). וכן ההתהוות בפועל הגם שזהו ע\"י האור פנימי דאיהו וגרמוהי חד לברוא בהן כו', שהמהווה הוא האור שזהו בחי' איהו שמתייחד עם גרמוהי כו', מ\"מ הוא בכח האוא\"ס הסובב דוקא, וכמ\"ש כל אשר חפץ ה' עשה דעשיית והתהוות העולמות הוא מבחי' חפץ ורצון ה' דוקא. דמהאור פנימי בעצם א\"א להיות התהוות העולמות שהרי האו\"פ הוא שמאיר בגילוי בבחי' פנימיות, וממילא הרי ההתהוות שמזה\nבהכרח שיהי' בבחי' ערך כו' (שזהו מה שגבי ש' הוי' כתיב ונבראו בדרך ממילא שהן בערך כו' וכמ\"ש במ\"א). וכמו כלים דאצי' שהתהוותן הוא מן האור דמהתעבות האור נעשו הכלים כו' כמשנת\"ל פ\"ח (ועמ\"ש לעיל פ\"ט), הרי נתהוו כלים שהן בערך האור כו'. וכמו\"כ אם הי' התהוות העולמות מהאו\"פ היינו מאור האצי' היו העולמות במדרי' הרוחניות לא בבחי' יש כו', ובכדי שיתהווה מציאות יש זהו מהאור מקיף דוקא כו', וכמ\"ש באגה\"ק ד\"ה איהו וחיוהי חד וז\"ל וגם מאור א\"ס הסובב ומקיף לד' עולמו' אבי\"ע בשוה מאיר אל הקו הפנימי דרך הכלים די\"ס דבי\"ע ובהארתו תוך הכלים נותן בהם כח ועוז לברוא יש מאין כו' עכ\"ל, הרי דהתהוות היש הוא מאוא\"ס הסובב דוקא כו'. והגם שבד\"כ אצי' הוא בחי' סובב לגבי בי\"ע כו', מ\"מ בפרטיות המדרי' ה\"ז בחי' או\"פ כו'. דהנה אצי' דכללות הרי ודאי הוא בבחי' סובב לגבי בי\"ע הכללים כו', דאצי' דכללות הוא האוא\"ס שלפני הצמצום, והיינו שרשי האורות הכלולים באוא\"ס שהן ע\"ס הגנוזות זהו בחי' אצי' דכללות כו', והרי כללות האוא\"ס שלפה\"צ ה\"ה בבחי' סובב\nלגבי העולמות כו', ומ\"מ בפרטיות המדרי' ה\"ז בחי' שרש ומקור האו\"פ כו'. וכמו\"כ באצי' הפרטיות שהוא בחי' או\"פ שמזה לא הי' אפ\"ל התהוות היש כ\"א מבחי' או\"מ דוקא כו'. וכן חיות כל העולמות והנבראים עיקרו הוא מבחי' אור הסובב וכמ\"ש בסש\"ב פמ\"ח שידיעתו ית' מה שיודע את הארץ הלזו הגשמי הוא חיות כל עובי הכדור כולו והתהוותו מאין ליש כו', הרי שהחיות של עובי הכדור הוא מידיעתו ית' דידיעתו ית' הוא מה שבידיעת עצמו יודע את הנבראים דהיינו הידיעה שבעצמות כו', ומזה הוא החיות של הארץ וכל הנבראים כו'. אך הנה חיות זה אינו במורגש בנבראים ומה שבא בהם במורגש הוא מהאור פנימי, הרי באמת כל הגילוים וההמשכות דהאו\"פ הכל הוא מהאו\"מ, וכמשנת\"ל פט\"ז ופכ\"ז דשרשי האורות שהן הע\"ס הגנוזות הוא מה שהאוא\"ס שיער בעצמו להאיר בבחי' מדה וגבול שזהו בחי' מל' דא\"ס כו'. וכן לאחר הצמצום כל המשכות האו\"פ הוא מהאו\"מ ונק' חיי החיים, וכמו מחי' החיים יתן לך חיים כו' שהוא המקור לכל האור והחיות פנימי שבעולמות כו', וכפי רצונו ית' באופני הגילוים כן הוא\nההמשכ' והגילוי בכל העולמות והספי' כו', וגם בחי' תוס' האור והגילוי הוא מבחי' האו\"מ להיות תוס' אור בהפנימי כו'. וכמו בזמן דעת"],[3601330262,"רצון למע' שנמשכים אז גילוי אורות נעלים, שהגילוים בעצם הן מבחי' אור פנימי ונמשכים דוקא בזמן עת רצון כו', וכמו בזמן ביהמ\"ק שהי' גילוי אוא\"ס בכל העולמות עד שגם למטה הי' מאיר גילוי אור, שהכל ראו גילוי אוא\"ס בביהמ\"ק, וכמ\"ש שלש פעמים בשנה יראה כל זכורך דכשם שבא ליראות כך בא לראות כו'. וידוע דראי' זהו מבחי' יחוד פנימי שהוא הגילוי דבחי' עצמות אוא\"ס ב\"ה, וה\"ז בחי' יושר בחי' או\"פ רק שזהו תוס' אור בהפנימי כו', והי' זה בזמן הרצון דוקא כו'. וגם בגשמיות הי' אז ריבוי השפעה והי' איש תחת גפנו כו', וכנודע דיחוד פנימי ה\"ז נשמה אל יחוד חיצוני דאו\"א כו', וע\"כ לפי שהי' אז בחי' יחוד פנימי דאו\"א הי' תוס' אורות גם בבחי' יחוד חיצוני דאו\"א כו'. וכן בעולמות העליונים הי' הריבוי ביותר וכמארז\"ל חגיגה די\"ג ע\"ב כתוב א' אומר אלף אלפי' כו' וכתוב א' אומר היש מספר כו', כאן בזמן שבהמ\"ק קיים וכאן בזמן שאין בהמ\"ק קיים שכבי' נתמעטה פמליא של מעלה שע\"י סילוק הרצון נתמעטה כו', וכמו ויתעצב אל לבו שגרם סילוק האור והחיות כו', ובזמן\nגילוי הרצון נמשך תוס' אור בבחי' אור פנימי כו'. הרי דבחי' אור הסובב באמת נמצא בכל העולמות וההשתל', וכמא' לית אתר פנוי מיני', ופועל בכל העולמות בבחי' ההתהוות והגילוי שבהם וגם בחי' תוס' אורות כו'. אך בכ\"ז המשכת האו\"מ ופעולתו הוא בהעלם כו', שעש\"ז נק' סובב ומקיף דהגם שזהו עיקר המקור והסיבה לכל דבר מ\"מ נק' מקיף לבד לפי שהוא בהעלם כו', וכמ\"ש בסש\"ב שם פמ\"ח דר\"ל סובב ומקיף מלמע' לענין בחי' גילוי השפעה, כי ההשפעה שהיא בבחי' גילוי בעולמות נק' בשם הלבשה שמתלבשת בעולמות, כי הם מלבישים ומשיגים ההשפעה שמקבלים, משא\"כ ההשפעה שאינה בבחי' גילוי אלא בהסתר והעלם ואין העולמו' משיגים אותה אינה נק' מתלבשת אלא מקפת וסובבת כו'. והיינו דזה שהאור הסובב נמצא בכ\"מ ופועל בכ\"מ אינו בבחי' התלבשות אור בכלי להיות מושג בעולמות, וכמא' לית מח' תפיסא בי' כלל שאינו שייך בזה שום תפיסא והשגה כלל כו', ואע\"ג דאיהו תפיס בכולהו עלמין לית מאן דתפיס בי' כו'. ופי' איהו תפיס בכולהו עלמין הוא מה שכל הגילוים וההמשכות הכל הוא ע\"פ רצונו\nית', וכן התהוות כל העולמות והנבראים והנהגתם שמנהיגם כרצונו וכמ\"ש כמצבי' עביד בחיל שמיא כו', ומ\"מ לית מאן דתפיס בי' כלל להיות להם תפיסא והשגה באוא\"ס לפי שאינו בגדר תפיסא והתלבשות כלל כו', והוא סובב ומקיף לכל העולמות וההשתל' בשוה, דמאחר שאינו מאיר בהם בגילוי ממילא אינו שייך בזה חילוקי מדרי' כו'. דהאו\"פ מאחר שמתלבש בגילוי בפנימיות יש בזה כמה חילוקי מדרי' באופן הגילוי בכל עולם ועולם ובכל ספי' כו', שלפי אופן העולמות והכלים כך הוא ההמשכה כו', והיינו לפי שכללות האור הוא בכדי לפעול כו'. ובשרשו הראשון לפני הצמצום הוא מה שאוא\"ס שיער בעצמו להאיר במדה וגבול כו', ולזאת ה\"ה בא בבחי' התלבשו' כו'. ויש מדידה באופן המשכת האור איך שהוא נמשך בכל מדרי' ומדרי' ולפי אופן כזה הוא התהוות הכלים והעולמות ומתלבש בתוכם להחיותם ולהאיר בהם כו', שהכל הוא בבחי' התחלקו' כו'. אבל האו\"מ דכללות האור אינו לפעול כ\"א הוא בבחי' גילוי מן העצם ובהמשכתו אינו בבחי' התלבשות פנימי כ\"א בבחי' מקיף כו', וע\"כ בהאו\"מ גופא אין בו התחלקות\nדמעלה ומטה וראש וסוף כו', וכמו\"כ אין התחלקות בהמשכתו בעולמות שסובב ומקיף כללות ההשתל' מרכ\"ד עד סוכ\"ד בהשוואה כו'."],[3601330263,"<span data-k=\"ks\"><b>קיצור.</b> ובאמת כל הגילוים וכל ההתהוות הוא מהרצון שהוא האו\"מ, דמהאו\"פ לבד להיותו בחי' גילוי פנימי א\"א להיות התהוות המציאות, כ\"א בכח האו\"מ דוקא (ואצי' הוא בחי' או\"פ), וכן חיות כל הנבראים הוא מידיעתו ית' שהוא בחי' או\"מ, וכמו\"כ למעלה שרשי האורות והגילוים הוא מהאו\"מ, וגם תוס' אור בהפנימי הוא מהאו\"מ, וכמו בזה\"ב שהי' עת רצון הי' גילוי אור גם למטה ברוחניות וגם בגשמיות, רק נק' מקיף מפני שאינו בבחי' התלבשות, שאינו מושג ומורגש בעולמות, איהו תפיס בכולהו ולמד\"ת בי', ולכן האו\"פ הוא בבחי' התחלקות בעולמות, משא\"כ האו\"מ דבעצם אינו בבחי' התחלקות וכן בהמשכתו בעולמות.</span>\nנט) <b>אמנם</b> עדיין צ\"ל והלא יש מקיפים פרטים לפרטי העולמות, וכמו כתר דאצי' וכתר דברי' עד כתר דעשי', שזהו מדרי' פרטיות בבחי' מקיף העליון שמקיף לכל עולם לפ\"ע העולם ההוא כו', א\"כ יש התחלקות מדרי' גם בהאו\"מ, כי ודאי אינו דומה האו\"מ דאצי' להאו\"מ דברי' כמו שאינו דומה עולם האצי' לעולם הברי' כו'. אך הענין הוא דהנה האו\"מ יש לו עכ\"פ שייכות אל הפנימי, וכמשנת\"ל פנ\"ב במשל בנפש שהכחות פנימים אינם תופסי' בהרצון אבל הרצון תופס בכל הכחות ומתחבר עמהם, רק שההתחברות אינו בבחי' התערבו' ממש להיות מתלבש ומתגלה בהם רק מתחבר עמהם בהעלם להיות הגילוי כפי אופן הרצון כו'. וכמו\"כ בבחי' רצון העליון שהוא בחי' האו\"מ הרי יש לו עכ\"פ אחיזה וחיבור עם הפנימי כו', וכמשנת\"ל פכ\"ז דשרש האו\"פ הוא מהאו\"מ דע\"ס הגנוזות זהו מה שאוא\"ס הבל\"ג שיער בעצמו להאיר במדה וגבול כו', וכמו\"כ האו\"מ פועל בהאו\"פ באופני הגילוים של האו\"פ להיות כפי אופן הרצון כו'. ומאחר שיש להמקיף שייכות אל הפנימי א\"כ שייך בזה ג\"כ מקיף כללי ומקיף פרטי, והוא\nהרצון בכלל בכללות העולמות וההשתל' והרצון פרטי בכל עולם בפרט כו'. והנה המקיף הכללי הוא בחי' הרצון הפשוט שבאוא\"ס שלפני הצמצום שעלה ברצונו להאציל ולברוא, הרי רצון זה הוא על כללות ההשתל' שכולל הכל כו', והוא בחי' טה\"ע שלפני הצמצום, וכמא' גליף גליפו בטה\"ע שזהו בחי' ההשערה מה שהאוא\"ס שיער בעצמו כללות העולמות וההשתל' כו', והאוא\"ס עצמו סובב ומקיף כולם בהשוואה כו', וקודם שנתהוו העולמות אינו שייך עדיין שהוא בחי' סובב רק מה שכולל את כולם כו'. אבל מ\"מ האוא\"ס עצמו הגם ששיער בעצמו כו', מ\"מ ה\"ה בבחי' הבדלה מהם (ועיקר בחי' הסובב הוא מה שלמע' מעלות הרצון והוא בבחי' התעוררו' כללי כו' וכמשי\"ת), וכולל כולם בהשוואה ממש כו' (וההשתל' גופא כמו שהן כלולים ברצונו ית' הן ג\"כ בהשוואה, וכמשנת\"ל פי\"ט וכ\"א בע\"ס הגנוזות שהן בבחי' התאחדות ממש מפני שאינם בבחי' מציאות לעצמן כלל כו', דכמו\"כ גם העולמו' כמו שהן לפני הצמצום הרי אינם בבחי' מציאו' כלל, וכמשנת\"ל ובכ\"ד בענין אותיות הרשימו שלפני הצמצום שאינם כלל בבחי' מציאות דבר\nח\"ו, וע\"כ לפני הצמצום הכל בבחי' אחדות וכולם הם בהשווא' כו', רק מ\"מ הרי יש ע\"ס רק שהן בפשיטות ובאחדות כו'. אבל האוא\"ס מקיף אותם בהשוואה, והיינו דלגבי' לא יש כאן התחלקות ע\"ס כלל, דרק בערך עצמן וכ\"ש בערכינו היינו בערך הגילוים הנמשכים מהם הן בבחי' ע\"ס והשתל' כו', אבל בערך הא\"ס היינו קמי' הם כולם שוים ולא יש התחלקות ספירות והשתל' כלל כו'. והגם דמ\"מ הרי האוא\"ס שיער"],[3601330264,"בעצמו להיות ע\"ס כו', מ\"מ אין האוא\"ס נתפס בהם שיהי' בבחי' התחלקות בערכו ית' כו'. וזה\"ע שהרצון עם היותו תופס בכל הכחות ומנהיגם כו', מ\"מ הם אינם תופסים בו כו', והיינו שאינו נתפס בהם להיות בו שינוי עי\"ז שהוא בעצם למע' מהתחלקות שלהם כו', וכמו\"כ יובן דעם היות שעלה ברצונו כללות ההשתל' מ\"מ אין הרצון נתפס בזה כלל וכולל כולם בהשוואה לגמרי כו'. והענין הוא דהנה נת\"ל דאור הוא שההמשכות והגילוים הכל הוא בבחי' אור, והיינו דלבד שההמשכות דאו\"מ גופא (וכמו המקיפים הפרטים) הן המשכות שבבחי' אור, הנה גם מה שנמשך ממנו בחי' האו\"פ (ובשרשו הוא בבחי' ההשערה ששיער בעצמו להאיר במדה וגבול כו'), דאור זה עצמו הוא בבחי' שפע עד\"מ, המשכתו מהאו\"מ היינו מאור הא\"ס, הוא בבחי' אור כו'. וכמו הרצון שפועל בכל הכחות לא בבחי' תפיסה בהם, כמו\"כ האוא\"ס הגם שהאו\"פ התהוותו ואצילותו הוא מהאו\"מ כנ\"ל פנ\"ח, מ\"מ ה\"ז בבחי' אור שאינו נתפס בהם כו', ועמשנת\"ל פכ\"ז דהשערה הנ\"ל הוא בחי' אחרונה שבאוא\"ס וא\"כ הכל הוא בבחי' אור כו'). וכמו\"כ אחר שנתהוו\nהעולמו' הנה האוא\"ס סובב ומקיף אותם כו'. והוא בחי' העיגול הגדול שלפני הקו שסובב ומקיף כללות ההשתל' מרכ\"ד עד סוכ\"ד בהשוואה ממש כו', ועז\"נ מעונה אלקי קדם ומתחת זרועות עולם ואי' במד\"ר הקב\"ה מעונו של עולם כו', והו\"ע הוא מקומו ש\"ע ואין העולם מקומו כו', וזהו ומתחת זרועות עולם שמקיף את כולם כו'. וכ\"ה גם בבחי' א\"ק, שזהו בחי' טה\"ת שאחר הצמצום, בחי' מחה\"ק ורצון הקדום על כללות ההשתל' שג\"כ סובב ומקיף כולם בהשוואה כו', וכידוע שכל מה שנתהווה בעולמות הכל כלול במחה\"ק דא\"ק והם שם בהשוואה, וכמא' צופה ומביט עד סוכ\"ד כו' וכולם נסקרי' בסקירה אחת כו' וכמ\"ש במ\"א. וכן גם אחר שנתהוו ה\"ה מקיף את כולם, וכידוע דעיגולי א\"ק מגיעים עד תחתית העשי' כו'. וכ\"ז הן בחי' מקיפים כללים לכללות העולמות, דטה\"ע בחי' מקיף הכללי שלפני הצמצום, וטה\"ת בחי' מקיף כללי שאחר הצמצום כו', וכמו\"כ יש מקיפים פרטים לכל עולם בפרט כו' וכמשי\"ת.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש כי תצא למלחמה על אויביך דהיינו המלחמה עם הנה\"ב, דמלחמה זו שייכה בכחות פנימים היינו בכחות הגילוים שבנפש כו'. וכמו למעלה הרי ידוע דאחיזת החיצונים יכול להיות באור פנימי, לפי שבא בבחי' התלבשות שזהו ע\"י צמצום ומיעוט האור ממדרי' למדרי' עד שבמדרי' התחתונות מתמעט האור ביותר, וע\"כ יכול להיות שם אחיזה ושם שייך מלחמה כו', אבל בהאו\"מ אינו יכול להיות אחיזת החיצונים, אדרבה האו\"מ מסמא עיני החיצונים כו'. וכמו\"כ הוא בנפש דבאורות מקיפי' דנפש דהיינו בהעבודה שלמע' מטו\"ד אינו שייך מלחמה כלל, ובהתגלות בחי' רצון פשוט מתבטלים כל החיצונים כו' (וזהו דביו\"כ אין שליטה להיצה\"ר מפני שאז מאיר מלמע' גילוי בחי' עצמות אוא\"ס, וכמו\"כ בנפש מאיר בגילוי עצמות הנפש כו', ע\"כ אין אז שליטה להיצה\"ר כו'), רק בכחות הגילוים שהן ע\"פ טו\"ד שם שייך אחיזה כו'. אך ע\"ז היא העבודה שע\"פ טו\"ד לעשות הבירור בנה\"ב, והיינו העבודה דתפלה בהתבוננות באלקות בענינים שהן בהשגה דוקא ובכאו\"א לפי ערך השגתו, ותכלית הכוונה שגם השכל הטבעי יבין וישיג את הענין האלקי והטוב והעילוי באלקות שעי\"ז יתעורר גם באהבה"],[3601330265,"לאלקות כו', ותחלה הוא בדרך הכנעה וביטול היינו שמסכים אל הביטול דנה\"א שלא יהי' לו למונע ומעכב כו', עד שגם הוא מתעורר באהבה שירצה באלקות דוקא כו'. וכ\"ז הוא בדרך מלחמה דלהיות שהעבודה היא בכחות המצומצמים שיש להם ערך אל הכחות הטבעים ה\"ה עומדים לנגד וכמא' שעת צלותא שעת קרבא כו', רק שהנה\"א מתגבר על הנה\"ב מפני שניתן לו כח ועוז לשלוט עליו, וזהו מכח המקיפי' שבנפש, וכמא' משביעין אותו תהי צדיק, וידוע הקושי' איך משביעין הנפש על הגוף כו'. אך הענין דמשביעין הוא ל' שובע, והוא הכח שנותנים לנה\"א מכח עצם הנשמה להיות בכחו להתגבר על הנה\"ב כו'. וכאשר הנה\"א מברר הנה\"ב מתוסף בו תוס' אורות דיתרון האור הוא מן החשך דוקא וכתיב ורב תבואות בכח שור כו'. וזהו כי תצא למלחמה אין אומרים צא אלא למי ששרוי בפנים כו', פנים הו\"ע המקיפים שבנפש דשם אינו שייך מלחמה כלל, וצ\"ל היציאה מבפנים היינו העבודה שע\"פ טו\"ד דוקא דכאן שייך המלחמה עם הנה\"ב כו', וכדאי היא המלחמה הזאת מפני היתרון אור שבא עי\"ז כו', ואין אומרים צא אלא למי ששרוי\nבפנים דהיינו שהכח ע\"ז הוא מעצם הנשמה דוקא שמשם נמשך כח לנה\"א להתגבר על הנה\"ב כו'. אמנם זה שהנה\"א פועל בהנה\"ב זהו הכל בבחי' אתכפי' לבד, ומ\"ש ונתנו ה' אלקיך בידיך זהו בבחי' אתהפכא חשוכא לנהורא היינו שנהפך מהות הנה\"ב לטוב כו', שזה אינו בכח האדם מעצמו כ\"א שנותנים לו מלמע' כו'. וע\"ד ומל ה' אלקיך את לבבך שהוא מלמע' דוקא, דעבודת האדם בכח עצמו הוא ומלתם את ערלת לבבכם שהיא ע\"י העבודה שע\"פ טו\"ד כו', אבל ומל ה' אלקיך כו' הו\"ע האהבה שלמע' מטו\"ד שזה נותנים מלמעלה, ועי\"ז נעשה אתהפכא חשוכא לנהורא כו'. והנה את לבבך ואת לבב ר\"ת אלול והיינו שאז הוא הגילוי מלמע' בחי' רעו\"ד שלמע' מטו\"ד ולהיות אתהפכא חשוכא כו' שהו\"ע ונתנו ה' אלקיך כו', רק שלזה צ\"ל תחילה כי תצא למלחמה בכח עצמו כמה שיכול לפעול בהנה\"ב ועי\"ז אח\"כ ונתנו ה' אלקיך בידיך כו'. וזהו ג\"כ דהגילוים דאלול ור\"ה תלוי' בהעבודה דכל השנה, דבכל השנה עיקר העבודה היא במוח ולב דהיינו ע\"פ טו\"ד כו', ולפ\"ע העבודה בכל השנה נותנים באלול ור\"ה ועשי\"ת התגלות עצם הנשמ'\nכו'. וזהו כי תצא למלחמה שצ\"ל היציאה מבפנים לעבוד עבודתו בתפלה ע\"פ טו\"ד בכדי לפעול הביטול בנה\"ב שעי\"ז דוקא נעשה יתרון אור כו', ואין אומרים צא אלא למי ששרוי בפנים היינו שהכח ע\"ז הוא מהמקיפים שבנפש רק שזהו בהעלם כו', ואח\"כ ונתנו ה' אלקיך בידיך שנותני' מלמע' התגלות עצם הנשמה שעי\"ז נעשה אתהפכא חשוכא לנהורא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וצ\"ל והלא יש מקיפים פרטים לעולמות, הענין הוא דהאו\"מ יש לו מ\"מ שייכות אל האו\"פ ונמשך ממנו, וע\"כ יש מקיף כללי ומקיפים פרטים, ובחי' טה\"ע שלפני הצמצום הוא בחי' מקיף כללי וכולל שרשי האורות כולם בהשוואה, כי בערך הא\"ס אינם בבחי' התחלקות, והגם ששיער בעצמו שרשי האורות אינו נתפס בזה, וגם שהן בכלל אור הא\"ס בחי' אחרונה שבו, ואחר שנתגלו ונתהוו מקיף כולם, ובחי' א\"ק הנק' טה\"ת ג\"כ בחי' מקיף כללי. וע\"פ הנ\"ל ית' פסוק כי תצא.</span>"],[3601330266,"<h3>בס\"ד. ש\"פ תבא, תער\"ב</h3>\n<b>והי'</b> כי תבא אל הארץ אשר ה' אלקיך נותן לך נחלה וירשתה וישבתה בה, וצ\"ל דמ\"ש כי תבוא אל הארץ משמע שזה בכח עצמו ואח\"כ אשר ה' אלקיך נותן לך ה\"ז בבחי' נתינה מלמע' כו'. ומה\"ע נותן לך וירשתה, דהרי מתנה וירושה הם ב' ענינים, וצ\"ל מהו ב' ענינים אלו לגבי הארץ כו'. גם צ\"ל מ\"ש וישבת בה הלא המתנה והירושה היא ג\"כ לישב בה ומהו אומרו עוד וישבת בה כו'. ובספרי מדייק מ\"ש והי' כי תבא אל הארץ ואו' עשה מצוה שבשכרה תכנוס לארץ, וצ\"ל מהו המצוה שבשכרה תכנוס לארץ, והלא נתינת הארץ היא שכר על כללות המצות וכמ\"ש בפ' עקב ושמרתם את המצות כו' ובאתם וירשתם את הארץ כו', וכן הוא כמה פעמים בתורה, וא\"כ מהו המצוה שבשכר' דוקא תכנוס לארץ כו'. ולהבין כ\"ז ילה\"ק משנת\"ל שיש ב' מדרי' אור פנימי ואור מקיף, דאו\"פ הוא שבא במדה וגבול שיש בו חילוקי מדרי' בעצם ובא בבחי' התלבשות ובבחי' התחלקות לפ\"ע העולמות והכלים כו', ואו\"מ הוא אור פשוט בעצם שאין בו חילוקי מדרי', ולזאת גם בהמשכתו בעולמות אינו בא בבחי' התלבשות בעולמות ומאיר בכולם בשוה\nכו'. ונת' דבאו\"מ גופא יש ב' מדרי' בחי' טה\"ע וטה\"ת. דטה\"ע הוא בחי' מקיף הכללי שלפני הצמצום והוא בחי' עיגול הגדול שלפני הקו שסובב ומקיף כללות ההשתל' מרכ\"ד עד סוכ\"ד כו'. ובחי' טה\"ת זהו בחי' מקיף הכללי שאחר הצמצום והיינו בחי' א\"ק שמקיף ג\"כ כללות ההשתל' כו'.\n<b>סמ\"ך)</b> ומעתה צ\"ל מהו ההפרש לגבי העולמות בין בחי' מקיף הכללי שלפני הצמצום לבחי' מקיף הכללי שאחר הצמצום, דודאי יש הפרש בין מקיף הכללי דטה\"ת למקיף הכללי דטה\"ע דהגם ששניהם מקיפים כללות ההשתל' בהשוואה כו', מ\"מ צ\"ל דטה\"ת הוא בבחי' קירוב יותר כו', ומ\"מ גם בחי' המקיף דטה\"ע בהכרח לומר שפועל בעולמות שהרי הוא בבחי' מקיף עכ\"פ אל העולמות, וא\"כ בהכרח לומר שפועל ג\"כ בעולמות כו', וצ\"ל מהו ההפרש ביניהם, וגם מהו פעולתם בהעולמות כו'. והנה פעולת המקיף דטה\"ת דהיינו בחי' מחה\"ק דא\"ק י\"ל עפמ\"ש במ\"א דמש\"א וכל קומה לפניך תשתחוה היינו בבחי' ציור קומה דא\"ק כו', דלהיות שבחי' א\"ק סובב ומקיף כללות ההשתל' הרי בהביטול דציור קומה דא\"ק כל הנבראים מתבטלים באמת לגבי אוא\"ס ב\"ה, דכמו שבחי' א\"ק להיותו בבחי' קירוב אל אוא\"ס ב\"ה ה\"ה בבחי' ביטול במציאות ובבחי' התאחדות ממש באוא\"ס ב\"ה, כמו\"כ באמת כל העולמות להיותם בתוך ציור קומה דא\"ק הסובב ומקיף אותם ה\"ה בטלים בעצם מהותם ומציאותם לאוא\"ס ב\"ה כו'. רק שהביטול הזה שמחמת ציור\nקומה דא\"ק הוא בהעלם מאד שאינו מורגש בנבראים כלל הביטול הזה כו'. וכמ\"ש במ\"א בענין ידיעה ובחירה שהידיעה העליונה שבבחי' א\"ק אינה מכרחת הבחירה, דהגם שיודע כל מעשה האדם והנהגותיו ופעולותיו קודם שעושה מ\"מ האדם אינו מוכרח משום זה בפעולותיו וה\"ה עושה בבחירתו בכח עצמו כו', וזהו לפי שהידיעה מובדלת בערך לגמרי שאינה מורגשת כלל בהאדם ע\"כ אינה מכרחת את הבחירה כו'. דכשם שידיעתו ית' אינה מכרחת ענין ההתהוות דהגם שיודע כל ההתהוו' קודם שנתהוו, מ\"מ אין זה מכריח את ההתהוות כו', ומה"],[3601330267,"שמבואר בכ\"מ דהעולמות תיכף כשעלו ברצונו ומחשבתו ית' מיד נתהוו כו', הרי לא נתהוו בבחי' מציאות יש (דמציאות היש ה\"ז התחדשות גמורה דקודם שנתהווה לא הי' מציאותו כלל דעש\"ז נק' יש מאין דבר מלא דבר כו' כידוע ומבואר במ\"א), כ\"א התהוות בכח לבד. רק שלמע' הכח אינו חסר הפועל, דלמט' הרי מחשבת האדם לא תפעול מאומה והי' כלא הי', ולמע' מהמח' נעשה הדבר בכח שהכח אינו חסר הפועל וה\"ה פועל כו', והרי ידוע שהפועל הוא כמו מדרי' הכח כו' וכמ\"ש מזה בדרוש יו\"ט של ר\"ה, רס\"ו, והיינו שזה שכשעלה ברצונו ומחשבתו ית' להוות העולמות כבר נתהוו בכח וה\"ז פועל, הנה הפועל הוא במדרי' הכח לא שנתהוו בבחי' מציאות יש בפועל כו'. והגם דהתהוות העולמות בפועל הוא ג\"כ מידיעה זו וכמ\"ש בסש\"ב פמ\"ח, שהרי ידיעה זו היא חיות כו' והתהוותו מאין ליש כו', זהו כשעלה ברצונו ית' להיות מזה ההתהוות כו' (וג\"ז ע\"י כמה צמצומים וכמ\"ש בסש\"ב שם רק שלא הי' מתהווה כמו שהוא עתה כו' אם לא ע\"י צמצומים כו'). אך הרי הי' הרצון והידיעה עוד קודם שנתהוו העולמות וכמ\"ש מגיד\nמראשית אחרית ומקדם אשר לא נעשה כו', והרי לא נתהוו בפועל מידיעה זו כו'. שזהו ג\"כ מכח הכל יכול דכשם שכחו הכל יכול הוא שתהי' ההתהוות מידיעתו ית', כמו\"כ כחו הכל יכול הוא שהגם שיודע כל ההתהוות ומ\"מ לא תהי' מזה ההתהוות בפועל כו', והיינו מפני שהידיעה היא בבחי' הבדלה לגמרי ע\"כ אינה מכרחת ההתהוות כו'. וכמו\"כ אחר שנתהוו הנבראים אין הידיעה מכרחת את הבחירה, דהגם שיודע כל מעשה האדם ופעולותיו קודם שעשה (ומשם באמת מקור הכח לפעולת האדם כו', ולא בבחי' מקור שהרי אינו בגדר מקור רק שמשם שרשו האמיתי כו'), אין זה מכריח את הבחירה לפי שהידיעה מובדלת בערך ואינה מכרחת אותו בפעולתו וה\"ה עושה בבחירתו בכח עצמו כו'. וכשם שהוא בידיעה ובחירה, כמו\"כ הוא בהביטול שכל הנבראים בטלים מצד בחי' ציור קומה דא\"ק אין זה מורגש כלל בנבראים, עד שעם היות שבאמת הוא בטל במציאות מצד הביטול דציור קומה דא\"ק, יכול להיות שבבחירתו יהי' להיפך ח\"ו ויהי' נפרד לגמרי מאלקות ר\"ל. וזהו רק שאינו מורגש הביטול אבל מ\"מ הרי הם בטלים עכ\"פ כו', וי\"ל\nדביטול זה מועיל עכ\"פ שיוכלו לקבל חיות מאלקות כו', וכנודע דהכלי לקבלת החיות מאלקות הוא הביטול דוקא וכמ\"ש יראת ה' לחיים דהכלי לחיות הוא יראה וביטול כו' (ולכן גם בקלי' וסט\"א בהכרח שיהי' בהם קצת ביטול עכ\"פ דקרי לי' אלקא דאלקיא כו'), וע\"י הביטול שבהם מצד הציור קומה דא\"ק יכולים לקבל קצת חיות עכ\"פ מאלקות כו', אך זהו בהעלם לגמרי.\n<span data-k=\"ks\"><b>קיצור.</b> והנה פעולת המקיפים כללים בעולם, הנה בחי' א\"ק שהוא בבחי' ביטול במציאות באוא\"ס הרי כל העולמות והנבראים הכלולים בו בטלים באמת במציאות, רק שאינו מורגש כלל בהנבראים, כמו שהידיעה דא\"ק אינה מכרחת הבחירה (כשם שידיעתו ית' אינה מכרחת התהוות העולמות בפועל) ותועלת הביטול הוא שיוכל הנברא לקבל חיות מאלקות.</span>\nסא) <b>וי\"ל</b> עוד עפמ\"ש בלק\"ת בד\"ה למנצח על השמינית דבחי' א\"ק הגם שלא שייך בו התלבשות בבחי' אור פנימי, מ\"מ הארת גילוי זה מוכרח"],[3601330268,"להיות בישראל כו', ובהגהות לשם מבואר שז\"ע מה שכנ\"י נק' כלה מל' כלתה נפשי שיש בכאו\"א מישראל בניצוץ נשמתו ליכלל ולידבק בה' אחד, ואה' זו יש בכח כאו\"א מישראל בתמידות, וכמ\"ש למען יזמרך כבוד ולא ידום קארי תדיר ולא שכיך, ואפי' בפחותי ערך וע\"ה יש בחי' זו רק שאינה בהתגלות מורגשת בנפשם תמיד רק מוסתרת בבחי' מקיף שומר עליהם מלמע', ולכן יש בכח כאו\"א מישראל למסור נפשו על קדה\"ש בלי שום טעם ודעת השגת אלקות רק בבחי' אמונה היינו שהיא מקיפו מלמע' מן השכל כו' (ועמ\"ש בלק\"ת בהביאורי' דוידעת פ\"ג בענין שהאמונה נק' עטרה כו'), ושרש האמונה בנש\"י הוא משום דמזלי' חזי כו', וזהו בשרש הנשמה למע' דהתקשרותה באלקות הוא משום דמזלי' חזי ורואה אמיתות אחדות ה' ע\"כ א\"א לה להיות נפרד ח\"ו (וצ\"ל דאין זה ענין ההתקשרות עצמית של הנשמה בעצמות א\"ס שזהו מפני שמושרשים בעצמות כו' וכמ\"ש במ\"א), אך למטה ה\"ז בא בבחי' אמונה כו' (ומבו' במ\"א דתוקף האמונה פשוטה שבנש\"י הוא משום דמזלי' חזי שה\"ה רואה אמיתות הדבר כו'). וי\"ל דשרש האמונה הוא עוד למע'\nמבחי' מזלי' כו', שהרי בראי' יש ג\"כ חילוקי מדרי' וכמ\"ש במ\"א, וי\"ל דכמו\"כ גם בהא דמזלי' חזי יש חילוקי מדרי' כו', משא\"כ האמונה ה\"ז בכולם בשוה לפי שנמשך ממדרי' עליונה יותר כו', ומזה הוא כח קדה\"ש שיש בישראל וגם בחי' האהבה מוסתרת שיש בכאו\"א בהעלם ליכלל ולידבק כו'. וע\"ז יש בחירה בכ\"א מישראל להוציאה בהתגלות מהסתירה שיאיר גם בשכלו ומוחו ובלבו, והוא בחי' כלה כלות הנפש לשרשה ומקורה בלבו ונפשו ובמאודו ממש כו', וזהו מהארת בחי' א\"ק שיש בבחי' מקיף בנש\"י להיות בבחי' כלות הנפש ולמסור נפשו כו', והיא בהעלם בנש\"י וביכולתו להביא זה מההעלם אל הגילוי כו' (ועמ\"ש בלק\"ת שם דהארה זו היא מבחי' פנימיות א\"ק והיא בנש\"י דוקא להיות שישראל עלו במח', דפי' עלו במח' היינו בבחי' עליונה שבמח', והוא שבמחה\"ק דא\"ק עלו בבחי' הפנימיות ונמשכה הארה משם לכאו\"א מישראל כו', והביטול דוכל קומה לפניך תשתחוה הנ\"ל י\"ל שזהו בבחי' חיצוניו' א\"ק שיש ביטול זה בכל הנבראים ואינו בהם בבחי' הרגש כלל כו'). ועוד יובן ענין הארת בחי' א\"ק שבכאו\"א מישראל\nשהו\"ע הקדמת נעשה לנשמע וכדאי' במשנה דברכות למה קדמה שמע לוהא\"ש בכדי שיקבל עליו עומ\"ש תחלה ואח\"כ יקבל עליו עומ\"צ, וידוע דקבלת עומ\"ש הו\"ע הביטול לא\"ס בעל הרצון לרצות כל מה שהוא רצונו ית' בקיום המצות כו'. וזהו\"ע הקדמת נעשה לנשמע דנשמע הוא לקבל גילוי הרצונות פרטים וא\"כ הביטול הוא אל הרצון, ונעשה קודם לנשמע הוא הביטול לאוא\"ס בעל הרצון כו', והוא שמקבל עליו ביטול הרצון בכלל שיהי' לו רצון בכל אשר ישמע מהקב\"ה כו'. ועם היות דקבעומ\"ש הוא לא בבחי' התגלות הרצון שז\"ע קבלת עול שהוא בבחי' כח נעלם כו', והקבלה היא לעשות בפו\"מ לא דוקא מה שרוצה כ\"א גם אם יכבד עליו הדבר אין בזה שום תירוץ ולא שום מניעה ועיכוב כלל כו', הנה באמת הוא כח נעלם, אבל מ\"מ הרי יש בזה רצון והו\"ע קבלת עול מלכותו ית' ברצון כו', רק שאינו בהתגלו' הרצון בבחי' יציאה מהדרגה, אבל יש בזה רצון חזק ותקיף בנפש כו'. דענין התגלות הרצון הוא בהתפעלות בנפש וביציאה מגדר כלים ובקבעומ\"ש אין בזה יציאה מהדרגה כו', ואפי' בקבעומ\"ש דר\"ה שהוא בהתגלות הרצון אין זה בהתפעלות בנפש כ\"א הוא בבחי' מסירה ונתינה בכל עצמותו שמוסר ונותן כל"],[3601330269,"עצמו ומהותו לאלקות והוא בגילוי בנפשו כו', דקבעומ\"ש דכל השנה אינו בגילוי בנפש וקבעומ\"ש דר\"ה הוא בגילוי בנפשו, אבל אין זה בבחי' יציאה מגדר כלים כו', ומ\"מ הרי הקבעומ\"ש דר\"ה הקבלה היא ברצון חזק בנפש כו'. וידוע ג\"כ דבעבודת עבד יש בזה תענוג מה שמשלים רצון האדון כו', וזהו\"ע שמחה של מצוה דבקיום המצוה בפו\"מ צ\"ל בזה שמחה, וכמ\"ש תחת אשר לא עבדת כו' בשמחה ובטוב לבב כו', ועם היות דעבודה בשמחה היא בכוונת המצות מפני שבאופן עבודה זו הוא יודע ומרגיש שעושה איזה דבר וגם ממשיך בזה גילוים בעולם וגילוים בנפשו דמשו\"ז הוא השמחה כו', משא\"כ בקבעומ\"ש אין בו ההרגש שעושה איזה דבר בעבודתו, וגם אין כוונתו בזה להמשיך גילוים בעולם וכ\"ש להמשיך גילוים בנפשו רק לעשות רצה\"ע לבד כו', מ\"מ יש בזה שמחה מזה שמשלים את הרצה\"ע כו'. וכמו עד\"מ אדם פשוט כשמשלים רצון דאדם גדול ה\"ה בשמחה גדולה מזה, וכמו\"כ הוא השמחה בקיום המצות מה שמשלים את רצה\"ע כו'. ולמע' מזה הוא שמתענג בהתענוג שיהי' להאדון כו', והיינו שמתענג בהתענוג שלמע' דנח\"ר לפני\nשאמרתי ונעשה רצוני כו', דהתענוג שלמע' זהו תענוג שלו כו' וכמ\"ש במ\"א ועמשית\"ל פקע\"ד, הרי דבקבעומ\"ש יש בזה רצון ותענוג כו', ומה שנק' קבלת עול אין זה שהוא רק בדרך עול והכרח כ\"א מה שזהו בדרך נתינה ומסירה (איבער גיגעבינקייט) לא ע\"פ טעם ודעת כ\"א מה שמוסר א\"ע להיות עבד כו', דענין הנתינה והמסירה (דיא זאך פון איבער גיגעבינקייט) יש ג\"כ במשפיע ומקבל או באוהב ונאהב, שהמקבל או האוהב מוסר עצמו אל המשפיע או הנאהב, אך זהו ע\"פ טו\"ד דהמקבל מפני שמקבל השפעה מהמשפיע כמו השפעת השכל וכה\"ג וההשפעה טוב לו, הרי נעשה הקירוב באופן כזה שמוסר עצמו אליו כו', וכמו\"כ באוהב ונאהב שזהו מצד ידיעתו בהעילוי שלו ה\"ה מתקרב אליו ומוסר עצמו כו'. משא\"כ ענין העבדות הוא שלא מצד הידיעה בעילוי האדון ולא מצד ההשפעה שמקבל ממנו כו' (שהרי עבדא בהפקירא ניחא לי', שכן הוא גם ברוחניו' שלא טיב ההשפעה הוא שפועל עליו כו'), כ\"א הוא נתון ומסור ונתון אליו רק משום העבדות שקיבל עליו להיות לו עבד כו', וזהו שנק' קבלת עול לשלול שאין זה מצד הטו\"ד רק\nמשום עול העבדות שקיבל על עצמו כו'. אבל באמת יש בזה רצון ותענוג כו' (רק שג\"ז אינו בהגילוים כ\"א בהעצם כו' כנ\"ל), רק דענין קבעומ\"ש הוא שלא יהי' מניעה ועיכובים כלל אפי' בהדברים שלא יש לו רצון בהם והם היפך רצונו, אך זהו מדרי' תחתונה בעבדות והו\"ע עבד כנעני שאין לו שום רצון ועושה רק מצד עול האדון שעליו כו', אבל אמיתית ענין קבעומ\"ש הוא שיש לו רצון ותענוג בעבודתו רק שאין זה לצורך עצמו כו' כנ\"ל. וכח זה הוא בנש\"י מפני שמושרשים בבחי' א\"ק כו', דהנה א\"ק נק' רעוא דכל רעוין בחי' רצון לרצון כו', ומשם נמשך בנש\"י כח זה בבחי' ביטול הרצון לרצות כל מה שהוא רצונו ית' כו'. וז\"ע ויכתוב משה מוצאיהם למסעיהם, דמוצאיהם הוא מל' וכמוצא מים כו', והוא מקור נש\"י כמו שמושרשים בא\"ק כו', ומשה שהוא שושבינא דמלכא המשיך בנש\"י משרשם ומקורם כמו שהן בעצמות אוא\"ס ב\"ה בחי' פנימיות א\"ק כו', ועמ\"ש בלק\"ת ע\"פ זה, ושם דההמשכה היא למסעיהם שיוכלו להתעלות מלמטלמ\"ע בבחי' בכל מאדך כו'. וי\"ל דהכח נעלם להיות קבעומ\"ש הנ\"ל יש בעצם בנש\"י (וי\"ל\nשזהו מירושה מהאבות וכענין האהבה מוסתרת שיש בכאו\"א בירושה לנו מאבותינו כו', ועמ\"ש בסש\"ב פי\"ח וי\"ט), ומה"],[3601330270,"שהמשיך משה הוא שיהי' התגלו' הרצון הו\"ע אהבה דבכל מאדך בכח ההמשכה משרשם ומקורם כו' (וממ\"ש בהבי' שם נר' שזהו הביטול דקבעומ\"ש כו').\n<span data-k=\"ks\"><b>קיצור.</b> גם מהארה דא\"ק הוא הכח למס\"נ על קדה\"ש, גם בחי' האהמ\"ס, ובבחירתו יביאה לגילוי במוח ולב שז\"ע בחי' כלה כלות הנפש (והוא מפנימיות א\"ק ובנש\"י דוקא), גם י\"ל דמשם הוא כח הביטול דהקדמת נעשה לנשמע שהוא הביטול לבעהר\"צ, והו\"ע קבעומ\"ש, והגם שזהו בהעלם מ\"מ ה\"ז בתוקף גדול, ויש בזה שמחה מזה שמשלים רצה\"ע, ומהתענוג שלמעלה, ונק' קב\"ע מפני שהוא הנתינה והמסירה לא ע\"פ טו\"ד (ולא כמו במשפיע ומקבל שזהו מצד הידיעה והקבלה), והו\"ע מוצאיהם למסעיהם.</span>\nסב) <b>וכ\"ז</b> הוא במקיף דא\"ק דמ\"מ יש לו שייכות אל העולמות הגם שהוא בבחי' מקיף הרחוק כו', וע\"כ נמשך משם איזה הארה בגילוי בנשמות כו'. אבל בחי' טה\"ע שזהו בחי' העיגול הגדול שלפני הקו, הגם שזהו ג\"כ בבחי' מקיף לעולמות אחר הצמצום כו', אין לזה שייכות אל העולמות ואינו נמשך מזה הארה בגילוי כו'. אמנם ידוע דשרש הכלים הוא מבחי' האו\"מ דוקא, וכמ\"ש בע\"ח דהתהוות הכלים הוא ע\"י הכאת או\"מ באו\"פ, ועיקר שרשן הוא מהאו\"מ וכמ\"ש מזה בתו\"א בהבי' הב' דיביאו לבוש מל', וזהו שהכלי היא עגולה דשרשה הוא מהאו\"מ כו' וכמ\"ש במ\"א. ולפ\"ז י\"ל דכח הביטול של הכלי הוא מהאו\"מ מבחי' העיגול הגדול כו'. דהנה האור פנימי הוא בבחי' התלבשות בגילוי בהכלים ופועל ביטול בהכלים כו', שהרי הכלים הם בבחי' מציאות והאור הוא בבחי' אין כו', רק שיש חילוקי מדרי' באור בחי' או\"מ ואו\"פ כו', אבל כללות ענין האור הוא בבחי' אין כו', וע\"כ האור פועל הביטול בהכלים כו' שיהיו ג\"כ בבחי' אין כו' (ועמשית\"ל פ'). אך הכח בהכלים להיות בהם בחי' הביטול ע\"י האור,\nועוד זאת שהביטול יהי' באופן כזה בבחי' ביטול בעצם מהותם שיתייחדו באוא\"ס ב\"ה, זהו מבחי' המקיף דטה\"ע שרש ומקור הכלים כו', והביטול של הכלי מגיע למעלה מהביטול של האור כו'. והענין הוא עפמ\"ש במ\"א על מאמר הפדר\"א גבי אילו של יצחק פשט האיל את ידו ונגע בטליתו של אאע\"ה כו', ומבו' שם דאברהם הוא בחי' גילוי הקו וכמ\"ש מי העיר ממזרח דא\"ת העיר אלא האיר והוא בחי' גילוי הקו דשרשו מת\"ת הנעלם כו' וכמ\"ש במ\"א, וטליתו של אברהם הוא בחי' העיגול הגדול שלפני הקו כו', וע\"י העקידה דיצחק שהוא מסירת הגוף בפו\"מ שנעשה קרבן כו', עי\"ז פשט האיל כו' ונגע בטליתו של אאע\"ה שהגיע בבחי' המקיף דעיגול הגדול כו'. דהנה ידוע דמסירת הגוף מגיע למעלה יותר ממסירת הנפש, וכמ\"ש במ\"א בענין ויתהלך חנוך את האלקים ואיננו דזהו שנכלל בבחי' האין האמיתי דעצמות אוא\"ס ע\"י ביטול גופו דוקא כו', ובד\"כ המס\"נ שבגוף דוקא מגיע הרבה יותר מהמס\"נ שמצד הנשמה כו', ובפרט בהביטול הגוף באופן כזה שמתאחד ממש עם האלקות, וכמו בחנוך ואלי' שגופם נעשה גוף אלקי כו'. וי\"ל\nשזהו ג\"כ מעלת הקרבנות מה שהבשר והחלב הגשמי נכלל באש שלמעלה כו', וכה\"ג הוא בתענית שהחלב ודם נכלל באלקות כו', וזהו מעלת יוה\"כ בעינוי הגוף שמגיע למעלה מהתשובה כו' וכמ\"ש במ\"א. והביטול הזה שהגוף מתאחד באלקו' י\"ל שזהו מגיע"],[3601330271,"בבחי' המקיף הכללי כו'. וזהו דלעתיד שיהי' אז גילוי בחי' המקיף הכללי, וכידוע בענין יהללו שמו במחול דשמו הוא בחי' הקו ומחול הוא בחי' העיגול הגדול הסובב ומקיף כו', ולעתיד יהי' חיבור ב' המדרי', וכמ\"ש במ\"א דלעתיד יהי' הקו גם בקצהו התחתון נוגע ודבוק בהאוא\"ס הסובב מתחת העולמות כו', ועי\"ז יהי' ע\"י הקו גילוי בחי' אוא\"ס הסובב ממש כו', ועמ\"ש מזה בד\"ה יו\"ט של ר\"ה, רנ\"ט. וע\"כ יהי' היתרון דלעתיד מה שהגוף יהי' אלקות שזהו ע\"י גילוי בחי' מקיף הכללי כו', ומגיעים לזה ע\"י ביטול והתאחדות הכלים דוקא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם מבחי' טה\"ע הוא שיש כח הביטול בהכלים, ושיתבטלו בעצם מהותם, דשרש הכלים הוא מהאו\"מ, וע\"כ מסירת הגוף דוקא מגיע בבחי' עצמות אוא\"ס, ולעתיד שיהי' ע\"י הקו גילוי בחי' העה\"ג שלפני הקו, יהי' הגוף הגשמי אלקות.</span>\nסג) <b>והנה</b> ב' המדרי' דטה\"ע וטה\"ת הם בחי' מקיפים כללים לעולמות, ויש ג\"כ מקיפים פרטים והו\"ע כתר דאצי' שזהו בחי' רצון להאציל האצי', וכן כתר דברי' לברוא עולם הבריאה עד כתר דעשי' שהוא בחי' רצון פרטי לעולם העשי' כו'. והענין הוא דהנה הרצון הפשוט שבאוא\"ס שלפה\"צ הגם שזהו מה שעלה ברצונו ית' להאציל ולברוא כו', ובפרט בחי' מחה\"ק דטה\"ת שהיא בבחי' שייכות אל העולמות (שהרי הרצון פשוט שלפני הצמצום הגם שזהו רצון על כל מה שנתהווה ושיער בעצמו בכח כל מה שעתיד להיות בפועל כו', הרי אין העולמות שם בבחי' מציאות כלל וכלל, משא\"כ במחה\"ק דא\"ק הרי נתהוו במח' זו כו'), מ\"מ הרי במח' זו הכל עדיין בבחי' העלם ובבחי' התכללות לגמרי עד שעומדים כולם בהשוואה לגמרי כו'. וכנודע דבא\"ק הרי אצי' ועשי' הן בהשוואה ממש כו', והוא משום ב' דברים הא' י\"ל דכמו שהן בא\"ק האור והגילוי שוה בכולם, הגם שאח\"כ בהתהוותם בפועל הרי רחוק מאד ערך העשי' לגבי האצי', דבאצי' מלובש אוא\"ס שמאיר בגילוי בכלים דאצי' ואיהו וגרמוהי חד כו', ובי\"ע הם\nנפרדים כו', מ\"מ כמו שהן בא\"ק י\"ל שהאור בהם בשוה כו'. דכשם שאחר שנתהוו הרי מחה\"ק דא\"ק סובב ומקיף את כולם בשוה דעיגולי א\"ק הם מתחת לעשי' כו', כמו\"כ בהתכללותם במחה\"ק קודם שנתהוו ה\"ה כולם בשוה בבחי' האור והגילוי כו'. וכמו בהתגלות הכחות העצמיים הרי אור הנפש מאיר בכולם בשוה, הגם שהם מחולקים בעצם מדריגתן כו' וכמשנת\"ל פכ\"ב, ומכ\"ש דכשהן כלולים בהעצם שמאיר בהם האור בכולם בשוה, וכמו\"כ בהעולמות והספי' כמו שהן כלולים בא\"ק מאיר בכולם האור בשוה כו' (והנה אחר שנתהוו הרי באצי' מאיר בגילוי קצת עכ\"פ משא\"כ בעשי', וכמו הרצון שבמוח ה\"ה מאיר בגילוי עכ\"פ כו' וכמ\"ש במ\"א וית' לקמן בעזה\"י, הנה זהו עיקרו בבחי' הרצון הפרטי כו', וענין המח' שבמוח הוא בגילוי וברגל בהעלם י\"ל שזהו בחי' היושר דא\"ק כו'). והב' לפי שבמחה\"ק דא\"ק הן בבחי' העלם לגמרי, שאינן בבחי' מציאות דבר להיות בבחי' התחלקות המדרי', לפי שכולם כלולים ממש בבחי' מח' זו בבחי' בלתי מציאות ניכרת כלל כו', ועמ\"ש מזה בד\"ה יו\"ט של ר\"ה, רס\"ו, איך שבא\"ק הן בבחי' פשיטות מהגדרה לגמרי כו', וכמשנת\"ל פי\"ט בהע\"ס הגנוזות באוא\"ס שלפני הצמצום, כמו\"כ בהספי' והעולמות כמו"],[3601330272,"שכלולים בא\"ק כו' (ומשו\"ז יכולים כולם לקבל את האור בשוה כו'). וע\"כ בכדי להיות התהוות העולמות בפועל ובבחי' עולמות מחולקות במדריגתן, צ\"ל רצון פרטי לכל עולם בפרט כו'. והמשל בזה הוא כמו אדם הבונה איזה בנין הרי תחלה הוא הרצון על הבנין בכלל, ועם היות שברצון זה כבר נמצא איך יהי' הבית בציור החדרים והעליות והפתחים וחלונות וכן בהעצים והאבנים ועפר כו', מ\"מ הרי כ\"ז אינו ניכר עדיין ברצון בדרך פרט כ\"א הוא הרצון על הבית בכלל כו', ואח\"כ כשבא לפועל יש רצון פרטי לכל חדר ועלי' ולכל דבר בפרט כו'. וכמו\"כ הוא הדוגמא למעלה דבחי' מחה\"ק הוא המח' והרצון על העולמות בכלל שכולם שם בהעלם עדיין, ואח\"כ נמשך רצון פרטי לכל עולם בפרט כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש והי' כי תבא אל הארץ אשר ה' אלקיך נותן לך, דהנה ארץ הוא ל' רצון וכמארז\"ל למה נק' שמה ארץ שרצתה לעשות רצון קונה כו', והו\"ע הרצון פשוט שבנפש כו', ועז\"א אשר ה' אלקיך נותן לך דהתגלות הרצון פשוט זהו שנותנים מלמע' כו', וז\"ע נחלה דהיינו בחי' מקיפים שבנפש, וכמ\"ש נחלה עבר על נפשינו כו' וכמ\"ש במ\"א. אמנם בכדי לבוא לבחי' רצון פשוט צ\"ל תחלה העבודה שע\"פ טו\"ד וזהו כי תבא אל הארץ כו', דהנה אית רצון ואית רצון, אית רצון שע\"פ טו\"ד, ואית רצון שלמע' מטו\"ד, וצ\"ל תחלה הרצון שע\"פ טו\"ד ועי\"ז נעשה כלי לגילוי הרצון שלמע' מטו\"ד כו'. וזהו\"ע התפלה שהיא ההתבוננות בפסוד\"ז וברכות ק\"ש כו', דפסוד\"ז הו\"ע ההילולים והתשבחות דבריאת והתהוות העולמו', וברכות ק\"ש ההתבוננות בביטול המלאכים, ובק\"ש ביטול הנשמות בהשגתם באלקות וכמש\"א שמע ישראל כו', דכ\"ז הוא העבודה שע\"פ טו\"ד ועי\"ז בא בשמ\"ע להביטול שלמע' מטו\"ד כו', וכידוע שהתפלה נק' סולם שמוצב ארצה היינו העבודה שע\"פ טו\"ד וראשו מגיע השמימה בבחי' המקיפים\nשבנפש כו', וזהו מה שה' אלקיך נותן כו'. אמנם ענין וירשתה הוא ירושת הארץ מהז' עממין, דבעבודה הוא בירור הז\"מ דנה\"ב בבחי' אתהפכא חשוכא לנהורא שעי\"ז יורשים אורות דתהו שלמע' מתיקון כו', והוא שמגיעים אל האור מקיף ע\"י ביטול החומריות דוקא כו', דשרש החומריו' הוא מהכלים וע\"י שפועל בעצמו ביטול החומריות נעשה תיקון וביטול הכלים למעלה, שזה מגיע להאו\"מ דטה\"ע כו' כמשנת\"ל. וידוע ההפרש בין ירושה למתנה דמתנה יש לה הפסק וירושה אין לה הפסק, דהנה האה' שע\"פ טו\"ד חולפת ועוברת אחר התפלה וממילא חולף ועובר גם האה' שלמע' מטו\"ד, שהרי הכלי לזה היא האהבה שע\"פ טו\"ד, וכאשר נפסקה אה' זו ממילא נפסקה גם האה' שלמע' מטו\"ד כו', אבל ירושה שהוא ע\"י בירור הנה\"ב בבחי' אתהפכא אין לזה הפסק כו'. והנה ב' מדרי' אלו דמתנה וירושה שניהם הם בבחי' מקיף כו', אמנם ענין וישבת בה הוא שיהי' בבחי' פנימיות והיינו שהמקיף יאיר בפנימיות וע\"ד לע\"ל שיהי' התחברות האו\"מ ואו\"פ כו' כנ\"ל. ובעבודה הו\"ע התורה שאחר התפלה דתורה הוא בחי' או\"פ ובתורה שאחרי התפלה\nמאיר המקיף בפנימיו' כו', דהרי העבודה בבחי' אהבות הנ\"ל והעבודה דבירור וזיכוך הנה\"ב הרי כ\"ז הוא בתפלה, רק שבתפלה הוא בבחי' מקיף ובתורה ה\"ז בא בבחי' פנימי כו'. וזהו בכללות השנה וכמו\"כ בדרך פרט באלול ור\"ה ויו\"כ וחה\"ס, דהנה בר\"ה הוא קבעומ\"ש שזהו בבחי' גילוי אור עצמיות הנפש וכמשנת\"ל דכן הוא למע' שמאיר אז"],[3601330273,"גילוי העצמיות וכמ\"ש חשף ה' את זרוע קדשו כו', וכן התשובה דר\"ה היא בחי' תשובה עילאה והו\"ע והרוח תשוב אל האלקים אשר נתנה שזהו בהתגלות עצמיות הנשמה כו'. וההכנה לזה הוא באלול בבחי' תשובה תתאה, שהיא היציאה מן הרע כשמתמרמר על ריחוקו מאלקות בפרטי מחדו\"מ שלו, שעי\"ז הוא היציאה מן הרע כו', ה\"ז הכנה לתשו\"ע דר\"ה כו', דתשו\"ת זהו בכח כאו\"א לבוא לזה בכח עצמו, דכשם שהעבודה שע\"פ טו\"ד היא בכח עצמו כמו\"כ תשובה תתאה היא ג\"כ בכח עצמו, דכאשר הוא ממארי דחושבנא בפרטי הענינים שלו ומתמרמר בנפשו מאד ע\"ז (אז עס ווערט עם באמת ניט גוט פון דיא אלע ענינים שלא לה' המה ובפרט בענינים ההפכים לגמרי כו', דמרירות אמיתי הו\"ע עקירת הרצון כו'), ה\"ה עושה הסכם חזק בנפשו שלא יהי' עוד כזאת ולא ישוב לכסלה עוד כו'. שהזמן המסוגל לזה הוא בימי אלול, ובפרט בימי הסליחות דאז צריך לפשפש במעשיו ולהתמרמר עליהם ולעשות הסכם חזק על להבא כו', שעי\"ז הוא היציאה מן הרע כו'. ועי\"ז נעשה כלי לתשו\"ע דר\"ה, שזהו ע\"י הגילוי העצמיות מלמע' כמ\"ש חשף ה' כו'\nשעי\"ז הוא גילוי עצמיות הנפש כו'. ואח\"כ ביו\"כ מאיר גילוים נעלים ביותר שזהו ע\"י עינוים דיוה\"כ במיעוט החלב והדם, שעי\"ז מאיר בחי' המקיף דטה\"ע וכמ\"ש כי בענן אראה, אראה בעצמותו, והוא ע\"י הענן דוקא ענן הקטרת שהו\"ע בירור הרע דנה\"ב בבחי' אתהפכא כו' וכמ\"ש במ\"א. וכ\"ז הוא בבחי' מקיף. ואח\"כ בסוכות מאיר המקיף בפנימי, שז\"ע בסוכת תשבו שיהי' בבחי' התיישבות בפנימיות כו'. וזהו בכסה ליום חגינו דכל ההמשכות דר\"ה ויו\"כ עיקר הגילוי שלהם הוא בסוכות והיינו שאז מאיר בבחי' פנימיות כו'. וזהו והי' כי תבא אל הארץ, דארץ הוא בחי' הרצון פשוט שבא בבחי' נתינה מלמע', רק שצ\"ל כי תבא אל הארץ בהעבודה שע\"פ טו\"ד שזהו בכח עצמו והיא הכלי כו'. וע\"ז אמרו בספרי עשה מצוה שבשכרה תכנוס לארץ היינו העבודה דתפלה בהתבוננות באלקות, שזהו בכח עצמו ויגיעתו לבא להאהבה שעפ\"י טו\"ד, ועי\"ז ה' אלקיך נותן לך האהבה רבה שלמע' מטו\"ד כו'. ועוד זאת שיהי' ירושת הארץ ע\"י הבירור דנה\"ב שעי\"ז נמשך גם בחי' המקיף דטה\"ע כו', וישבת בה הוא בעסק התורה שאחר התפלה שהאו\"מ מאיר בפנימיות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה בהמקיפים כללים הנ\"ל, הרי כל הספי' והעולמות הן בבחי' התכללות לגמרי, הן בבלתי מציאות במהותן ומדריגתן והן בהגילוי ששוה בכולם, וע\"כ צ\"ל רצון להתהוות כל עולם, ועד\"מ רצון כללי ורצון פרטי. וע\"פ הנ\"ל ית' פסוק והי' כי תבוא.</span>"],[3601330274,"<h3>בס\"ד. ש\"פ נצבים, תער\"ב</h3>\n<b>אתם</b> נצבים היום כולכם לפני ה' אלקיכם ראשיכם שבטיכם כו', וידוע דבכ\"מ שנא' היום קאי על יום דר\"ה, וכמו\"כ מה שנא' כאן היום קאי ג\"כ על ר\"ה, דבר\"ה נצבים כולם לפני ה'. וצ\"ל מהו\"ע דבר\"ה דוקא נצבים כולם לפני ה' כו'. והנה נצבים הוא ל' נפעל שנפעלים מלמע', וצ\"ל מה\"ע שנש\"י נפעלים מלמע' כו'. גם צ\"ל מה שמפרט פרטי המדרי' שבנש\"י, ראשיכם שבטיכם זקניכם כו', והלא אומר תחלה כולכם כו', ולמה צריך לפרט כל המדרי' בפרט כו'. ולהבין כ\"ז יש להקדים משנת\"ל דאוא\"ס הבל\"ג שבא בבחי' מקיף לעולמות יש בזה ב' בחי' מקיפים בחי' מקיף הכללי ומקיף הפרטי, דמקיף הכללי (שאחר הצמצום) הוא בחי' מחה\"ק דא\"ק ומקיף הפרטי זהו בחי' כתר דאצי' כו'. דהנה מחה\"ק דא\"ק הגם שכולל הכל מ\"מ לא הי' אפשר להיות מזה ההתהוות בפועל כי במחה\"ק כל העולמות הן בהשוואה כו'. ונת' דההשוואה היא בב' ענינים, הא' בהגילוים די\"ל דכמו שהן בא\"ק מאיר בעשי' בשוה כמו באצי' כו', והב' שהן שם בבחי' מציאות בלתי ניכרת וממילא ה\"ה שם כל העולמות בלי התחלקות כלל כו'. ובכדי שיהי'\nמציאות העולמות ובהתחלקות צ\"ל לזה רצון פרטי בכל עולם כמו שהוא כו', וז\"ע בחי' כתר דאצי' שזהו רצון פרטי לעולם האצי' כו'.\nסד) <b>ועוד</b> יובן מה שצ\"ל רצון פרטי לעולמות דהגם דמחה\"ק דא\"ק כוללת כל העולמות, מ\"מ צ\"ל רצון פרטי לעולמות כו'. דהנה ידוע שיש ב' בחי' רצון, והיינו גם בהרצון שלמע' מהטו\"ד יש ב' מיני רצונות (והן בחי' רצון הנעלם ורצון הגלוי או כח הרצון ורצון כו'), הא' הוא רצון ממש דהיינו כשיחפוץ באיזה דבר עד שתמשך נפשו אליו ממש ויטה לדבר ההוא להדבק אליו ולהשיגו כו', שז\"ע הרצון שהוא ההטי' וההמשכה לאיזה דבר כו', ואין זה משום איזה טעם והשגה שהטעם יהי' סיבת הרצון שלולא הטעם לא ירצה בזה, רק מה שמצד עצמו הוא רוצה ונמשך לזה כו' (ובודאי יש בזה איזה כוונה פנימית, אבל גם הכוונה אין זה בבחי' טעם והשגה כו'. דהנה יש רצון שהוא למע' מהכוונה לגמרי ואין בזה שום כוונה כלל והוא רצון עצמי שמצד העצמות ממש, וכמו עד\"מ רצון האב אל הבן או רצון הבן אל האב שהוא רצון עצמי בלי שום כוונה כו', שלפעמים ה\"ז בא בהתגלות שנמשך ומשתוקק מאד בגעגועים גדולים, והוא רק מצד העצם היינו לפי שהוא עצמו ומהותו ואין בזה שום כוונה כלל כו', ואינו\nנוגע בזה כלל איכות האב או הבן איך דהוא כו', והתגלות הרצון הזה הוא שהעצמי ממש נמשך ונתגלה בזה כו'. והדוגמא מזה למע' הוא בהרצון עצמי דעצמות א\"ס בנש\"י שזהו רק מפני שמושרשים בעצמותו ית', וכמ\"ש רק באבותיך חשק ה' גם קודם מ\"ת כו', שזהו הרצון בנש\"י עצמן מפני שמושרשים בעצמות כו'. וז\"ש לא מרובכם מכל העמים כו', פי' דלא משום העילוי שבנש\"י משו\"ז הרצון בהם כו', דמ\"ש לא מרובכם אין הכוונה על הריבוי בכמות, שהרי הריבוי בכמו' אינו טעם על אהבה, אלא הכוונה היא על הריבוי באיכות ובמעלה, והיינו דלא משום ריבוי העילוי שבנש\"י חשק ה' בהם, רק מצד עצמם שהן מושרשים בעצמות דמשו\"ז יש בהם רצון עצמי ממש כו'. דהנה יש ג\"כ רצון שהוא בתוקף גדול והוא כשהרצון הוא בענינים נעלים והו\"ע"],[3601330275,"השאגה שהו\"ע תוקף ההתפעלות שבא מתוקף הרצון בענין נעלה ביותר כו'. וכמו שאוג ישאג על נוהו וכמו שארז\"ל ג' משמורות הוי הלילה ועל כל משמר ומשמר הקב\"ה יושב ושואג כארי, אוי לי שהחרבתי את ביתי והגליתי את בניי בין האומות כו', שהיא השאגה על העדר גילוי האלקות כו', דבזמן ביהמ\"ק הי' גילוי אוא\"ס ממש למטה והגילוי הוא בנש\"י כו', וע\"ז היא השאגה על העדר הגילוי כו', מפני שלמע' יש רצון גדול כבי' שיהי' גילוי אלקות למטה, וכמא' נתאווה הקב\"ה להיות לו דירה בתחתונים כו', וע\"כ על העדר הגילוי וכ\"ש בגילוי נעלה כזה הוא השאגה כו'. והרצון הזה הוא הרצון בגילוים כו', וכמו\"כ הרצון בתומ\"צ הוא ג\"כ הרצון בגילוי אלקות כו', משא\"כ הרצון והאהבה דהקב\"ה בנש\"י בעצם אין זה מצד הגילוים כ\"א מצד העצם, ולכן כתיב ואף גם זאת בהיותם בארץ אויביהם לא מאסתים כו', אפי' בזמן הריחוק כו', דבין כך ובין כך בניי הם כו' ולהחליפם באומה אחרת א\"א כו', דאיך שהוא ח\"ו א\"א להחליפם כו', והיינו בחי' רצון עצמי ממש כו'. ובדוגמא כזאת הוא בנש\"י בהתגלות עצמות\nהנשמה ברצון עצמי לעצמות א\"ס ב\"ה בלי שום כוונה ובלי שום מבוקש כלל כו'. דהנה יש רצון שהוא בתוקף ההתפעלות והוא הרצון בגילוי אלקות, וכמו כאיל תערוג על אפיקי מים שהוא בחי' הצעקה על העדר הגילוי אלקות כו', וכמו צמאה לך נפשי כמה לך בשרי בארץ צי' ועיף בלי מים שלא יש גילוי אלקות כו', והוא הרצון בהגילוים כו', וכמו\"כ הרצון דמי לי בשמים כו' שאינו רוצה בהגילוים כו', הרי מ\"מ יש בזה מבוקש אם שהמבוקש הוא שרוצה בהמשכ' העצמית, או שרוצה להתכלל כו', הרי כ\"ז הוא איזה מבוקש כו'. אבל אמיתת רצון העצמי הוא מה שעצם הנשמה תתעורר בבחי' עצמות אלקות בלי שום מבוקש כלל ובלי שום חשבון לנפשו כו', שזהו רק מפני שהיא מושרשת בעצמות ע\"כ בהתגלות עצם הנשמה ה\"ה כשלהבת העולה מאליה שנמשכת (זיא ציהט זעך) לאלקות בבחי' רצון עצמי כו'. אמנם הכוונה כאן הוא בהרצון שיש בו כוונה פנימית והוא ג\"כ למע' מהטעם כו', והו\"ע הרצון בהתהוות העולמות דארז\"ל ע\"פ שוקיו עמודי שש שוקיו זה העולם שנשתוקק הקב\"ה לבראותו כו', והכוונה פנימית בזה הוא משום שנתאווה הקב\"ה להיות לו דירה בתחתונים כו', והרי גם ע\"ז אין טעם והשגה כלל רק מפני שכך הוא רצונו ית' כו').\n<span data-k=\"ks\"><b>קיצור.</b> עוד יובן ענין הנ\"ל כי יש ב' מיני רצון, הא' רצון גלוי בהטי' לאיזה דבר, ויש בזה כוונה פנימיות (ואגב יבאר ענין רצון עצמי מצד העצם כמו הרצון בנש\"י מצ\"ע, וכן רצון נש\"י באלקות בלי שום מבוקש, ויש רצון בגילוים מצד הגילוי עצמו וכמו הרצון בביהמק\"ד ובתומ\"צ, ורצון הנשמה בגילוי אלקות, והמבואר כאן הוא רצון שיש בו טעם פנימי) רק שהוא למעלה מהטעם, וזהו בחי' רצון ממש.</span>\nסה) <b>אך</b> יש עוד בחי' רצון לפני רצון זה (ונק' רצון הנעלם או כח הרצון), והוא שאינו נמשך נפשו עדיין לאותו הדבר בבחי' הטי' והמשכה ממש להשתוקק אליה, כ\"א שהוחלט והוסכם אצל עצמותו שראוי ונכון להיות רוצה בדבר ההוא שיבוא לידי מעשה, אבל אין כאן עדיין רצון והמשכה ממש שמשתוקק בזה רק הסכם בלבד שראוי לרצות כו'. והסכם והחלט זה הוא לאחר שנתעורר בהדבר, ואין זה ענין רצון המוחלט המבו' במ\"א שהוא בלי התעוררות כלל, והוא מה שיש בעצם"],[3601330276,"הנפש רצונות מוחלטי' מצד העצם שלא נתעורר בהם ויכול להיות שלא יתעורר בהם לעולם, והן מוחלטים בהעצם מצד העצם כו' וכמ\"ש במ\"א. אבל הרצון המוחלט המבו' כאן הוא שבא לאחר שכבר נתעורר בהדבר והי' אצלו שקלא וטריא אם ראוי לרצות א\"ל והוחלט אצלו שראוי לרצות כו', אך הוא בבחי' הסכם והחלט בלבד לא בבחי' רצון ממש כו', ויוכל לימשך כמה שנים עד שיתעורר ברצון ותשוקה ממש כו'. ומ\"מ במשך הזמן יבוא הרצון וגם הפועל מפני שכבר נתעורר בהדבר והוחלט אצלו שראוי לרצון ע\"כ יבוא הרצון כו', רק שיכול להיות נמשך משך זמן כו'. והסכם זה נק' מחשבה ולא רצון ממש, דרצון אותיות צנור וכמו הצנור שהוא המשכה כך הוא ענין הרצון שנמשך נפשו לאיזה דבר, והיינו שזהו בהתפעלו' שנתפעל בנפשו בהדבר ההוא כו', אבל ההסכם אינו רצון בהתפעלות עדיין כ\"א מח' והוא שהוסכם והוחלט במחשבתו להיות רוצה כו', והוא בעומק בנפש שמובדל בערך מהדבר להיות מתפעל מזה כו'. והיינו שהרצון הגלוי הוא במדרי' בנפש שבבחי' קירוב אל הפועל ובבחי' שייכות אליו וע\"כ הוא בבחי' התפעלות כו',\nאבל ההסכם והרצון הנעלם הוא במדרי' כזו שהוא בבחי' הבדלה עדיין כו'. וע\"ד שבמוחין ומדות שעפ\"י טו\"ד שכאשר רואה איזה דבר האהוב ומבין בשכלו שהדבר טוב לו ה\"ה מתפעל באהבה אל הדבר, והנה אנו רואין שלפעמים גם אם מבין שהדבר טוב לו ומ\"מ אינו מתפעל באהבה, והיינו מפני שהוא בבחי' ריחוק והבדלה מהדבר כו' (ושם הוא מצד העדר ההתקשרות כו' וכמ\"ש במ\"א, מ\"מ איך שיהי' ה\"ה בבחי' הבדלה ומשו\"ז אינו מתפעל בהדבר כו'). ועד\"ז הוא ברצון הנעלם שהוא במדרי' גבוה בנפש שהוא בבחי' הבדלה מהפועל, וע\"כ הגם שנתעורר בהדבר והוחלט אצלו אינו מתפעל בזה להיות לו רצון ממש רק שראוי לרצות כו'. ולכן הרצון זה נק' מח' ע\"ד מח' קרה שאינו בהתפעלות כו', וכמו\"כ הרצון הזה הוא רק הסכם והחלט במח' כו'. ונמצא ההפרש בין הסכם לרצון הוא, שהרצון הוא המשכת הנפש מהיותה עומדת בעצמותה שהיתה מופשטת משום דבר, להיות נמשכת למהות ודבר זולתה כשהוא רוצה בה כו', משא\"כ בההסכם שהנפש מסכמת שראוי לרצות בדבר פלוני עדיין אין מהותה נמשכת לאותו דבר כלל, רק שהוא בבחי' הסכמה\nבעצמותה להיות מקור ושרש לרצון אח\"כ במשך הזמן כו'. אמנם עכ\"ז ג\"ז הוא בחי' ירידה לגבי עצמות הנפש טרם שנעשה בה הסכם הזה, שהיתה בעצמותה ממש ומופשטת ומושללת משום דבר זולתה ולא הי' אפי' מקור להמשכה והטי' לאיזה דבר זולתה, משא\"כ בחי' ההסכם הוא הורדת המהות להיות מתחבר לזולתה, אלא שאינו כירידת המהות שע\"י הרצון שהוא הטי' והמשכה ממש לאותה הדבר, משא\"כ בההסכם שאינה נמשך עדיין לרצות רק שהוא בחי' הסכם בעצמותה שתימשך אח\"כ לרצות כו', והוא בבחי' ממוצע בין עצם הנפש לרצון הגלוי כו'. דהנה נת\"ל פמ\"ט דהרצון אינו כח בפ\"ע רק שהוא הטיית והמשכת הנפש כו', והרי הנפש עצמה מובדלת ומושללת לגמרי מכל דבר, ובכדי שיהי' רצון הגלוי בבחי' המשכה לאיזה דבר זהו ע\"י אמצעות ההסכם הנ\"ל שהוא בעצמותו עדיין רק בבחי' הורדת המהות לבד ה\"ז בבחי' ממוצע להיות הרצון הגלוי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וקודם לרצון הגלוי הוא ההסכם, שנתעורר בהדבר והוסכם שצריך לרצות, אבל לא יש עדיין הטי' בהתפעלות, רק שעי\"ז יבוא לידי רצון, ולכן נק'</span>"],[3601330277,"<b>רק</b> מחשבה, כי הוא בעצמותו עדיין מובדל מהדבר, לא כמו הרצון שהוא התגלות והמשכה להדבר שרוצה, ומ\"מ הוא ירידה מעצמותו ממש, וע\"כ הוא בבחי' ממוצע בין עצם הנפש ורצון הגלוי.\nסו) <b>והדוגמא</b> מזה יובן למע' דבחי' מחה\"ק דא\"ק, שהוא כדוגמת ההסכמה וההחלטה בדעת האדם לרצות באיזה דבר, שהוא בעצמותו עדיין ולא נעשה בו עדיין הטי' והמשכה כו', וכן בחי' מחה\"ק דא\"ק הוא שעלה לפניו ית' שיהי' התהוות כל הנמצאים דבי\"ע מרכ\"ד כו'. ונעשה ע\"ז בחי' ההסכם כבי' שיהי' כן ואינו בבחי' ההמשכה והטי' עדיין לאותן הצמצומים דאבי\"ע, אלא הוא עדיין בבחי' הסכם בעצמותו כו', והו\"ע הגילוי לעצמו לבד ולא בבחי' המשכה עדיין כו'. וה\"ז ג\"כ בבחי' ירידה והתגלו' לגבי העצמו' כמו שהוא קודם ההסכמה הנ\"ל שאינו בבחי' התגלות כלל, וההסכמה ה\"ה התגלות עכ\"פ רק שהוא בעצמותו עדיין ואינו בבחי' המשכה כו'. ומבחי' ההסכם דמחה\"ק דא\"ק נמשך הרצון שהוא בחי' כתר דאצי', וכידוע דממל' דא\"ק נעשה כתר לאצי' כו', והוא בחי' ההמשכה וההטי' להיות התהוות הע\"ס דאצי' וכללות העולם דאצי', שהתהוותם הוא ע\"י הרצון וכמשנת\"ל פנ\"ח שהרצון גורם פתיחת המקור להיות התגלות האורות, וכמו הלומד במקום שלבו חפץ כו', שע\"י הרצון שהוא הטיית והמשכת הנפש נמשך\nהגילוי כו' (והנה כאשר עושה איזה דבר ע\"י ההסכם בלבד וכמו כאשר הוסכם והוחלט אצלו ללמוד תורה, והוא לומד בכח ההסכם הזה שלא בא לכלל רצון עדיין ה\"ז בדרך קבלת עול, ויכול להיות שבזה לא יהי' עדיין גילוי האור להשכיל ולהתחכם כו', רק כאשר ההסכם הוא בתוקף כדבעי ה\"ה מקשר עצמו אל הענין ביתר שאת ועי\"ז בא התגלות הרצון וגם ההשכל' להשכיל ולהתחכם כו'. ולפ\"ז י\"ל שע\"י ההסכם נמשך בחי' הדעת הנעלם והוא ההתקשרות עצמי שמכריח את הרצון וגם את מקור השכל לבוא לידי גילוי כו', ועמ\"ש בד\"ה וככה הגדול פע\"ו ומ\"ש במ\"א בד\"ה וירד העיט כו'. אמנם הרצון הוא שרוצה בהתגלות ונמשכה נפשו לזה ועי\"ז יהיו ממילא הגילוים כו'). וזהו רצון אותיות צנור שהוא בחי' המשכה כו', והו\"ע נוצר חסד שהוא בחי' חסד שבכתר היינו חסד שברצון שרוצה שיהי' המשכת החסד כו', ולכן הוא מקור לבחי' ועושה חסד שהוא בחי' החסד שבס' השתל' כו', וכמ\"ש בתו\"א ד\"ה מראיהם ומעשיהם, ונוצר אותיו' צנור ואותיו' רצון והוא בחי' ההטי' וההמשכה כו'. וזהו\"ע בחי' הכתר שאחר בחי' ההסכמה וההחלטה\nשזהו הכל עדיין כמו שהוא בעצמותו עדיין שאינו בבחי' המשכה והתגלות כו', נמשך אח\"כ בחי' הכתר שהוא בחי' ההמשכה והתגלות להיות התהוות אצי' והתהוות בי\"ע כו' (ולפ\"ז י\"ל שזהו בחי' קדש וקדוש, דקדש הוא כמו שהוא לעצמו עדיין וקדוש בוא\"ו הוא המשכת הארה מקדש שהוא ג\"כ קדוש ומובדל, ומ\"מ הוא בבחי' גילוי לדבר הזולת כו', ובד\"כ הוא בחי' הגילוי לעצמו והגילוי לזולתו כו'. וזהו דא\"ק הוא בחי' אדם דברי' דכללות וכתר בחי' אדם דיצי' דכללות, שזהו עד\"מ בחי' מח' ודיבור כו', וכידוע דברי' ויצי' הן עד\"מ מח' ודבור, שההפרש ביניהם הוא דמח' היא הגילוי לעצמו ודבור הוא הגילוי אל הזולת שעי\"ז יהי' העשי' כו'. כמו\"כ בחי' מחה\"ק דא\"ק היא בבחי' גילוי לעצמו עדיין, ובחי' כתר דאצי' הוא בחי' דיבור שזהו הגילוי לצורך האצי' בחי' עשי' דכללות כו'. ובפרטיות העולמו' הנה אצי' הוא בחי' מח' כו' וכמ\"ש בע\"ח, אמנם"],[3601330278,"בכללות המדרי' בחי' מחה\"ק דא\"ק ובחי' כתר דאצי' הו\"ע מח' ודבור כו'). וזהו\"ע מה שצ\"ל בחי' רצון גם לאחר שכבר עלה הכל בבחי' מחה\"ק דא\"ק, לפי שכ\"ז הוא בבחי' מח' ורצון נעלם כו', וצ\"ל אח\"כ רצון גלוי כו'. ועוי\"ל דהנה א\"ק הוא בחי' א\"ס בערך האצי' וכמ\"ש בע\"ח שער סדר האצי' רפ\"א. והענין הוא דעם היותו בבחי' אדם ה\"ה בבחי' קדמון כו', והיינו שזהו בחי' המח' שעלה בא\"ס קדמון לכל הקדומים כו', דכשם שהוא קדמון כך מחשבתו קדומה כו' וכמ\"ש במ\"א, וע\"כ כל המדרי' שבו הכל הוא בבחי' א\"ס כו', ובכדי שיהי' ע\"ס דאצי' הוא ע\"י הכתר, וכנודע שהכתר הוא ממוצע בין הא\"ס אל האצי' והיינו מה שעלה ברצונו ית' להיות ע\"ס כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא למעלה הוא דמחה\"ק דא\"ק הוא בחי' ההסכם בעצמותו עדיין, ומזה נמשך רצון גלוי להיות התהוות האצי' (ובנפש ע\"י ההסכם יבוא לבחי' דעת הנעלם שמכריח התגלות הרצון והשכל) והו\"ע קדש וקדוש, גילוי לעצמו, וגילוי להזולת, והו\"ע כתר דאצי', ועוד דא\"ק הוא בחי' א\"ס עדיין ובכדי שיהי' אצי' הוא ע\"י אמצעית הכתר.</span>\nסז) <b>והנה</b> בחי' כתר דאצי' להיותו בחי' מקיף פרטי לעולם האצי', אינו נמשך מזה הביטול בכל הנבראים כמו מבחי' א\"ק דוכל קומה לפניך תשתחווה כנ\"ל פ\"ס. אך בנש\"י יש בכאו\"א בחי' ומדרי' זו, להיות דנשמות הרי מושרשים באצי' וכמ\"ש נשמה שנתת בי טהורה היא כו', דכל נשמה גם נשמות דבי\"ע שרשם הוא באצי', וכמ\"ש בסש\"ב דגם בבחי' נפש דעשי' יש בה מבחי' ע\"ס דאצי' כו', וישראל עלו במח' היינו במח' סתימאה דא\"א, וע\"כ גם מבחי' המקיף דכתר יש בכאו\"א מישראל, והו\"ע האהבה מוסתרת ובחי' רעו\"ד שלמע' מטו\"ד שיש בכאו\"א מישראל כו'. וז\"ש ששם עלו שבטים כו' עדות לישראל, ולכאו' מה\"ע העדות. אך הענין דעדות הוא על דבר הנסתר ונעלם כי על דבר הנגלה ונראה לכל א\"צ עדות ולאו דוקא על דבר הנגלה ממש כ\"א אפי' מילתא דעבידא לגלויי מיד א\"צ עדות גמור כידוע בגמ', דלכך האמינו בעדות אשה עד אחד ועד מפי עד כו', רק על דבר הסתום ונעלם צריכים עדות כו'. והדוגמא מזה למע' הוא בחי' אוא\"ס סתימא דכל סתימין בחי' סוכ\"ע שלמע' מבחי' גילוי ע\"ז שייך עדות כו',\nוהיינו שע\"י העדות נמשך גילוי בחי' ומדרי' זו כו'. וזהו שהמצות נק' עדות וכמ\"ש בדרך עדותיך ששתי, והיינו שע\"י המצות שהן בחי' רצה\"ע מאיר גילוי בחי' אוא\"ס סדכ\"ס כו'. וכן הוא עד\"ז מ\"ש ששם עלו שבטים כו' עדות לישראל, כי הי\"ב שבטים הן מבחי' ו\"ק דאצי', כמ\"ש ששה משמותם כו' ואת שמות הששה הנותרים כו', והיינו ענין י\"ב גבולי אלכסון כנודע. והנה המדות נמשכים מן השכל אך יש ג\"כ שרש המדות בלמע' מהשכל, וזהו בחי' טורי חשוכא הנז' בזהר שעז\"נ בעבר הנהר ישבו אבותיכם כו' וכמ\"ש במ\"א. וזהו ששם עלו שבטים שהו\"ע ישראל עלו במח' כו', ומבחי' זו נמשך ג\"כ בנפש והוא בחי' המס\"נ ורעו\"ד שלמע' מהשכל כו', ועז\"נ עדות לישראל שזהו עדות ורמיזא לבחי' הנסתר בחי' אוא\"ס סדכ\"ס כו'. וזהו מה שהקב\"ה נותן בו נשמה דהיינו בחי' רעו\"ד, להיות שזהו עיקר בחי' אלקות שבנשמה דהיינו מה שהקב\"ה נותן כו'. דהנה בנשמה יש ד' מדרי' רצון שלמע' מהשכל ושכל"],[3601330279,"ומח' ודבור שנחשבים למדרי' א' להיותם בחי' חומר וצורה כו' ומעשה כו' והן בחי' נר\"ן ונשמה לנשמה כו'. דנר\"ן שרשם מע\"ס דאצי' והוא מחלק או\"א דהיינו בחי' חו\"ב כו', ומה שהקב\"ה נותן בו נשמה היינו בחי' נשמה לנשמה שזהו נשמה דנר\"ן כו', שעז\"נ ומספר את רובע ישראל דפי' רובע הוא ארבעה, והן הד' מדרי' הנ\"ל שבנשמה. וגם רובע הוא ל' רביעית דהיינו מדרי' הרביעית בחי' הרצון שזהו עיקר בחי' ישראל כו', כי שכל ומחדו\"מ ישנם גם בעכו\"ם שנמשכים מע\"ס דקלי' כו', ונש\"י לבד שיש בהם מדרי' הנ\"ל והן מע\"ס דקדושה, הנה העיקר הוא מה שבנש\"י יש בחי' הרצון פשוט בחי' נשמה לנשמה שזהו עיקר מדרי' ישראל כו'. דישראל הוא מל' כי שרית כו' וגם ישראל הוא שר אל ל' מושל ושליט, כמו עד\"מ הרצון שליט על כל האיברים כי ברצונו יכול ליתן איבריו לאש או למים קרים היפך טבעם והם בטלים להרצון כו'. וכן הרצון שבנה\"א גדול ורב כחו להיות מושל ושולט על כל כחות הנפש, וכמ\"ש כי קרוב אליך הדבר מאד בפיך ובלבבך לעשותו, שזהו ע\"י האהבה מוסתרת שיש בכאו\"א עי\"ז קרוב מאד\nלהיות גם בפיך ובלבבך בעסק התורה ומחדו\"מ דאלקות כו' וכמ\"ש בסש\"ב פי\"ז. וגם ההתגלות דמדרי' זו הוא בנקל יותר מהתגלות הכחות פנימיים, דעם היות שזהו מדרי' גבוה, מ\"מ בנקל יותר להגיע לבחי' רעו\"ד מלהגיע להאהבה הנמשכת מהשכל וההתבוננות כו'. וכשיש התגלות בחי' רעו\"ד אז ממילא הוא השליטה על כל הכחות, היינו שיהי' התגלות הכחות פנימיים כו'. ועיקר גילוי רצון הנ\"ל ופעולתו (היינו כאשר הוא בהעלם וי\"ל דכמו\"כ אחר שיש התגלות בחי' רעו\"ד הנה פעולתו הניכרת בפועל) הוא בביטול רצונות זרות מעניני עוה\"ז להיות עוזב תאוותיו ולבטל רצונו מפני רצון ה', וכן במחדו\"מ וראי' ושמיעה להיות עוצם עיניו מראות ברע ואוטם אזנו משמוע וכן במח' כו', והן בועשה טוב להיות בטול רצונו מכל וכל רק לה' לבדו כו', וכ\"ז לא ע\"י התבוננות והתעוררות אהוי\"ר כ\"א מפני ביטול הרצון כו' שז\"ע ישראל שר אל כו'. וזהו עדות לישראל דכח שליטה וממשלה זו הוא בנש\"י דוקא, והוא עדות על בחי' אוא\"ס סדכ\"ס, שיש בנשמות בחי' זו שעי\"ז יש בהם כח השליטה והממשלה הנ\"ל, וגם שעי\"ז נמשך\nגילוי רצה\"ע, ובפרט שע\"י התגלות בחי' רעו\"ד שממשיכים גילוי בחי' רצה\"ע, היינו בחי' אוא\"ס הסתום ונעלם, וכנודע דלית מח' תב\"כ אבל נתפס איהו ברעו\"ד כו'. וזהו פעולת המקיף הפרטי דבחי' כתר דאצי' שפועל בנש\"י להיות בהם בחי' רעו\"ד הנ\"ל (ועם היות שזהו מה שהקב\"ה נותן בו נשמה והיא נשמה דנר\"ן כנ\"ל, הרי מדרי' זו היא בחי' מקיף דנשמה (היינו מדרי' בנשמה שהיא בבחי' מקיף כו'), וכן ההתגלות היא בבחי' מקיף שזהו\"ע רעו\"ד שזהו בחי' הרצון שלמע' מטו\"ד כו', והיא בבחי' נשמה לנר\"ן שנותן חיות בהפנימי וגם שעי\"ז יהי' התגלות הכחות פנימיים כו', ולעיל פנ\"א נת' דמה שהרצון פועל התגלות הכחו' הוא בדרך הכרח שבאופן כזה הוא פעולת המקיף כו'). ועוד זאת דבחי' המקיף עליון דכתר דאצי' פועל ג\"כ בבחי' פנימי בבחי' מקיף קרוב והיינו שנרגש בהפנימי כו', וכמו הרהורי תשובה שנופלים לאדם פתאום, שזהו מבחי' מקיף דחי' שנק' מזל ע\"ש שנוזל ונוטף לנשמה המלובשת בגוף, שעז\"א אע\"ג דאינהו לא חזי מזלייהו חזי, והיינו שרש ומקור הנשמה שרואה ושומעת הכרוזים עליונים\nשמעוררי' על התשובה ומטפת הארתה לנשמה המלובשת בגוף, שמזה נופלים לו הרהורי תשובה להיותו בבחי' מקיף קרוב כו'. ולמע' היינו ההמשכה מבחי' כ\"ע שבבחי' מקיף פרטי בבחי'"],[3601330280,"קירוב כו'. וזהו ג\"כ ענין מארז\"ל אכל בי' עשרה שכינתא שריא שהוא בחי' מקיף הנ\"ל, וכמו שיש מי שמתפעל כשמתפלל בעשרה שאז התפלה אצלו בהתעוררות פנימי יותר כו', או כשרואה שחבירו מתפלל בכוונה מתפעל גם הוא להתפלל יותר מרגילותו כו', שכ\"ז הוא מבחי' מקיף הקרוב כו', וכמ\"ש בתו\"א בהבי' דהבאים ישרש יעקב.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש אתם נצבים היום כו', דהנה נצבים זהו בחי' תוקף העמידה והיא בחי' מקיף דנשמה שזהו בבחי' תוקף שאינו משתנה כמו הכחות הגילוים דשכל ומדות שיש בהם שינוים, משא\"כ הרצון שלמע' מטו\"ד אין בזה שינוים כו'. וכמו גבי למע' כתיב כי לא אדם הוא להנחם, דבציור אדם שייך ניחומים היינו שינוים כו', אבל מדרי' לא אדם לא ינחם כו'. וכמו\"כ בנפש דבחי' הרצון שלמע' מטו\"ד הוא בתוקף ובלי שינוי כו', גם שההתגלות היא בתוקף ולא כמו מדות שע\"פ טו\"ד שהן בהגבלה ובבחי' חלישות, משא\"כ הרצון שלמעלה מטו\"ד הוא בתוקף ההתגלות ובלי הגבלה כו'. וזה\"ע נצבים בבחי' התגלות עצמית הנשמה היינו בחי' הרצון שהוא בתוקף כו', גם נצבים הוא ל' נציב שהוא ל' שר וכמו בימים ההם אין מלך באדום רק נציב מלך כו'. דהנה נת\"ל דבחי' הרצון שלמע' מטו\"ד זהו מדרי' ישראל דישראל הוא ל' שר שמושל ושולט על כל הכחות כו', וזהו ג\"כ ענין נצבים היינו בחי' נציב ושר שזהו מדרי' ישראל כו'. ומש\"כ אתם נצבים היום דקאי על ר\"ה דהנה בר\"ה אז הוא התגלות עצמות\nהנשמה, ועיקר העבודה דר\"ה הוא בבחי' עצמות הנשמה דוקא, דכל השנה עיקר העבודה היא בכחות הגלוים שהיא העבודה דמוח ולב בהשגה והתבוננות באלקות ובהתעוררות אהוי\"ר שע\"פ טו\"ד כו', אבל בר\"ה עיקר העבודה היא בהתגלות עצמות הנשמה כו'. וזהו נצבים היום לפני ה' אלקיכם למע' מבחי' הפנימי והיינו שמעוררים וממשיכים עי\"ז גילוי בחי' עצמות אוא\"ס ב\"ה וכמא' אבל נתפס איהו ברעו\"ד כו' כנ\"ל. ועוד זאת מש\"כ אתם נצבים היום דת\"א אתון קיימין יומא דין כו', דהנה כתי' ויהי היום ויבאו בני אלקים כו', וקאי על היום דר\"ה דבני אלקים באין ומקטרגין ח\"ו, שזהו להתייצב על ה' היינו לנגד ש' הוי' כו'. ועז\"א דהגם דבני אלקים באים ומקטרגין ר\"ל, מ\"מ אתם נצבים היום עומדים וקיימין וזוכים בדין כו', והיינו ע\"י בחי' הרצון פשוט שיש בנש\"י עי\"ז הן עומדין וקיימין כו', ואדרבה נמשך בהם תוס' אורות כו'. וז\"ע תקיעת שופר דר\"ה וכידוע דענינו הוא התגלות עצם הנשמה שזהו בחי' הצעקה בקול פשוט מעומקא דלבא כו', ועי\"ז הן קיימין ועומדין בבחי' תוס' אורות וגילוים על כל\nהשנה כו'. אמנם מ\"ש נצבים ל' נפעל היינו שהתגלות עצמו' הנשמה הנה נש\"י נפעלים בזה מלמע' וכמשנת\"ל ומבו' בכ\"מ דהתגלות עצם הנשמה אין בזה בהאדם בכח עצמו רק שנותנים לו מלמע' כו'. אמנם בכדי שיהי' בר\"ה התגלות עצמות הנשמה זהו ע\"י העבודה דכל השנה בכחות הגלוים כו', וע\"ז הוא ההקדמה דחדש אלול בבחי' תשו\"ת ובפרט בימי הסליחות להיות ממארי דחושבנא בפרטי הענינים שלו ובפרטי העבודה דכל השנה, ואם הי' שלא כדבעי יתמרמר בנפשו ע\"ז ובבחי' קבלה על להבא כו', ועי\"ז יהי' בר\"ה התגלות בחי' עצמות הנשמה כו'. וזהו מה שחשיב אח\"כ ראשיכם שבטיכם כו', היינו לפי שבכדי להיות נצבים היום זהו ע\"י העבודה דכל השנה בכחות הגלוים שזהו פרטי המדרי' שבנשמות כו'. גם להיות"],[3601330281,"שבהתגלו' עצמות הנשמה הרי עי\"ז יהי' התגלות הכחות כמשנת\"ל. וכן הוא למע' דבר\"ה שנמשך בחי' עצמות אוא\"ס הרי אז הוא ג\"כ ההמשכה כללית על כל העבודה דכל השנה וכמו תקעו בחדש שופר כו', כי חוק לישראל הוא משפט לאלקי יעקב היינו בחי' אלקות שבנשמו' שגם ע\"ז הוא הדין ומשפט בר\"ה כו', ובההמשכות דר\"ה נמשך על כללות העבודה דכל השנה כו'. וזהו אתם נצבים היום בבחי' התגלות דעצם הנשמה כו', ועי\"ז אתם קיימין ועומדים גם בבחי' תוס' אורות כו', ועי\"ז הוא ההמשכה על כל השנה, בהעבודה בכחות הפנימיים כו'. וז\"ע ראשיכם שבטיכם וזקניכם כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ופעולת בחי' כתר דאצי' הוא רק בנש\"י, והיא האהמ\"ס ורעו\"ד, והו\"ע עדות לישראל (כי שרשם בבחי' סדכ\"ס) והו\"ע הקב\"ה נותן בו נשמה, כי זהו האלקות שבנשמה, והו\"ע ישראל שר אל השליטה להיות ביטול הרצונות זרות, ולהיות התגלות הכחות פנימיים, ונותן חיות בהפנימי, גם מזה הם הרהורי תשובה הבאים פתאום, ואכל בי עשרה שכינתא שריא.</span>"],[3601330282,"<h3>בס\"ד. ליל ב' דר\"ה, תער\"ג</h3>\n<b>זה</b> היום תחלת מעשיך זכרון ליום ראשון, זה היום קאי על היום דר\"ה שנק' תחלת מעשיך. ולכאו' אינו מובן, והלא ר\"ה הוא יום וא\"ו למע\"ב דבכ\"ה באלול נבה\"ע ור\"ה הוא יום וא\"ו, וכן מובן ממש\"א זכרון ליום ראשון דר\"ה אינו יום ראשון שהוא יום ו' שבו נברא אדה\"ר, וא\"כ מפני מה נק' תחלת מעשיך. וגם צ\"ל מה\"ע שהיום דר\"ה הוא זכרון ליום ראשון כו'.\nסח) <b>והנה</b> היוצא מכל משנת\"ל הוא דבכללות השתל' יש ב' מדרי' אור פנימי ואור מקיף, דבשרש הראשון באוא\"ס שלפה\"צ שרש האו\"פ הן הע\"ס הגנוזות באוא\"ס ב\"ה, דענינם הוא להאיר את העולמות שזהו מה ששיער אוא\"ס בעצמו להאיר במדה וגבול כו'. וכמו שהן באוא\"ס שלפה\"צ הן בבחי' פשיטות לגמרי לפי שאינן בבחי' מציאות ניכרת כלל ה\"ה בבחי' פשיטות ובבחי' התאחדות והתערבות כו', וע\"י הצמצום נמשכו להיות ספירות פרטיות להיות ספי' החכ' בפ\"ע ובינה בפ\"ע כו'. וז\"ע שהקו שהוא האור שנמשך אחר הצמצום ה\"ה קו העשוי מנקודות היינו הספי' פרטיות כו', ומ\"מ גם כמו שהן בהקו ה\"ה בבחי' בלי מה ובבחי' פשיטות כו', רק כאשר מתלבשים בהכלים דע\"ס דאצי' ה\"ה נעשים בבחי' מציאות דבר מה כו', שהרי הכלים הם בבחי' מהות ומציאות דבר, נעשים עי\"ז האורות ג\"כ בבחי' מציאות דבר, וה\"ה בבחי' התחלקות מעלה ומטה במעלתן דהיינו בבחי' ריבוי ומיעוט האור והגילוי כו', וגם בעצם מדריגתן שהחכ' היא בבחי' מעלה"],[3601330283,"בעצם מדריגתה לגבי בינה וכן המוחין לגבי המדות כו'. להיות דבשרשן הן להאיר בבחי' מדה וגבול, ומ\"מ הן בבחי' פשיטות לגמרי, הנה באמצען דהיינו בחי' הקו למעלה מאצי' מתגלה בחי' הפשיטות שבהם, ובסופם דהיינו בהתלבשותן בכלים דאצי' באים בבחי' מציאות דבר ובבחי' הגבלה והתחלקות כו', והיינו שמתגלה בחי' הגבלה שלהם כו'. וכמו\"כ יש בזה התחלקות בעולמות שהע\"ס דאצי' אינן כמו הע\"ס שלמעלה מאצי', וכן הע\"ס דבריאה לגבי אצי' כו'. אמנם האו\"מ בשרשו הוא בחי' האוא\"ס שהוא בבחי' גילוי מן העצם שאין ענינו להאיר את העולמו' כ\"א בבחי' גילוי מן העצם שהגילוי הוא מעין העצם, וע\"כ נק' א\"ס שהוא בבחי' פשיטות ממש ובבחי' בלי גבול כו'. וע\"כ על עצם האור מצד הפשיטות שלו אינו שייך בו שם כלל, רק בבחי' התפשטו' האור שייך שם רצון להיות שענין הרצון הוא רק גילוי העצם כו', וכאשר הוא בבחי' רצון ה\"ה בבחי' מקיף עכ\"פ לעולמו' כו' אבל אין בו התחלקות, וכמו שהרצון פועל בכל הכחות והאיברים בשוה ברגל כמו בראש, כמו\"כ במקיף הוא בכל העולמות בשוה כו'. ונת' דמ\"מ\nלהיותו בבחי' מקיף הרי יש לו שייכות אל הפנימי ע\"כ יש בזה מקיפים כללים ומקיפים פרטים כו', דמקיפים הכללים הן בחי' טה\"ע וטה\"ת, דטה\"ע זהו בחי' העיגול הגדול שלפני הקו שסובב כללות ההשתל' דקו כו', וטה\"ת זהו בחי' מחה\"ק שסובב ומקיף ג\"כ כללות ההשתל' אחר הצמצו' כו'. ומקיפים פרטים הן הכתרים שבכל העולמות כתר דאצי' שהוא הרצון להאציל האצי' וכתר דברי' הרצון לברוא כו'. ומה שצריכים מקיפים פרטים הוא לפי שבהמקיף הכללי הרי הכל שם בהשוואה עשי' כמו אצי', די\"ל ששווים שם גם בבחי' האור והגילוי ובד\"כ הם לא בבחי' מציאות ניכרת להיות בהם התחלקות כו', וע\"כ צריכים רצון פרטי לכל עולם בפרט כו'. וגם שהרצון כללי הוא רצון נעלם עדיין בבחי' הסכם והחלט לבד כו', והכתרים הן בחי' רצון גלוי כו', וז\"ע כתר דאצי' שהוא בחי' רצון גלוי להאציל אצי' כו'. וגם דא\"ק הוא בבחי' א\"ס עדיין, וע\"כ בכדי שיהי' התהוות ע\"ס צ\"ל רצון פרטי כו', והמקיפים פועלים בעולם, דבחי' העה\"ג שלפני הקו הוא שנותן כח הביטול בהכלים. ולעתיד שיהי' גילוי בחי' העה\"ג, יהי'\nהגוף הגשמי אלקות, ובזה דבכל קומה דא\"ק לפניך תשתחווה הנה כל הנבראים הכלולים בא\"ק בטלים לאוא\"ס ב\"ה, ומבחי' פנימיות א\"ק נמשך הארה בנש\"י והוא הכח דמס\"נ על קדה\"ש שבכאו\"א, וגם מה שנק' בשם כלה בחי' כלות הנפש, וגם הביטול דהקדימו נעשה לנשמע, ומבחי' כתר דאצי' הוא בחי' האהמ\"ס ורעו\"ד, ובחי' הרהורי תשובה שנופלים פתאום, וגם משארז\"ל אכל בי עשרה שכינתא שרי' כו',\n<span data-k=\"ks\"><b>קיצור.</b> תוכן הענין דיש שרשי האורות דאו\"פ באוא\"ס שלפני הצמצום, והוא מה שאוא\"ס שיער בעצמו להאיר במדה וגבול, והן הע\"ס הגנוזות, ושם הן בבחי' אחדות ממש, וע\"י צמצום נמשכו ספי' פרטיות בהקו בבחי' נקודות שהן ג\"כ בבחי' פשיטות, ובהכלים הם בבחי' מציאות, ויש בהם מעומ\"ט במעלתן ומדריגתן, והאו\"מ בשרשו הוא בחי' גילוי העצם בבחי' א\"ס ממש, ומ\"מ יש מקיפים כללים ופרטים, מקיפים הכללים הוא בחי' טה\"ע שלפני הצמצום וטה\"ת בחי' מחה\"ק שאחר הצמצום, ומקיפים פרטים הן בחי' הכתר של כל עולם, וכל המקיפים פועלים למטה.</span>"],[3601330284,"סט) <b>והנה</b> כשם דכתר דאצי' הוא רצון פרטי ורצון גלוי לעולם אצי' כמו\"כ כתר דברי' הוא רצון פרטי וגלוי להתהוות עולם הברי' כו', דתחלה הי' הכל כלול במחה\"ק דא\"ק שעלו שם כל העולמות וההשתל' והכל הי' בהשוואה כו', ואח\"כ נמשכו רצונות פרטיות לכל עולם בפרט והו\"ע כתר דברי' וכתר דיצי' עד כתר דעשי' שזהו רצון פרטי לעולם העשי' כו'. וזהו שאנו אומרים בברכת יוצר אלקי עולם ברחמיך הרבים רחם עלינו אדון עוזינו צור משגבינו מגן ישעינו משגב בעדינו, דאדון עוזינו הוא בחי' המקיף דמל' דאצי' כמו שהוא באצי' ואח\"כ צור משגבינו מגן ישענו כו' הן ג' מקיפים דג' עולמות בי\"ע כו'. וביאור הענין הוא, דהנה אי' בזהר בהתחלתו בריש הורמנותא דמלכא גליף גליפו בטה\"ע כו', ופי' בריש הורמנותא דמלכא הוא בתחלת רשות ורצון המלך כו', דהנה עצמות אוא\"ס הרי אינו בבחי' רצון עדיין, כי בחי' הרצון הגם שהוא בבחי' גילוי העצם והוא בבחי' א\"ס (שלמע' מהע\"ס שהן להאיר בבחי' מדה וגבול כו'), מ\"מ ה\"ז ענין פרטי דהיינו רצון כו'. והגם שאין זה כח פרטי, היינו\nשאינו מהות כח בפ\"ע, שהרי כל ענין הרצון הוא רק הטיית והמשכת העצמיות כו'. וכמשנת\"ל פמ\"ט ההפרש בין הרצון לכל הכחות, דכל הכחות הן מהות כחו' בפ\"ע שאינן העצמיות דהנפש, וכמו כח השכל שהוא מהות כח בפ\"ע שאינו הנפש עצמו וכן כח החסד וכה\"ג, ועם היות שהנפש הוא המשכיל היינו שהוא משכיל ע\"י כח השכל שבו שאין זה עצמיות שלו כו', אבל הרצון אינו מהות כח בפ\"ע כ\"א הוא הטיית והמשכת העצמיות דנפש לבד כו'. וכמו\"כ הוא הדוגמא למע' דענין הרצון הוא רק המשכת העצמות כו', מ\"מ הרי העצמות למע' מזה ואינו בגדר רצון בעצם. וכמשנת\"ל פנ\"ו דעצם האור הוא בבחי' א\"ס ממש שאינו שייך בו שם רצון, והרצון הוא רק בבחי' התפשטות האור כו', ובפרט בחי' התגלות הרצון שהוא המשכת הרצון באיזה דבר אין זה שייך בעצמות כו'. ובאמת באוא\"ס בכלל אינו שייך ענין דבר כלל ולא ענין המשכה באיזה דבר, דלפני הצמצום הרי הכל הוא בבחי' התכללות בעצמותו לא בבחי' המשכה כו' (וכמ\"ש במ\"א בענין אתה הוא הוי' לבדך כו'), וא\"כ מה שאנו אומרים המשכת העצמות והתגלות הרצון הרי אין זה\nהמשכה והתגלות ממש (כי הכל הוא בעצמותו גופא) ולא לאיזה דבר מה כו'. מ\"מ גם מה ששייך לומר בהאור א\"ס אינו שייך בעצמות כו' (היינו גם בעצמות האור כו'). וז\"ע בריש הורמנותא דמלכא דהיינו שמבחי' העלם עצמותו ית' שלמע' מגדר רצון בא לידי רצון כו', והוא ענין א' עם מ\"ש בע\"ח דטרם שנאצלו הנאצלים הי' אור עליון פשוט כו', דהכוונה במ\"ש טרם שנאצלו הנאצלים הוא טרם שעלה ברצונו ית' להאציל כו', והוא בחי' עצמות אוא\"ס שלמעלה מבחי' רצון כו', וכשעלה ברצונו הפשוט להאציל זהו בחי' הורמנותא דמלכא שבזהר. וזהו דבהתחלת פסוד\"ז, דכללות ענין פסוד\"ז מדבר בענין בריאת והתהוות העולמות, הנה בהתחלת פסוד\"ז אומרים ברוך שאמר והי' העולם, ונודע דאמירה היא בלב היינו במח' ורצון כו', ומה הי' אמירה זו הוא שיהי' ענין נבדל מעצמותו והוא שיהי' העולם כו'. ומ\"ש והי' העולם הוא ל' עתיד שבודאי עתיד להיות כי ההוא אמר בעצמו ולא יעשה לבוא לגילוי גמור כו' (וי\"ל מ\"ש והי' ע\"פ מ\"ש במ\"א דוהי' אותיו' הוי' רק שאותיו' ו\"ה קודמים לאותיות י\"ה, דאותיות ו\"ה הי'\nמורה אצלם על השמחה, וכמ\"ש במד\"ר איכה ע\"פ היו צריה לראש לא אמרית וי אלא וה אמרי, והיינו שזהו השמחה שיתגלה לעתיד"],[3601330285,"מה שישמח ה' במעשיו ע\"י הבירורים שנתבררו בעשי' דוקא כמ\"ש בלק\"ת בד\"ה ה' לי בעוזרי. וזהו ג\"כ ענין והי' העולם להיות דפנימי' הכוונה בהרצון שבהתהוות העולמות הוא שיהי' עבודת הבירורים למטה, שעי\"ז נשלמה הכוונה דנתאווה הקב\"ה להיות לו דירה בתחתונים כו', וע\"כ אומר והי' העולם דהיינו השמחה העליונה כבי' שיהי' ע\"י התהוות העולמות שזהו פנימיות הרצון כו'. וזהו והי' ו\"ה קודם שהיא ל' שמחה. גם נודע מ\"ש במד\"ר ריש מג\"א דוהי' מורה על השמחה שזהו שמחה הנ\"ל, וה\"ז ע\"ד מה שאמרו במי נמלך בנשמותיהן של צדיקים דהיינו מה שעלה לפניו ית' שיהיו צדיקים שיקיימו תומ\"צ למטה שעי\"ז הוחלט הרצון דברה\"ע כו', כמו\"כ הו\"ע והי' שבהרצון להתהוות יש בו פנימי' הרצון שזהו השמחה כבי' בעבודת הבירורים כו'. גם י\"ל דידוע דזו\"נ יש להם שרש גבוה יותר מחו\"ב דז\"א בעתיקא אחיד ותליא כו', וגם בחי' המל' שרשה ברדל\"א למע' מהט\"ס כמ\"ש בע\"ח, וזהו והי' ו\"ה קודמים לי\"ה כו'. ובד\"כ זהו ג\"כ מה ששייך לבירורים, וכנודע דהבירורי' למטה (דהיינו בדרך מלמטלמ\"ע כו') הן\nהבירורים דבחי' מל' בכח הארת ש' מ\"ה דז\"א כו' וכמ\"ש במ\"א, וזהו דבשרשם הקדום ו\"ה קדום כו'). או והי' שמיד נתהווה כי מיד שעלה ברצונו הפשוט גליף גליפו כו' (ומ\"מ האמירה שאמר והי' העולם ה\"ז למע' עדיין מבחי' גליפו הנ\"ל וכמשי\"ת). וענין רשות ורצון הוא שהרצון אינו הכרחי ח\"ו. דהנה מה שעלה ברצונו ית' שיהי' ענין נבדל מעצמותו הוא מצד היכולת שבעצמו' כו', וכידוע דהתהוות היש הוא ביכולת העצמות דוקא וכמ\"ש באגה\"ק ד\"ה איהו וחיוהי חד דא\"ס עצמותו ומהותו שמציאותו מעצמותו ואינו עלול מאיזה עילה שקדמה לו ח\"ו, הוא לבדו בכחו ויכולתו להוות יש מאין ואפס המוחלט ממש בלי שום עילה וסיבה אחרת קודמת ליש הזה כו', ובחי' היכולת שבעצמות להוות יש מאין זהו סיבה להיות עלה ברצונו כו' (ואין זה היכולת שבעצמות היא בבחי' סיבה ח\"ו אל הרצון כו', ור\"ל שהיכולת והרצון אינו בבחי' סיבה ומסובב כו', אך מבחי' היכולת בא בחי' הרצון כו'). ומאחר שהיכולת הוא סיבת הרצון ממילא אין הרצון הכרחי ח\"ו, שהרי זהו ענין היכולת שאינו מוכרח, דדבר הכרחי אין זה\nיכולת וכל ענין היכולת הוא שאינו מוכרח בהדבר כו'. וז\"ע רשות ורצון שהרצון הוא בבחי' רשות כו', וכמ\"ש בשל\"ה שער האותיות אות רצון שעלה ברצונו ב\"ה לברוא את העולם ברצונו הטוב בנדבה בלי הכרח כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו\"כ יש כתר דברי' ויצי' ועשי', והו\"ע צור מגן ומשגב ג' מקיפים, ויקדים מ\"ש בזהר בריש הורמנותא דמלכא, והוא דמבחי' העלם העצמות שאינו בגדר רצון בא לכלל רצון בעצמותו, וזהו שאמר והי' העולם אמירה ברצון שיהי' עולם שהו\"ע עליית הרצון להאציל ולברוא, ופי' והי' השמחה מענין הבירורים שעלה בעצמותו, במי נמלך, גם הוא שרש ו\"ה שלמעלה מי\"ה, וענין רשות ורצון היינו שהרצון בבחי' רשות כי הוא בא מבחי' היכולת שבעצמותו להוות.</span>\n<b>עי\"ן)</b> והנה הרצון הזה הוא רצון כללי שאין בו עדיין ענינים פרטיים כלל, וז\"ש ברוך שאמר שהוא בחי' אמירה אחת לבד כו', והגם שבהכרח לומר שהרצון (גם קודם ההשערה) כולל בעצמו כל מה שיתהווה כו', הנה זהו בהעלם לגמרי בהרצון הכללי ואינם ניכרים הפרטים כלל גם לא לעצמו כו' (דבד\"כ בחי'"],[3601330286,"האוא\"ס שלפני הצמצום הוא בבחי' גילוי לעצמו לבד כו', וכשמדברים בפרטי המדרי' שבאוא\"ס הנה בחי' רצון הנ\"ל הוא בעצמותו גופא בחי' האור השייך אל הזולת כו' וכמ\"ש במ\"א ועמשנת\"ל פט\"ז, אך בד\"כ מה שלפני הצמצום הכל הוא לעצמו עדיין כו', וע\"כ בבחי' הרצון הפשוט שאינם ניכרים הפרטים עדיין היינו שאינם ניכרים עדיין גם לעצמו כו'). וזהו ענין ברוך הוא שהוא המשכת ההעלם אל הגילוי והיינו שזה שיש בהעלם בהרצון יבוא לידי גילוי לעצמו כו', והו\"ע ההשערה בכח כל מה שעתיד להיות כו'. ועז\"א בריש הורמנותא דמלכא גליף גליפו דהחקיקה הו\"ע ההשערה כו', וכ\"ז באוא\"ס שלפה\"צ ואינו שייך עדיין שיהי' התהוות העולמות, דגם בחי' ההשערה בכח הכל הוא באוא\"ס שאינו בערך ההתהוות עדיין כו' (דגם בבחי' האורות דנת\"ל פט\"ז ופכ\"ז דשרשי האורות שזהו ההשערה להאיר בבחי' מדה וגבול ושזהו שרש בחי' ממכ\"ע, מ\"מ ה\"ז בבחי' סובב לגבי הקו כו' וכמ\"ש במ\"א, והיינו שזהו בבחי' הבדלה בערך מבחי' הקו כו', וכ\"ש דבבחי' הכלים הרי בחי' ההשערה שבאוא\"ס שלפני הצמצום היא בבחי' הבדלה\nבערך כו', שהרי בכלים ריחוק הערך דהכלים לגבי שרשם ומקורם הוא יותר מבאורות, דבאורות הרי גם האור כמו שהוא בגילוי בבחי' מציאות אור הרי אינו בבחי' מציאות ממש, דכללות האור ה\"ה בבחי' אין כו' וכמשנת\"ל פי\"ד דמה שהאור נעשה בבחי' מציאות ה\"ז מ\"מ ע\"י הכלי כו'. וא\"כ ריחוק הערך דהאור לגבי שרשו ומקורו אינו גדול כ\"כ כמו בכלים שהן בבחי' מהות ומציאות דבר, ושרשי הכלים שהן אותיות הרשימו שז\"ע גליף גליפו כו', הרי אינו בבחי' מציאות דבר כלל וכלל כו', וע\"כ נת\"ל פ\"י די\"ל דהכלים לגבי שרשם ומקורם שלפני הצמצום הן באין ערוך לגמרי כו'. וא\"כ מובן דבחי' ההשערה בכח אינו בערך ההתהוות כו'. אמנם כאן מדברים בהאוא\"ס הבל\"ג והיינו אור הא\"ס המשער כו', דידוע דקודם הצמצום הי' האוא\"ס מאיר בגילוי ממש באותיות הרשימו כו', והאור הא\"ס לא מיבעי כמו שהוא בבחי' הרצון הפשוט (טרם ההשערה כבי') שאינו בערך ההתהוות, אלא גם כמו שהוא בבחי' ההשערה אינו בערך ההתהוות כו'). ובכדי שתהי' ההתהוות הי' צ\"ל הצמצום באוא\"ס שהוא בבחי' סילוק האור כו' (ועמשנת\"ל\nפכ\"ח) (וידוע שע\"י סילוק האור נעשה אותיות הרשימו בבחי' מציאות כו' וכמ\"ש במ\"א). וזהו שאחר ברוך הוא שזהו בחי' ההשערה שלפני הצמצום או' ברוך אומר ועושה שהוא בחי' האמירה השייך לעשי' ופועל ההתהוות, והוא בחי' הרצון ומחה\"ק דא\"ק, שזהו ג\"כ בכללות ההשתל' וכמא' צופה ומביט כו', רק שזהו לאחר הצמצום וע\"כ הוא בחי' הרצון השייך לפועל כו'. וזש\"א ברוך אומר ועושה דבתחלה אומר שאמר סתם מפני שאינו שייך עדיין לעשי', רק או' שאמר והי' העולם שהוא הרצון להיות דבר נבדל כו' אבל אינו שייך לעשי' עדיין כו', וכאן או' אומר ועושה שיש לזה שייכות לעשי' כו'. אך גם אמירה זו היא בבחי' מח' ורצון עדיין שז\"ע אומר ועושה דאמירה היא בלב כו'. אמנם ברוך גוזר ומקיים הוא בחי' הגזירה בדבור להיות קיום הדבר, וכמו עד\"מ מלך שגוזר אומר בדבור להיות כך וכך שבודאי יהי' הדבר, משא\"כ כשהוא במח' לבד יוכל להיות שלא יבוא עדיין לפועל כו', או שיומשך עוד זמן הרבה כו', אבל כשגוזר בדבור ודאי יהי' הדבר תומ\"י כו'. ועד\"ז הוא הדוגמא למע' במש\"א גוזר ומקיים הוא שבא לידי דבור שזהו בחי' יצי' דכללות שהוא בחי' ההתגלות מא\"ק כו'. וי\"ל ע\"פ משנת\"ל פס\"ה וס\"ו דמחה\"ק"],[3601330287,"דא\"ק הוא בבחי' הסכם לבד עדיין ולא בבחי' רצון ממש, והיינו דבמדרי' שאחר הצמצום הנה בחי' א\"ק הוא רק בבחי' הסכם ואינו מוכרח עדיין להיות התהוות המציאות בפו\"מ כו', ולכן מה שנתהווה בבחי' א\"ק שהרי כשעלה במח' מיד נתהווה כו', ה\"ז לא בבחי' מציאות עדיין וכמ\"ש בע\"ח דכלים דא\"ק הן רק בחי' שרש נשמות דגופות כו'. אבל בבחי' הדבור שזהו בחי' יצי' דכללות נתהווה מיד דהיינו כמ\"ש בע\"ח שער העקודים דהתחלת הכלים הוא בעקודים כו', ועם היות שהיא רק בבחי' כלי אחד מ\"מ הרי זה בחי' כלים כו'. ואח\"כ ברוך עושה בראשית הוא בחי' עשי' דכללות דהיינו עולם האצי' שנק' עשי' ע\"ש בחי' הכלים דאצי' שהן בבחי' מציאות דבר כו' וכמ\"ש במ\"א. וזהו עושה בראשית בחי' החכ' שנק' ראשית לפי שהיא ראשית ההשתל' והיא בחי' עשי' לגבי אוא\"ס וכמ\"ש כולם בחכ' עשית שהחכ' היא בחי' עשי' כו', ופי' עושה בראשית הוא מה שהחכ' היא בחי' עשי', ומה שע\"י החכ' הוא עשיית והתהוות העולמות בפו\"מ וכמ\"ש בראשית ברא בחוכמתא ברא כו', וכתיב בחכ' יבנה בית כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה בהרצון הנ\"ל אינם ניכרים הפרטים גם לא לעצמו כבי', וע\"כ שיער בעצמו מה שעתיד להיות והו\"ע גליף גליפו. וזהו ברוך הוא, וג\"ז אינו בערך שיהי' מזה ההתהוות דלפני הצמצום הרי גם בבחי' ההשערה הי' גילוי אוא\"ס הבל\"ג, וע\"י הצמצום בחי' סילוק האור נתהווה בחי' מחה\"ק דא\"ק שזהו ג\"כ אמירה במח' רק ששייך לפועל, וזהו אומר ועושה, ולהיות שזהו בבחי' הסכם בלבד, הי' אח\"ז התגלות הרצון שז\"ע גוזר ומקיים והוא בחי' יצי' דכללית, ואח\"כ עושה בראשית בחי' עשי' דכללית.</span>\nעא) <b>נמצא</b> שיש כאן ה' מדרי' בחי' הרצון הפשוט שז\"ע בריש הורמנותא דמלכא שבמדרי' זו לא יש עדיין פרטים כלל גם לא בבחי' גילוי לעצמו כו', ומה שגליף גליפו בטה\"ע הוא בבחי' התגלות הפרטים אבל הוא לעצמו עדיין כו', והוא באוא\"ס שלפני הצמצום כו', ואח\"כ ג' מדרי' לאחר הצמצום והן בחי' בי\"ע הכללים כו'. ובד\"כ זהו בחי' נר\"ן וח\"י דבחי' הרצון הפשוט להיות שאין בו מדרי' פרטים גם לעצמו זהו בחי' יחידה כו', ובחי' ההשערה בכח הוא בחי' חי' וכנודע דבחי' חי' הוא שיש לזה שייכות אל הפנימי כו'. וכמו בבחי' כתר דאצי' בפרט בחי' חי' זהו בחי' חיצוניו' הכתר שנקרא ריש ומקור לנאצלים ויש שם התכללות הע\"ס וכידוע בענין מאה שנה כו', אך הספי' דשם הן בבחי' חקיקה כו' וכמ\"ש בלקו\"ת בהביאור דאם בחקותי ובהבי' דזאת חקת התורה. ובחי' בי\"ע הן ג' מדרי' נר\"נ כו'. ובכ\"א מהה' מדרי' אומר ברוך שהוא בחי' ההמשכה, להיות דבחי' העצמות הוא למע' גם מבחי' הרצון הפשוט שהוא בחי' הארה לבד כו' (וכמשנת\"ל פס\"ט), עז\"א ברוך שאמר כו' להיות המשכת האמירה\nוהרצון הפשוט כו' דהיינו שמבחי' עצמות א\"ס ב\"ה שקדוש ומובדל לגמרי מגדר עולמות, יהי' המשכת בחי' הרצון הפשוט וההמשכה מההעלם כו'. והענין הוא דהנה תחלת הבריאה הי' מצ\"ע מצד כי חפץ חסד הוא ואח\"כ באתעדל\"ת תליא מלתא, ועז\"א ברוך שאמר להיות המשכת הרצון כו'. והגם דהאור והחיות חיצוני של העולמות (שזהו בכלל בחי' יחוד חיצוני דאו\"א כו') נמשך מעצמו גם בלי אתעדל\"ת וכמ\"ש במ\"א שזהו הכריתות"],[3601330288,"ברית דנח וכמ\"ש עוד כל ימי הארץ כו', מ\"מ ג\"ז צריכים להמשיך ע\"י עבודה כו'. שז\"ע ר\"ה שצריכים להמשיך בחי' הרצון לעולמות בשרש הראשון, וכמש\"א זה היום תחלת מעשיך זכרון ליום ראשון בתחלת כל ההשתל' באוא\"ס שלפה\"צ בחי' הורמנותא דמלכא כו', להיות דבר\"ה חוזר כל דבר לקדמותו וה\"ז כמו תחלת הבריאה וכמ\"ש מרשית השנה חסר א' שהאור והחיות מסתלק למע' כו'. והגם דסילוק האור דר\"ה הוא ג\"כ רק בפנימיות אבל חיצוניות החיות נשאר כו', דמשו\"ז העולם הוא בקיומו כו' וכמ\"ש במ\"א, הנה באמת האור והחיות הוא במיעוט מאד בליל א' דר\"ה עד תקיעת שופר דז\"ע בחי' דורמיטא דז\"א שהאור הוא במיעוט מאד כו', וממשיכים אור וחיות חדש ע\"י תקיעת שופר וט' ברכות דמוסף דר\"ה כו'. וכן הוא בכל יום דלילה הוא זמן החשך ובחי' סילוק האור ונשאר רק מעט חיות, והו\"ע השינה בבחי' קיסטא דחיותא כו', דתרעין דג\"ע אסתימו בלילה דכל ההשפעות בעולם הוא מג\"ע ובלילה תרעין דג\"ע אסתימו כו' וכמ\"ש בתו\"א ד\"ה והבדילה הפרוכת בפ' לך לך, ובכל יום צריכים להמשיך מחדש כו', והעיקר הוא\nלהמשיך תוס' אורות להיות הגילוי למטה כו'. וזהו ג\"כ ענין המשכת הרצון למלוכה דר\"ה, דמה שבר\"ה נמשך רצון לעולמות הוא ע\"י המשכת הרצון למלוכה שממשיכים בר\"ה, וענין המלוכה הוא להיות גילוי אור למטה כו', דפעם הראשון מלוכה שנא' בתורה הוא גבי קרי\"ס כמ\"ש ה' ימלוך לע\"ו והרי בקרי\"ס הי' גילוי אוא\"ס למטה כו'. וזהו ג\"כ ענין המשכת המלוכה דר\"ה, וכנודע ההפרש בין מלוכה לממשלה כו', דמה שאנו מבקשים מלוך על העולם בכבודך כו' הוא שיהי' גילוי המלוכה כו'. דע\"פ סדר השתל' הרי האור מתמעט ממדרי' למדרי' עד שלמטה הוא בחי' חשך והעלם והתגברות הישות כו', וע\"ז הוא העבודה להמשיך תוס' אור להיות למטה גילוי אור כו'. וע\"ז הוא ירידת הנשמות למטה וכמ\"ש נר הוי' נשמת אדם כי להיות עוה\"ז הוא עולם השפל והחשך עב כפול ומכופל וצריך להרבות בנרות להאיר את החשך, וע\"כ ברא אלקים את האדם שהוא נר המאיר הארת ש' הוי' בבחי' גילוי להאיר את העוה\"ז להיות אתהפכא חשוכא לנהורא. ועז\"נ והי' ברכה, ברכה בקרב הארץ שהוא בחי' ההמשכה להיות הגילוי למטה כו', והיינו\nשע\"י שממשיכים האור בגילוי בנפשם ע\"י ההתבוננות שמתבוננים באלקות, וההתבוננות היא בהעמקת הדעת שלא תהי' בבחי' מקיף לבד כ\"א שיהי' נרגש בפנימיות, שאז יגיע הדבר לעצמות נקודת נפשו ויתעורר בהתעוררות אמיתי שיהי' חפצו באמת באלקות, ולא ירצה כלל להיות בחשכת החומריות דנה\"ב רק רוחו ונשמתו אליו יאסוף בבחי' התאחדות באלקות כו'. ועי\"ז הוא מברר ומהפך ג\"כ חשכת העולם ולהיות גילוי אלקות בעולם כו', דגם את העולם נתן בלבו שהעולם נתון בלבו של אדם שע\"י שממשיך הגילוי בנפשו ויצא מחשכת הנה\"ב כו' (ובזה יש ב' אופנים או שיצא מהחשך היינו שע\"י הגילוי בנפשו ה\"ה למע' מעניני החומרים שעי\"ז נחלש החומריות דנה\"ב כו', או שע\"י הגילוי בנפשו פועל בהנה\"ב גופא לצאת מן החשך, והיינו שבההתבוננות מבין גם השכל הטבעי את הענין האלקי, ובהתעוררות המדות דנה\"ב מתעורר גם הנה\"ב בבחי' רצוא ואהבה לאלקות כו'. וזהו עיקר העבודה ותכלית הכוונה וכמ\"ש ואהבת כו' בכל לבבך בשני יצריך כו', ועי\"ז פועל בעולם להיות אתהפכא חשוכא לנהורא שיהיו הדברים התחתונים כלים לאלקות כו'). וזהו ברוך שאמר והי' העולם, פי' להיות שאמר והי' העולם בבחי' ברוך וגילוי בלב האדם"],[3601330289,"והיינו שמההתבוננות דשאמר והי' העולם יהי' ההתפעלות בלב כו', וכן ברוך הוא שבחי' הוא יהי' בבחי' גילוי בלב שיהי' הלב מתפעל כו'. וכ\"ז הוא ע\"י תוס' אור מלמע' שז\"ע ברוך שאמר להיות בחי' אמירה זו בבחי' תוס' אור משרשה ומקורה בחי' עצמות א\"ס ב\"ה, שעי\"ז יהי' הגילוי למטה בנה\"א ובגילוי בעולם להאיר את החשך כו', ועי\"ז אח\"כ ההמשכה מבחי' עצמות א\"ס ב\"ה בחי' ישת חשך סתרו בחי' העלם העצמות שלמעלה מבחי' אור כו'.\n<b>ועפ\"ז</b> יובן מש\"א זה היום תחלת מעשיך, פי' תחלת מעשיך היינו עיקר הכוונה דתכלית הכוונה בבריאת והתהוות העולמות הוא להמשיך גילוי אור אין א\"ס למטה, וזה נשלם ע\"י העבודה דנשמו' ישראל כנ\"ל. וזהו זה היום דר\"ה יום ברוא אדם הראשון הוא תחלת מעשיך שזהו עיקר הכוונה בברה\"ע שממשיכים בחי' גילוי אוא\"ס למטה כו'. וזהו זכרון ליום ראשון, יום ראשון הוא התחלת כל ההשתלשלות בחי' הרצון לעולמות בחי' הרצון הפשוט כו', ולהיות דבראש השנה ממשיכים בחי' הרצון למלוכה שזהו מבחי' עצמות אור אין סוף ב\"ה, ה\"ז זכרון ליום ראשון דבחי' רצון הנ\"ל שהוא בחי' חיצוניות ואינו בערך בחי' העצמות, ע\"כ צריכים ע\"ז זכרון כו'. ומכל מקום נמשך הזכרון ע\"ז דעל ידי הרצון למלוכה נמשך הרצון לעולמות ושיהי' בבחי' גילוי אור כו'. וזהו זה היום דר\"ה יום ברוא אדה\"ר הוא תחלת מעשיך עיקר הכוונה כו', דבכ\"ה באלול נבה\"ע הוא בחי' חיצוניות הרצון, אבל פנימיות הרצון הוא בנשמות ישראל וזה ממשיכים בר\"ה והוא זכרון ליום ראשון בחי' הרצון שבעולמות ויהי' בגילוי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> נמצא יש ה' מדרי' בחי' רצון הפשוט, ובחי' גליף גליפו, והן בחי' יחידה וחי', כי ההשערה יש לה מ\"מ שייכות אל העולמות, וג' מדרי' לאחר הצמצום והן נר\"ן, וברוך שאמר הוא שיומשך מן העצמות להיות בחי' אמירה ורצון, כי עכשיו באתעדל\"ת תלי' מילתא, והעיקר להמשיך בחי' פנימיות הרצון שעי\"ז יהי' הגילוי למטה, וזה\"ע המשכת הרצון למלוכה בר\"ה, וע\"ז הוא ירידת הנשמה להאיר חשך העולם ע\"י העבודה בהתבוננות ואהוי\"ר להאיר חשך הנה\"ב. ובזה יובן מש\"א זה היום דר\"ה בריאת האדם תחלת מעשיך עיקר הכוונה, זכרון ליום ראשון הוא הרצון על העולמות.</span>"],[3601330290,"<h3>בס\"ד. יום ב' דר\"ה. תער\"ג</h3>\n<b>אני</b> לדודי ודודי לי הרועה בשושנים, ואי' בזהר בשושנים ששונים בהלכות, וצריך להבין מה שייך ענין ששונים בהלכות לאני לדודי כו'. גם מהו ענין הרועה בשושנים, דמרעה שייך גבי צאן כו'. ולהבין זה יש להקדים מה שנת' לעיל בה' מדרי' דברוך שאמר עד ברוך עושה בראשית שהן ה' מקיפים דנר\"נ ח\"י והו\"ע בחי'"],[3601330291,"הרצון פשוט והשערה בכח שבאור אין סוף שלפני הצמצום וג' מדרי' בי\"ע הכללים שאחר הצמצום.\nעב) <b>והנה</b> נגד ה' מדרי' הנ\"ל דברוך שאמר אנו אומרים בברכת יוצר אלקי עולם ברחמיך הרבים רחם עלינו אדון עוזינו כו', פי' אלקי עולם הוא מי שאמר והי' העולם בחי' עצמות א\"ס בעל הרצון שלמע' מבחי' רצון, ולמעלה מבחי' אור בכלל כו'. דהנה מבואר במ\"א דעצמות אין אנו יכולים לכנות בשום שם וכינוי ח\"ו, כי כל שם הוא תואר דבר מה שמתאר את הדבר הנק' בהשם ההוא, וא\"כ בהכרח שהמתואר הוא באיזה מציאות דבר בעצמו ששייך בו התפיסא וההגדרה באיזה דבר, דמשום זה אפשר לתארו, מה שבעצמות אינו שייך כל זה כו'. וגם שם מאור אינו שייך על העצמות, דשם מאור מורה שהעצם הוא בחי' אור בעצם מציאותו, רק שאינו אור בגילוי שזהו רק הארה לבד כ\"א בחי' עצם כו', אבל בעצם מהותו הוא אור כו', ובעצמות אינו שייך לומר כן, דהגם שהאור נמשך ממנו אין העצמות בבחי' מאור כו'. ולכן המשל דאור השמש מהשמש אינו משל מכוון עדיין לאוא\"ס, דהרי השמש הוא בבחי' מאור שזהו כל מהותו כו', והעצמות אינו בבחי' מאור כו', ואנו מכנים אותו ית' בשם מאור לפי שאין לנו שם אחר\nוכשאנו מדברים בענין האור אנו מכנים עצמותו ית' בשם מאור, אבל באמת אינו שייך בו ית' השם מאור כו' וכמ\"ש במ\"א באורך. ומה שאנו יכולים לכנות בעצמות הוא רק בשם בורא, דשם זה אינו כינוי ותואר, שאינו מתאר אותו ית' באיזה ענין פרטי כמו מאור וכה\"ג, ואדרבה מורה שהוא ית' קדמון האמיתי, וע\"כ לו ית' היכולת לברוא מאין ליש כו' ושהוא נמצא בבחי' מציאות בלתי נמצא כו'. וכמו שנת\"ל פס\"ט בשם האגה\"ק דכח ההתהוות הוא בעצמות דוקא משום דמציאותו מעצמותו ע\"כ בכחו ויכולתו להוות יש מאין כו', הרי דענין הבריאה וההתהוות מורה על קדמותו ית' שמציאותו מעצמותו כו', ומאחר שמציאותו מעצמותו הרי מציאותו ית' הוא בבלתי מציאות נמצא כו'. ולכן ההתהוות היא ג\"כ באופן כזה שנתהווה יש מאין ואפס המוחלט ממש בלי שום עילה וסיבה אחרת קודמת ליש הזה כמ\"ש באגה\"ק הנ\"ל, וגם שהיש באמת אינו במציאות כלל, כי מציאות היש הוא התחדשות, וכל התחדשות הוא רק כח המחדש אותו ובלעדו לא יש ההתחדשות כלל וכמ\"ש במ\"א באורך, והרי מציאות היש הוא בדוגמא נמצא בבחי' בלתי מציאות\nנמצא (וזה מפלאי תמים דעים כל יכול ית' להוות דבר בדוגמת העצמות), וא\"כ הרי ההתהוות מורה על אמיתת עצמותו ית'. וז\"ע אלקי עולם שהוא ענין בורא עולם דבשם זה אנו יכולים לכנותו והוא המורה על אמיתת העצמות כו'. ומש\"א ברחמיך הרבים י\"ל שזהו בחי' האור והגילוי מן העצמות אך זהו בחי' עצמות האור שלמעלה עדיין מבחי' הרצון הפשוט כו', והוא האור כמו שהוא בבחי' א\"ס ממש שאינו בו שום שם עדיין כו', וממילא אינו בבחי' מקיף ג\"כ, שהרי הרצון הוא בבחי' מקיף עכ\"פ לעולמות, משא\"כ האור שבבחי' א\"ס ממש אינו בבחי' מקיף ג\"כ כו', רק הוא מקור כל המקיפים כו' דהמקיפים הן בבחי' התפשטות האור (דשם שייך שם רצון כו' וכמו שנת' לעיל פנ\"ז) וה\"ה נמשכים מן האור העצמי כו'. והענין הוא דהנה עצמות בעל הרצון אינו גם בבחי' מקור לרצון כו', והאור גם בחי' עצם האור ה\"ה בבחי' מקור לרצון עכ\"פ כו', וכמ\"ש במ\"א בענין אתה הוא הוי' לבדיך דהוא קאי"],[3601330292,"על אור הא\"ס בחי' עצם האור, ונק' הוא לפי שבו שייך בחי' העלם וגילוי כו' והיינו בחי' ההעלם של הגילוי כו', דבעצמות אינו שייך העלם וגילוי וע\"כ נק' אתה שנמצא כמו שהוא בהעלמו כו', ובהאור שייך העלם וגילוי היינו שזהו בחי' העלם של הגילוי כו', הרי שהוא בחי' מקור עכ\"פ כו'. וזהו דבחי' עצם האור הוא מקור כל המקיפים כו'. ואין זה סותר למשנת\"ל פס\"ט, דעם היות שהוא למעלה מבחי' רצון הפשוט, ואין לומר בו מה ששייך לומר בהרצון הפשוט כו', ומ\"מ הוא בחי' מקור המקיפים כו', ועמשנת\"ל פט\"ז שזהו בחי' שרש ומקור דבחי' סוכ\"ע כו'. וידוע די\"ג ברוך דברוך שאמר הן בחי' יגת\"ד שהן יגמה\"ר ע\"כ אומר במקור כל ההמשכות ברחמיך הרבים, ונודע ג\"כ די\"ג ברוך דברוך שאמר כולם הם בחי' מקיפים ויש בזה מקיפים דאור ישר (שהן מדרי' הנ\"ל) ומקיפים דאו\"ח כו', וברוך שמו הוא המקור הכולל כולם כו' וכמ\"ש במ\"א. וזהו ג\"כ ענין ברחמיך הרבים בחי' מקור כל המקיפים שהוא בחי' רחמים פשוטים לגמרי שאין בזה התחלקות מדרי' כלל כו', ואח\"כ נחלק לה' מדרי' נר\"נ ח\"י והמקיף\nהראשון מקיף דיחידה שהוא בחי' מקיף דרצון פשוט שאמר והי' העולם הנ\"ל שהוא בחי' יחידה והו\"ע רחם עלינו כו', דלהיותו בבחי' מקיף עכ\"פ אומר ע\"ז רחם עלינו כו'. והמדרי' הב' בחי' מקיף דחי' והוא אדון עוזינו שהרצון בא מהעלם אל הגילוי בבחי' השערה בכח שז\"ע ברוך הוא כו', ונק' אדון עוזנו לפי שהמקיף דחי' יש לו שייכות אל הפנימי ונותן כח ועוז בהפנימי כו'. וכ\"ז הוא באוא\"ס שלפני הצמצום כו' (בחי' אצי' דכללות כו'). ואח\"כ ג' מקיפים צור משגבינו מגן ישענו משגב בעדינו שהן מקיפים דנר\"ן בחי' בי\"ע הכללים כו', צור משגבינו בחי' מחה\"ק דא\"ק וכנודע דצור הוא ששרשי ההויות הן בו בהעלם כו', דכן הוא במדרי' שאחר הצמצום בבחי' מחה\"ק דא\"ק שהכל שם בבחי' העלם לגמרי (בבחי' העלם שאינו במציאות וכמ\"ש במ\"א) כו', מגן ישענו בחי' יצי' דכללות דמגן הוא שבא בבחי' גילוי, דז\"ע שגבי אברהם כתיב אנכי מגן לך מגן אברהם כו'. ואברהם הוא בבחי' עקודים וכמ\"ש בע\"ח שער העקודים פ\"א שז\"ע ויעקוד את יצחק בנו כו', והיינו בחי' יצי' דכללות בחי' גילוי כו'. ומשגב\nבעדינו בחי' עשי' דכללות, דמש\"א משגב בעדינו הוא ע\"ש הפסוק ה' צבאות עמנו משגב לנו כו', והיינו שהוא עמנו בבחי' קירוב ממש בבחי' עשי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכנגד זה יש ה' מדרי' ביוצ\"א, אלקי עולם הוא בורא עולם דרק בזה יכולים לכנות בחי' העצמות שזה מורה שמציאותו מעצמותו ושהוא נמצא בבחי' בלתי מציאות נמצא, ברחמיך הרבים הוא בחי' אור הא\"ס שלמע' מבחי' הרצון והוא מקור כל המקיפים, רחם עלינו בחי' הרצון פשוט שאמר וה\"ע מקיף דיחידה, אדון עוזנו ההשערה בהרצון, מקיף דחי' שנותן עוז בהפנימי, צו\"ר משגבנו מחה\"ק דא\"ק, מג\"ן ישענו יצי' דכללות, משגב בעדנ\"ו עשי' דכללות.</span>\nעג) <b>ובפרטיות</b> י\"ל כל המדרי' האלו בבחי' מל' דאצי', דהנה ידוע בענין נעוץ תחלתן בסופן שיש נעיצת התחלה בסוף יותר מבראש המתפשט, והיינו דבחי' מל' שהיא סופא דכל דרגין דאצי' יש בה נעיצת התחלה יותר מבחכ' שהיא ראשית האצי' כו'. דהנה חכ' היא ראשית ההשתל' דההמשכה מהחכ' אל הבינה הוא בבחי' עו\"ע כו' (והגם שנת\"ל פמ\"א ומ\"ב דחו\"ב הן אין ויש"],[3601330293,"שהבינה אינה משיגה האין דחכ' כו', ונת' שם דעיקר הידיעה דחכ' הוא בבחי' ראי' ובבחי' התאמתות, וגם בבחי' נקודת ההשכלה דחכ' עם היות שהוא שכלי, מ\"מ העיקר בזה הוא ההנחה בשכלו (דער לייג אין שכל), והוא בחי' האין דחכ' שאינו מושג בבינה כו'. מ\"מ אצי' הבינה מהחכ' אינו בדרך יש מאין, שהרי באמת אין התהוות הבינה בעצם מהותה מן החכ', וכנודע שהבינה יש לה מקור מיוחד מכח המשכיל כמו החכ' כו', ולכן יש מי שהוא בעל השגה ואינו בעל הבנה, דעם היות שאין בכחו להמציא שכל חדש מ\"מ בכחו להבין כל ענין שכלי בהשגה טובה, והעיקר בבחי' הרוחב היינו לפרט כל הפרטים שבנקודת ההשכלה שמקבל מזולתו כו', וגם לבוא על עומק הענין כו' וכמ\"ש במ\"א. וענין אצי' הבינה מהחכ' הוא רק התגלות לבד, והיינו ההשגה דבינה לא עצם הכח, דעצם הכח דבינה יש לו מקור מיוחד כנ\"ל, רק השגה דבינה א\"א להיות בלי נקודת החכ', וכמו שא\"א להיות נהר בלא מעיין כו', והתהוות ההשגה הוא מהשכלי שבנקוד' ההשכלה שזהו בדרך עו\"ע שהעילה מתלבשת בהעלול, שזהו ההפרש בין עילה ועלול ליש מאין,\nדיש מאין הרי האין המהווה את היש נשאר בהעלם, דהתהוות מציאות היש הוא ע\"י שהאין מתעלם ומסתתר מהיש כו' כנודע, וכ\"ש שאינו מתלבש ומתגלה בו כו'. ועם היות שנת' לעיל פנ\"ג דהתחדשות דבר הוא ע\"י התלבשות דוקא כו', הרי התלבשות זו אינה בבחי' התגלות כ\"א בבחי' העלם דוקא כו', וההעלם הוא באופן כזה שאין האין נרגש כלל בהיש שבאם יהי' נרגש בו לא יהי' בבחי' מציאות יש כו'. ובעילה ועלול העילה מתלבשת ומתגלה בהעלול ועי\"ז הוא דוקא התהוות העלול כו' וכמ\"ש במ\"א, ונת' בקצרה לעיל פ\"מ. ובאופן כזה הוא ג\"כ בחו\"ב שהשכלי שבהנקודה מתלבש' ומתגלה בההשגה, שהרי זהו\"ע ההשגה שמשיג את הנקודה כו', וההנחה שבנקודת ההשכלה שזהו האין שאינו מושג בבינה ה\"ז בשתי פנים, או שלא מזה הוא התהוות ההשגה, והיינו דההשגה הוא מהשכלי שבהנקודה כנ\"ל וההנחה נשארה בהעלם, והיינו שבעת ידיעת הענין מנקודת ההשכלה (מי ששייך לידיעה זו דנקודת ההשכלה דחכ' כו'), עיקרה של הידיעה הוא בבחי' הנחה, וכאשר בא לידי השגה נשארה ההנחה בהעלם ומה שבא לידי גילוי בההשגה הוא השכלי\nשבהנקודה כו'. או לפעמים כשהתהוות ההשגה היא מההנחה שבנקודת ההשכלה, הוא שע\"י הרגש ההנחה בא לידי השגה פנימית בהענין, והיינו כאשר בא אל נקודת ההשכלה וההנחה (אז ער טראגט זעך צו וויא האט זעך בא עם גילייגט דער ענין בעת שנפל לו המצאת הענין), הרי בא על עומק הענין בהשגה פנימיות יותר כו'. שזהו כדוגמת יש מאין שהרי ההנחה בעצם אינה באה בההשגה שהרי הוא למע' מהשגה רק מה שבכח ההנחה בא לידי השגה כו', ואין זה כמו בהשכלי שבהנקודה שהשכלי ממש בא בההשגה, משא\"כ בההנחה שזהו רק מה שע\"י הרגש ההשגה בא לידי השגה גדולה כו', ה\"ז כדוגמת יש מאין כו', ומ\"מ הנה זהו דוקא ע\"י הרגש ההנחה ועי\"ז דוקא נמצא הבנת והשגת הענין כו', והשגה הזאת היא בעומק הענין ופנימיותו כו'. א\"כ הרי ג\"ז אינו כמו יש מאין דשם הרי אין האין נרגש כלל בהיש, וכאן אם לא יהי' הרגש ההנחה לא יהי' מזה שום התחדשות בהשגה כ\"א ע\"י הרגש ההנחה כו', א\"כ א\"ז כמו יש מאין ממש כו'. והדוגמא מזה בבחי' חו\"ב שאין זה בבחי' יש מאין כו', ומה שחו\"ב נק' אין ויש היינו בבחי'\nהרוחניות שהבינה נק' יש רוחני לא יש ממש (וגם החכ' אינו בבחי' אין ממש היינו כמו השכלי שבהנקודה עד\"מ), ומה שנת'"],[3601330294,"במ\"א שהחכ' היא בחי' אין ממש ובינה בבחי' יש (עמ\"ש בסי' ד\"ה מזמור לתודה), ר\"ל שהאין דחכ' הוא בחי' האין של היש האמיתי (וכמו בחי' הראי' וכמו עד\"מ בחי' ההנחה כו'), ובבינה מאיר האין של היש הנאצל כו' ועמשנת\"ל פמ\"ב). וכן הוא בכל הע\"ס שהן בבחי' עו\"ע שהו\"ע השתל' הספי' בספי' עצמן כו'. וזהו עד המל' ומן המל' התהוות בי\"ע הוא בבחי' יש מאין ממש שהאין מהווה ממש את היש בבחי' התחדשות דבר והוא בבחי' העלם לגמרי מן היש כו', דכח זה לא יש בבחי' החכמה ראשית האצי' (שגם ההתהוות מהחכ' שבדוגמת יש מאין אינו בבחי' יש מאין ממש כו' כנ\"ל), כ\"א בבחי' הכתר שמהווה את החכ' מאין ליש וכמ\"ש והחכ' מאין תמצא כו' (וג\"ז רק בחי' יש נאצל כו'), וכח זה יש גם בבחי' מל' להוות יש מאין דבי\"ע כו', דבאמת הרי הכח הזה הוא מעצמות א\"ס וכמשנת\"ל דהוא לבדו בכחו ויכולתו לברוא כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וי\"ל ה' מדרי' הנ\"ל בבחי' מל', דהנה נתב\"ס בבחי' מל' יותר מבחכ', דחו\"ב הן עו\"ע, דהתגלות הבינה הוא ע\"י החכ', ונקודת ההשכלה דחכ' מושגת בבינה, שז\"ע עו\"ע, וההנחה שכלית היא למע' מהשגה ונעלם ממנה, או שבסיבת זה בא להשגה פנימיות יותר, והוא ע\"י הרגש ההנחה אם שאינה מושגת, ויש מאין הוא שנעלם האין לגמרי ואינו מורגש כלל, וכן כל הע\"ס הן בבחי' עו\"ע, אבל מל' מהווה מאין ליש ממש, וכח זה הוא מבחי' הכתר ומבחי' עצמות א\"ס.</span>\nעד) <b>וזהו</b> נעוץ תחלתן בסופן, פי' תחלה הוא בחי' א\"ס קדמון לכל הקדומים שאין לו תחלה ואין לו תכלה, ומה שאנו קוראין אותו תחלה אין זה שהוא בבחי' תחלה וראשית להגילוים והדברים שנתהוו כו', כ\"א ע\"ש שהוא תחלת הכל, וכמו שנק' סבה הראשונה (ולא שזהו בבחי' סיבה ומסובב כו'), וכמ\"ש הרמב\"ם דמאמיתת המצאו נמצאו כל הנמצאים כו'. וכוונת נעיצת התחלה הוא בסוף דוקא דבבחי' מל' דוקא יש כח העצמות כו', דבחי' המל' מושרשת בעצמות א\"ס ב\"ה שז\"ע מלך יחיד בחי' המל' כמו שכלולה במקורה ושרשה בחי' יחיד כו'. והו\"ע המלך הקדוש שקדוש ומובדל בעצם כו', ועז\"א אדון עולם אשר מלך בטרם כל יצור נברא דהיינו מלך בלא עם שא\"צ לעם כו' (שהכל צריכים אליו והוא אינו צריך להם כו'), והוא בבחי' התנשאות עצמי שמצד עצמו כו'. ובשרש הראשון י\"ל שזהו בחי' שמו הכלול בעצמותו דהוא ושמו אחד כו' וכמ\"ש השל\"ה דהוא שמו ושמו הוא כו'. וי\"ל שזהו בחי' היכולת שבעצמות שמיוחד ממש בעצמותו ית', וזהו בחי' המל' הכלולה בעצמותו ית', וכמ\"ש בע\"ח שער א\"א פ\"ב דבחי' המל'\nשרשה למע' מכל הספי' והיינו ברדל\"א, כמו\"כ בשרש כל השרשים בחי' המל' דוקא מושרשת בעצמו' א\"ס ב\"ה (וזהו דר\"ה שממשיכים אז מחדש בחי' הרצון למלוכה והרצון לעולמות כו' וכמשנת\"ל פע\"א, ה\"ז נק' יום הזכרון וכמו זכרון ליום ראשון כו', דזכרון שייך על דבר שאינו תופס מקום כו', והיינו לפי שההמשכה היא מבחי' עצמות א\"ס שלמע' מכל הגילוים כו', וממשיכים זה ע\"י הקבעומ\"ש דראש השנה דע\"י שנשמות ישראל נותנים עצמן בכל פנימיות נפשם לעצמות א\"ס ב\"ה ומקבלים עליהם מלכותו ברצון, עי\"ז ממשיכים מעצמות להיות רצון למלוכה כו'), ובחי' מל' דאצי' יש בה כח העצמות שז\"ע כח ההתהוות שבמל' והו\"ע אלקי עולם כו'. ומה שא' ברחמיך הרבים י\"ל דהנה ידוע דבבחי' שמו יש ב' אופנים, הא' כמו"],[3601330295,"שכלול בעצמותו והב' כמו שהוא בהמשכה והתגלות כו' (והוא בחי' עצם האור כו'), וכמ\"ש בסי' שער יוה\"כ בענין קדוש ונורא שמך דענין נורא הוא בבחי' התגלות השם כו', וכמו\"כ במל' שיש בה כח העצמות שזהו בחי' שמו הכלול בעצמותו יש בה כמו\"כ בחי' התגלות השם כו'. וי\"ל דהכל הוא מה ששייך להתהוות, דכח העצמות הוא בהעלם והתגלות השם הוא שבא בגילוי להוות כו', והכל הוא שכלול בעצמותו עדיין קודם שבא גם בבחי' רצון להוות כו'. וי\"ל דמדרי' הא' היא ע\"ד מ\"ש בבה\"ז בלק ד\"ה כי מראש צורים בענין אושיט פסיעה לבר שזהו שרש אותיות הדבור שבמל' דתבונה הנק' מחשבת שכל כו' וע\"ש שכ' כי הוי\"ו הוא בחי' ז\"א כו', והפסיעה לבר דאושיט חוץ לעצמותו שרשו ג\"כ מבחי' בינה כו', והיינו רק שמתהווה שרש ומקור למציאות האותיות של הדבור, אך עדיין הוא בבחי' התכללות כו', כי בחי' ז\"א שכלול באימא נק' מדות שבשכל כידוע, ובחי' פסיעה לבר מעצמותו הוא בחי' מחשבת שכל כו' עכ\"ל. ומדרי' הב' הוא כמו שהמל' הוא בתוך הז\"א בחי' כח הגילוי כו' וכמשית\"ל פ', ועמ\"ש במ\"א בד\"ה כי\nתבואו כו' ושבתה הארץ דמחשבת שכל הגם שיש שם אותיות ה\"ה מקושרים עדיין בהתרחבות ההשכלה כו', אבל כשחושב אותיות אדון עולם במיעוט ההשכלה ה\"ז בחי' דבור שבמח' כו'. וענין רחם עלינו שזהו בחי' מקיף דיחידה י\"ל שזהו בחי' כתר מל' דאיהו כתר עליון כו', והנה כתר מל' י\"ל שזהו בחי' אני שבאין דאני הוא בחי' עצמות אוא\"ס וכמ\"ש אני הוי' דפי' אני הוא עצומ\"ה הנושא ע\"ע שם העצם דש' הוי', ובחי' מל' הוא בחי' האין המהווה יש דבי\"ע, ואני שבאין הוא בחי' אוא\"ס שבמל' והו\"ע רוממות הטבע. דטבע הוא מל' טבעו בי\"ס דהיינו שהאלקות נעלם ונסתר כו', אך רוממות הטבע הוא שהאלקות נראה ונגלה כו', והן הניסים המלובשים בדרכי הטבע שנמשכים מבחי' רוממות הא\"ס שלמע' מטבע העולמו', ולכן הנס בעצם הוא למע' מהטבע רק שמלובש בטבע להיות שזהו מבחי' אני שבאין דמל' כו', וז\"ע כתר מל' בחי' רוממות הא\"ס שבמל' כו'. וידוע דהרחמים הוא מן הרוממות דוקא דמי שהוא מרומם יותר יש בו ענין הרחמים יותר, כי רחמים הוא על השפל, וע\"כ נמצא הרחמים במרומם דוקא מפני שהכל שפלים\nנגדו ורואה שפלותם, וכמו המלך נמצא בו הרחמים יותר כו', וכמ\"ש במ\"א באורך. וז\"ע רחם עלינו בחי' הרחמים הנמשכים מבחי' רוממות האוא\"ס שבמל' כו', וכן ע\"י ההתבוננות ברוממות הא\"ס שע\"י הנסים שהן רוממות הטבע נראה וניכר רוממות הא\"ס כו', תפול השפלות בלב האדם ויעורר על עצמו רחמים רבים על מה שהוא רחוק כ\"כ, ולפ\"ע הרגש הרוממות כך ערך השפלות כו' וז\"ע רחם עלינו כו'. ומזה נמשך אור מקיף על נפשו דהיינו אחר שמצד השפלות והריחוק לא יוכל אור האלקי להתגלות בו בבחי' או\"פ יבוא עליו בבחי' או\"מ כו'. וז\"ע אדון עוזנו שע\"י התעוררו' רחמים על נפשו נמשך בחי' הרחמים שלמע' שמבחי' רוממות הא\"ס שבמל' נמשך על נפש האדם להיות שורה עליו בבחי' או\"מ על נפשו כו', וזה\"ע אדון עוזנו שהאו\"מ הנמשך על נפשו נותן לו כח ועוז לצאת מן השפלות והריחוק וכמשי\"ת.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו נתב\"ס, תחלה היינו בחי' עצמות שהוא תחלת הכל, ומל' מושרשת בעצמות, והוא בחי' שמו הכלול בעצמותו, והוא בחי' היכולת, ויש כח</span>"],[3601330296,"<b>העצמות</b> במל' וז\"ע אלקי עולם, והנה בשמו העצמי יש בחי' התכללות והתגלות, שמך קדוש ונורא שמך, וי\"ל דכמו\"כ במל', והוא כמו שכלולה בבינה, וכמו שהיא בחי' כח הגילוי דז\"א, ובחי' ההתגלות זה ברחמיך הרבים, ורחם עלינו כתר מל' בחי' אני שבאין, רוממות הטבע, דרחמים הוא מן הרוממות, ונמשך מזה או\"מ על האדם וז\"ע אדון עוזנו.\nעה) <b>ולהבין</b> ענין אדון עוזנו, הנה במאו\"א אות א' סעי' י\"ב כ' אדון נק' המל' כשיש לה סימני דכורא והיינו כשמתמלאה ש' אד' במלואה ביום שבת אזי נק' אדון זכר (וזה שבשבת אומרים אל אדון כו' וכמ\"ש בפרע\"ח) וכן ש' ב\"ן וט' אותיו' גימ' אדון, וע\"ש סעי' ק\"ב שכמו\"כ אני הוא גימ' הנ\"ל. ובקה\"י כ' אדון גימ' אני כו' (והיינו בחי' אני שבאין בחי' רוממות הא\"ס שבמל' שנעשה אדון עוזנו כו'). וענין סימני דכורא יובן עפמ\"ש בזח\"א דרמ\"ו ע\"א דעלמא עילאה שהיא בינה היא עלמא דדכורא דאף שהבינה מקבל מהחכ' מ\"מ היא בבחי' דכר, וכמ\"ש בזהר שם דכיון דסלקא מלה מכנס\"י ולעילא כולה הוא דכר כו', דלמעלה מהמל' הכל הוא בבחי' דכורא כו'. והוא להיות דאבא עילאה מקננא באצי' לכן כללות האצי' הוא בחי' דכר, ובפרט בינה דאו\"א הן תרין ריעין דלא מתפרשין כו' (והגם דאבא יסד ברתא ה\"ז רק בחי' יסד דעצם שרשה הוא מבחי' אבא אבל בהתגלו' מקבלת מבינה וז\"א כו'). ולהבין זה ע\"ד החסידות הענין הוא דהנה אמרז\"ל לא זז מחבבה עד שקראה בתי אחותי אמי כו', דבת הוא\nבחי' מקבל והיא בחי' המל' שמקבלת מז\"א, משא\"כ אם היא אדרבה שמברכת לבנה כו'. ובעבודה בחי' בת הוא שאין לו כח לעורר האהבה והתשוקה בנפשו מפני חלישות הנפש שאינו יכול לצאת מנרתק הגוף והנה\"ב להתעורר באהוי\"ר ולהיות בבחי' רצוא לאלקות כו', וכמ\"ש אני הוי' לא שניתי ואתם בנ\"י לא כליתם שהנביא מתמה עצמו שמההתבוננות דאני הוי' לא שניתי הי' צ\"ל כלות הנפש, ואתם בני יעקב לא כליתם כו'. והסיבה לזה הוא מפני שהם בני יעקב וכמ\"ש עקוב הלב מכל, פי' עקוב אנוש וחלוש שהוא חלישות כח הנפש שאין בכחו לצאת כו', וסיבת החלישות הוא כמ\"ש כשל בעוני כחי שע\"י העוונות נכשל ונחלש כח הנפש כו', דכשם שלגבי מעלה ארז\"ל בזמן שישראל עושין רצונו של מקום מוסיפין כח כו' ולהיפך מתישין כו', כמו\"כ הוא בנפש שע\"י העון נחלש כח הנפש כו', וענין החלישות הוא שכחות הנה\"א נחלשים שאינו כלי לקבל אור אלקי, וכ\"ש שאין בו כח לצאת מחומריו' הנה\"ב ובפרט להתגבר עליהם כו', ולא עוונות ממש אלא ע\"י עיוות ועיקום שמעקם דרכו ונמשך אחר חומריות הגוף ונה\"ב ה\"ז מחליש כח\nהנה\"א, וכמא' תוקפא דגופא חולשא דנשמתא כו', ומיצר ומגביל את הנפש שהכחות שלה מתעלמים שז\"ע חלישות הכחות כו', והו\"ע טמטום המוח והלב כו', ומלביש את הנפש עד שמורידה לימשך אחריה ואינה יכולה לעלות ולצאת ממנה כו' והו\"ע גלות הנפש כו'. וכידוע בב' מיני התלבשות, הא' שהמלובש מושל וכמו בהתלבשות הנפש בגוף כו', והב' שהמלביש מושל וכמו בענין הגלגולים ר\"ל שהבהמה מושכת את נפש האדם בכל החומריות שלה ואינו יכול לעזור א\"ע כו' וכמ\"ש במ\"א. וכן הוא בהתלבשות הנפש האלקית בנפש הבהמית הנה כאשר הכחות דנה\"א הן בהתגלות בנפש הבהמית הרי הנפש האלקית מושל ושולט על הנפש הבהמית כו', וכאשר יש ח\"ו התגברות"],[3601330297,"מהנפש הבהמית הרי היא מושלת עליו ואינו יכול לצאת כו', רק להיות דהתלבשות זאת בנפש הבהמית שבאדם שמוכנת עכ\"פ לקבל צורת נפש האדם היינו הנה\"א כו', ע\"כ גם כשהיא בגלות ר\"ל יש לו עצה ותקוה כו', משום דמ\"מ אינה בבחי' התעלמות לגמרי כמו בגלגול, וגם המלביש הוא בצורת אדם עכ\"פ (הגם שבצד א' יש בזה גרעון שהרי הוא מסתיר על הנפש האלקית, משא\"כ בגלגולים הוא רק מה שגוף הבהמה אינו מוכן לקבל צורת הנפש דהתעלמות הנפש הוא מצ\"ע כו'. מ\"מ יש בזה מעלה מה שהנפש הבהמית מוכן כו' שאין ההתעלמות כ\"כ, ויש מקום שיתגלה בו כחות הנפש האלקית כו', ולכן אנו רואין שגם במרוחקים ר\"ל הנה לפעמים יש בהם תנועות טובות תנועות דיר\"ש כו', והיינו מפני שמ\"מ אין הכחות דנפש האלקית מתעלמים לגמרי ח\"ו), וע\"כ הן מצד המלובש והן מצד המלביש יש עצה כו' והעצה היא תורה שלזה ניתנה תורה לישראל, שהתורה נק' עוז שהיא הנותנת כח ועוז לנפש האלקית להתגבר בעצמו בכחותיו להיות כלי לאור אלקי בהשגה אלקית והתעוררות אלקי כו', שכ\"ז יש בנפש האלקית בעצם והתו' נותנת כח להתגבר\nבעצמם כו', וגם להתגבר על חומריות הגוף ונפש הבהמית וגסותן לצאת ממסגר אסיר כו'. וזהו בחי' בת בחי' מקבל והיינו שאין לו כח להתעורר באהבה ויראה מעצמו רק ע\"י התורה, ועז\"נ שמעי בת וראי כו' ושכחי עמך ובית אביך כו', דבכדי שאור התורה יפעול בו צריך ג\"כ להיות איזה הכנה לזה, והו\"ע שכחי עמך ובית אביך, עמך ובית אביך הו\"ע הרגילות שלו מה שהורגל בהענינים החומרים ונמשך אחריהם כו', צ\"ל עכ\"פ שכחי עמך כו' והו\"ע תשובה תתאה שישנה דרכו בהדברים בפועל עכ\"פ ויגדיר א\"ע שלא להיות בהתפשטות החומריות, דהיינו שבפועל עכ\"פ לא יניח את הנה\"ב להתפשט כו', והעיקר לכפות עצמו בההטבעה חומריות שמורגל בהם וחושב שהן דברים מוכרחים וא\"א בלעדם ואינו חושב בתיקונם כלל, ובאמת המה עיקר המונעים שאינם מניחים התגלות הכחות דנפש האלקית, וצ\"ל הכפי' בפו\"מ בההטבעה החומריות ועי\"ז הוא כלי עכ\"פ שיפעול בו אור התורה לעשות ישועות בנפשו כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש הרועה בשושנים, דהנה מ\"ש אני לדודי ודודי לי זהו העבודה דבאתעדל\"ת אתעדל\"ע והיינו העבודה בהכחות גלוים שבנפש המלובשים בגוף ונה\"ב כו', דפעם כתיב דודי לי ואני לו בבחי' אתעדל\"ע אתעדל\"ת שבנפש זהו בבחי' מקיפים שבנפש כו', ומ\"ש אני לדודי כו' זהו בכחות פנימים שבנפש כו', ובכדי להיות אתערותא דלתתא עז\"א הרועה בשושנים ששונים הלכות דתורה נותנת כח ע\"ז להיות אתערותא דלתתא דה' עוז לעמו יתן שיוכל לעלות כו'. אמנם מ\"ש הרועה כו' הוא כדאי' במדרש אני לו לצאן והוא לי לרועה, ומבו' במ\"א שז\"ע בחי' רעו\"ד שלמעלה מטו\"ד שהקב\"ה רועה אותנו במדרי' זו שנותנים מלמע' כו', וזה נמשך ג\"כ ע\"י התורה. דהנה התורה נדרשת בי\"ג מדות שהן י\"ג מדה\"ר וע\"כ בה וע\"י מאיר בנפש בחי' המקיפים דנפש שז\"ע רעו\"ד כו', ובכדי שיפעול אור התורה בנפשו זהו ע\"י ההכנה דשכחי עמך ובית אביך כו' כנ\"ל, וז\"ע אני לדודי דקאי על חדש אלול וידוע דאלול הוא בחי' תשובה תתאה שז\"ע שכחי עמך כו', ועי\"ז אח\"כ בר\"ה ויו\"כ באים לבחי' תשובה עילאה כו'. וזהו אני לדודי ודודי לי הרועה בשושנים דבכדי להיות אני לדודי בבחי' אתערותא דלתתא"],[3601330298,"זהו ע\"י ששונים בהלכות כו', וגם בכח התורה לבוא עי\"ז לבחי' רעותא דלבא כו'. וזהו אני לדודי בחדש אלול בבחי' שכחי עמך כו', ועי\"ז רועה אותנו בשושנים בכח התורה לבוא לבחי' תשובה עילאה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וביאור ענין אדון עוזנו, אדון ל' דכורא, ויקדים ענין בתי בחי' מקבל, והיינו שאין בו כח לעורר את האהבה מפני חלישות הנה\"א בהתגברות החומריות שאין בו כח לצאת ולהתגבר, והו\"ע גלות הנפש, וע\"ד ענין הגלגולים ר\"ל, מ\"מ להיות שהנה\"ב מוכן בצורת אדם יכול להיות התגלות והתגברות הנה\"א (והגרעון בזה שמסתיר, והמעלה שיכול להיות התגלות) והוא ע\"י התורה בחי' עוז ותושי', וז\"ע בת שאין היציאה בכח עצמו כ\"א ע\"י התורה, ותחלה צ\"ל שכחי עמך בחי' תשו\"ת, והוא הכפי' בהדברים שמורגל בהם. ובזה יובן אני לדודי שזהו אתעדל\"ת, והוא ע\"י הרועה בשושנים תורה, ופי' הרועה שבא גם לבחי' רעו\"ד והיא תשו\"ע דר\"ה ויו\"כ, ותחלה צ\"ל שכחי עמך באלול.</span>"],[3601330299,"<h3>בס\"ד. שבת תשובה, תער\"ג</h3>\n<b>שובה</b> ישראל עד ה' אלקיך כי כשלת כו' קחו עמכם דברים ושובו כו' אמרו אליו כל תשא עון כו', וצ\"ל מה\"ע קחו עמכם דברים אחר שכבר אומר שובה ישראל מהו עוד קחו עמכם דברים ושובו כו'. ולמה גבי שובה ישראל או' כי כשלת בעוניך ואח\"כ אומר קחו עמכם דברים כו'. גם מהו אומרו אמרו אליו כל תשא עון דמשמע מזה שיש עוד תשובה וצ\"ל מה\"ע תשובה זו כו'. ולהבין כ\"ז יש להקדים משנת\"ל ענין לא זז מחבבה עד שקראה בתי כו' דבת היא בחי' מקבל והוא כשאין כח לעלות מעצמו וצריך לקבל מהתורה ה' עוז לעמו יתן כו'.\nעו) <b>אמנם</b> בחי' אמי בעבודה זהו מדרי' גבוה שבכח זה אדרבה נש\"י הן בבחי' משפיעים בתורה. דהנה פעמים מצינו דנש\"י גדלו ממעלת התו' ופעם בהיפך שהתורה גבהה מעלתה על נש\"י, וכדאי' בתדב\"א שני דברים קדמו לעולם תו' וישראל כו' אומר אני שישראל קדמו כו', ובמד\"ר אי' ז' דברים קדמו לעולם כו', ומחשבתן של ישראל קדמה לכ\"ד, וכן מובן ממ\"ש תורה צוה לנו משה מורשה א\"ת מורשה אלא מאורשה שנש\"י הן בבחי' חתן משפיעים בתורה. ופעם משמע להיפך ממ\"ש בזהר תלת קשרין כו' ישראל מתקשראין באורייתא ואורייתא בקוב\"ה כו'. אך הענין הוא דהנה לא כל הנשמה מתלבשת בגוף ורק בחי' נר\"ן לבד הן שמתלבשים בגוף והיא העבודה שבסדר והדרגה במוח ולב כו', ולגבי מדרי' זו התורה למעלה מנש\"י, דאורייתא מחכ' נפקת דשרשה מבחי' ח\"ע דאצי', וע\"כ היא"],[3601330300,"למע' מעבודת הנשמות בהשגה והתבוננות שלהם שהוא השגות הנבראים שהן באין ערוך לגבי חכמתו ית', ובפרט שהתורה היא מהות חכמתו ית' והשגת הנשמות אפי' נשמות הגבוהות הוא בבחי' ידיעת המציאות וכידוע בענין חכם ונביא כו', ועמ\"ש באגה\"ק בקו\"א ד\"ה להבין מ\"ש בפרע\"ח. ומצד התלבשות הנשמה בגוף ונה\"ב שמעלימים ומסתירים על אור הנשמה כו' ה\"ה צריכים סיוע מהתורה דהתקשרות שלהם ע\"י התורה כו' וכמשנת\"ל פע\"ה. וזהו תלת קשרין מתקשראין דא בדא כו' דהתקשרות הנשמה באלקות הוא ע\"י התורה, שזהו בד\"כ בנשמות בבחי' חלק הנשמה המלובשת בגוף וכמא' מעיקרא כי עביד אינש אדעתא דנפשי' קעביד להעלות נפשו כו', ובפרט בנשמות שהן בבחי' חלישות מצד הנה\"ב שצריכים סיוע מהתורה כו'. אבל שרש ומקור הנשמה הוא למע' מהחכ' והיא בחי' רעו\"ד רצון פשוט שלמעלה מטו\"ד כו', ומצד מדרי' זו שבנשמות הן למע' מהתורה, וה\"ה משפיעים בתורה שז\"ע לימוד התורה לשמה לשם התו' להמשיך המשכת אוא\"ס בתורה כו'. וזהו שכ' ששים המה מלכות ס' מסכתות כו' אחת היא יונתי בחי' מס\"נ באחד וכן אה\"ר דבכל\nמאדך שהן למע' מהתורה וממשיכים תוס' אור בתורה כו'. וזהו בחי' אמי המברכת לבנה כו', ועש\"ז בינה היא בחי' עלמא דדכורא שזהו בחי' רעו\"ד שעי\"ז משפיעים בתורה, ולמעלה היא ההשפעה בבחי' ז\"א כו' (ואינה נק' דכורא ע\"ש ההמשכה דבסדר השתל' שמבינה לז\"א כ\"א ע\"ש ההמשכה דעצמות אוא\"ס כו', והוא ע\"י רעו\"ד שתופס בעצמות וכמא' לית מח' תב\"כ אבל נתפס איהו ברעו\"ד כו').\n<span data-k=\"ks\"><b>קיצור.</b> ובחי' אמי הוא שנש\"י משפיעים בתורה, דלגבי בחי' נר\"ן שבנשמה התורה שהיא בחי' חכ' ומהות חכמתו ית' ה\"ה למעלה מהנשמה בעבודתו בהשגה שהיא רק ידיעת המציאות, וצריכה סיוע ע\"י התורה, ובפרט בחלישות הנפש, אבל שרש הנשמה בחי' אה\"ר ורעו\"ד למעלה מהתורה ומשפיע בתורה בחי' עצמות אוא\"ס שנתפס איהו ברעו\"ד, וזהו ג\"כ ההמשכה מבינה לז\"א.</span>\nעז) <b>אך</b> לפעמים נמשך הארה מבחי' בינה למל' וכדאי' בזח\"א ד\"ב ע\"א ואימא אוזיפת לברתא מאנהא וקשיטת לה בקישוטהא כו' ודא איקרי אדון כד\"א הנה ארון הברית אדון כל הארץ, והיינו שע\"י ההמשכה מבינה למל' נק' המל' ג\"כ אדון ל' דכר כו'. ובנפש זהו שנמשך אור מבחי' מקור ושרש הנשמה הנק' מזלא לבחי' הנשמה המלובשת בגוף, וכמו הרהורי תשובה שנופלים לאדם ע\"י דמזלי' חזי הכרוזים העליונים המעוררים על התשובה כו', וזהו בד\"כ שהוא הארה משרש הנשמה בנשמה המלובשת בגוף. אמנם י\"ל שז\"ע ובקשתם משם דפי' ובקשתם הוא ל' בקשה וחיפוש ואין חיפוש אלא אחר אבידה דהיינו דבר שהיא אבודה אצלו בבחי' גלות כו', והיינו הניצוץ האלקי שבנפשו וכחות נפשו האלקית שהם אבודים ר\"ל בחומריות הנה\"ב ומתפזרים ומתפרדים מאד בריבוי המחדו\"מ אשר לא לה' המה כו'. ועז\"א ובקשתם משם שיחפש במקום האבידה וכמ\"ש נחפשה דרכינו שיפשפש במעשיו ודבוריו ומחשבותיו שעברו וחלפו מיום היותו אשר לא טובים המה כו', ועי\"ז יתמרמר נפשו מאד מעוצם ריחוקו ויצעק אל ה' בצר לו וכמ\"ש מן המיצר קראתי כו', שמפני המיצר והצער מעוצם הריחוק ה\"ה קורא מעומק"],[3601330301,"פנימיות נפשו בבחי' רצון וצמאון גדול ביותר כו', והרי הצעקה היא בחלק הנשמה המלובשת בגוף שהיא האבודה ר\"ל בהנה\"ב, וע\"י שהיא ממארי דחושבנא בפרטי מחדו\"מ הלא טובים הרי היא צועקת במר נפשה כו', דבצעקה זו ה\"ה יוצאה מהגלות דנה\"ב וגם פועל על הנה\"ב שתתהפך גם הלב החומרי לאלקות כו'. דלפי שהיתה תחלה מלובשת ומוסתרת בנה\"ב ומתמרמרת וצועקת מעומק הלב כו', ה\"ז פועל גם על הנה\"ב שיתהפך כו', ובפרט כאשר הצעקה היא בהנה\"ב עצמו שהנה\"ב צועק על ריחוקו, והוא ג\"כ ע\"י פעולת הנה\"ב שנעשה לו צר מעניניו החומרים והבהמיים ומריחוקו מאלקות וצועק במר נפשו כו'. והסימן ע\"ז הוא כאשר המרירות הוא בלב נשבר ביותר, וכמו המיואש ר\"ל שאין לו נוחם לנפשו כלל וכמו כאשר רואה דבר לא טוב ואין לו שום עצה כלל שנשבר רוחו בקרבו לגמרי כו', ועד\"ז הוא הלב נשבר דנה\"ב כו' (ועמשית\"ל פ'). דעי\"ז מתהפך לבו לגמרי מן הקצה אל הקצה, וכנראה בחוש בבע\"ת אמיתיים שמתהפכים לגמרי בעצם מהותם ע\"י המרירות הגדולה וצמאון נפשם ביותר כו'. וז\"ע הקישוטין וכמו עד\"מ עיקר התכשיט\nהוא אבנים טובות ומרגליות ועיקר יוקרם הוא רק מצד החידוש שבהם שהאבן שהוא דומם יאיר כ\"כ וכמ\"ש במ\"א, וכך הו\"ע אתהפכא חשוכא לנהורא שלב האבן דנה\"ב תתהפך להיות בבחי' כלה שארי ולבבי ועמך לא חפצתי כו', וזה נק' קשוטין כו'. אך גם לזה צריכים פתיחת לב האבן שירגיש הרחמנות שעל נפשו שירדה מאיגרא רמה כו', ויתמרמר באמת כו', וזהו ע\"י המשכת יגמה\"ר מלמע' הגורמים פתיחת הלב כו', והן היגמה\"ר המאירים בחדש אלול כו' וכמ\"ש במ\"א, והן ג\"כ בבחי' קישוטין וכמ\"ש במ\"א הטעם שכמו התכשיט אינו מתעצם בגוף, כמו\"כ יגמה\"ר הנ\"ל אינן מתעצמין עדיין, דיגמה\"ר דיוה\"כ ה\"ה מתעצמים בבחי' מל' והיגמה\"ר דאלול שהן לעורר על התשובה אינם מתעצמין עדיין ועש\"ז נק' קישוטין כו'. וזהו ההמשכה מבינה למל' דהיינו בעבודה ההמשכה מלמע' המעורר ופותח את הלב לצאת מהגלות והשבי' כו', והתעוררות תוקף הרצון הנעשה ע\"י המרירו' והרחמנות עכ\"פ כו', דמצד שרש הנשמה הרי יש בה בחי' הרצוא דבכל מאדך בעצם וזהו בחי' אימא בעצם שיש התגלות שרש הנשמה, ומה שאי' אוזיפת מאנהא וקישוטהא\nכו' הוא שיהי' בחי' הרצוא ע\"י המרירות על הריחוק והתעוררות ר\"ר כו'. וז\"ע אדון עוזנו שגם המל' נק' אדון ל' דכר שזהו בנפש כאשר הנשמה המלובשת מתעורר ע\"י הריחוק בתשובה אמיתית בבחי' רצוא וצמאון כו', ה\"ה ג\"כ בבחי' דכורא המשפיע וממשיך מבחי' עצמות אוא\"ס ב\"ה, ואדרבה זה מגיע למעלה יותר מן הרצון שמצד שרש הנשמה עצמה כו' וכמ\"ש במ\"א, ונק' אדון עוזנו שזה נותן כח בנפש לצאת מהשפלות והריחוק ונעשה כלי לאלקות למדרי' נעלית ביותר היינו גם לבחי' אורות שלמע' מבחי' הכלים כו'. ועוי\"ל ענין ההמשכה מבינה למל', דהנה מל' הו\"ע קבעומ\"ש וידוע דבקבעומ\"ש יש ב' אופנים וכנודע ההפרש בין קבעומ\"ש דכל השנה לקבעומ\"ש דר\"ה, דבכל השנה הוא בבחי' כח נעלם שאין בזה התגלות כו', ועם היות שאין זה בדרך עול והכרח כו' והוא בבחי' ביטול כעבד לפני האדון כו', כי תמיד יש עול ואימת האדון עליו כו', מ\"מ אין בזה התגלות הנפש כו', דהעבודה בהתגלות היא בכחות הגלוים דמוח ולב שזהו העבודה התמידית דכל השנה כו', אבל בר\"ה הרי העבודה היא קבעומ\"ש, דקבעומ\"ש דר\"ה היא בהתגלו' פנימי ועצמי בנפש בבחי' נתינה ומסירה בכל עצם נפשו שנותן א\"ע"],[3601330302,"(וואס ער גיט זעך אוועק צו אלקות) בכל עצמו ומהותו ובבחי' ביטול פנימי כו', רק שאינו בהתפעלות בנפש דבד\"כ ענין קבעומ\"ש אינו בהתפעלות להיות שזהו בבחי' ביטול כו', כי בענין הביטול יש יתרון בקבעומ\"ש גם על האה\"ר דבכל מאדך להיות שקבעומ\"ש הוא בבחי' הנחת עצמותו כו', אמנם בבחי' התפעלות הרצוא ובבחי' קירוב והתכללות נפשו באלקות בזה יש יתרון באה\"ר דרעו\"ד כו', ויש מעלה בהתפעלות להיות שזהו התגלות הנפש ויש בזה גילוי אור יותר כו', ובד\"כ הוא בבחי' קירוב יותר כו', וזה שיהי' הקבעומ\"ש בהתגלות נפשו בנתינה ומסירה אמיתית זהו\"ע ההמשכה מבינה למל' להיות בקב\"ע ג\"כ בחי' התגלות פנימי כו'. וז\"ע אדון עוזנו שתהי' המל' בבחי' אדון, דהיינו כאשר נמשך מבחי' בינה במל' להיות המל' ג\"כ בחי' רעו\"ד שלמע' מטו\"ד כו', ומזה נמשך עוזנו ע\"ד הוא נותן עוז ותעצומות לעם שיהי' ג\"כ בבחי' דכר להיות למטה ג\"כ בחי' תוקף הרצוא בתשובה הבאה מבחי' הריחוק עכ\"פ שהו\"ע ובקשתם משם כו', או בבחי' קבעומ\"ש בהתגלות בנפש שבא בבחי' תוקף ובחוזק גדול כו'. והנה אדון\nעוזנו זהו בחי' המקיף דמל' דאצי' כמו שהיא באצי' והיא הפועלת בכללות נשמות בענינים הנ\"ל, אמנם מש\"א צור משגבינו מגן ישענו משגב בעדינו כו' הוא ההמשכה בפרטיות הנשמות דבי\"ע, להיות דבנשמות יש כמה חילוקי מדרי', ובד\"כ הן בבחי' נפש רוח ונשמה דיש מי שעבודתו הוא בבחי' נפש לבד דהיינו רק בעשי' לבד בקיום המצות בפו\"מ ואינו שייך לאיזה השגה והתפעלות מדות שבלב כ\"א רק אל המעשה בלבד כו', וגם העשי' הוא רק בדרך עבודת עבד בקבלת עול כו', שאינו יודע כוונת המצוה ומה שנמשך עי\"ז כ\"א שנצטווה לעשותה וצריך לעשותה ומשו\"ז עושה את המצוה כו'. ויש שעבודתו הוא בבחי' רוח דהיינו התפעלות אהוי\"ר שבלב, אם רק בבחי' אהוי\"ר טבעים והן האהוי\"ר המוסתרים בנפש שכאו\"א מישראל יש בו בטבעו אהבה לאלקו', וכמו\"כ יש בהם בחי' היראה בטבע שירא למרוד כו', דיסוד היראה הזאת הוא שאינו יכול להיות נפרד ח\"ו מאלקות, והוא הביטול טבעי שיש בנש\"י בעצם (דמשו\"ז הן בבחי' ארץ חפץ ארץ הראוי לזריעה דמצות מפני הביטול שבהם כו' וכמ\"ש במ\"א), וצריכים להוציא האהוי\"ר שיהי'\nבהתגלות בהתפעלות מורגשת בלב כו', ולא בחיצוניות ובבחי' מקיף לבד שיכול להיות בהתלהבו' גדולה ואינו שייך למעשה כלל כו', כ\"א שתהי' בבחי' הרגש פנימי ועכ\"פ בתבונת מוחו ותעלומות לבו שיבוא לידי מעשה בפו\"מ בסו\"מ וע\"ט כו'. ועיקר העבודה דבחי' רוח הוא כשהתעוררו' האהוי\"ר הן ע\"י השגה והתבוננות שאז הן בבחי' הרגש פנימי בבחי' קירוב לאלקות, דכאשר האהבה היא ע\"י התבוננו' אז היא רוצה באמת באלקות כו', ונותנת חיות ואור בקיום המצות וגם מתקנים את הנה\"ב כו' וכמ\"ש במ\"א, רק שההתבוננות היא רק השייכה אל המדות והיינו בבחי' חיצוניו' המוחין כו'. ומי שהוא בבחי' הנשמה עיקר עבודתו הוא בבחי' השגה והתבוננות אלקי בבחי' עצמות המוחין ובהרגש האלקי בעצם כו', והמדות באים בדרך ממילא והן ג\"כ בבחי' גדלות כו' וכמ\"ש במ\"א (והגם שנת\"ל פמ\"ה דמוחין דברי' בד\"כ הן בחי' מוחין השייכים למדות לבד כו', י\"ל שיש בזה הפרש בין מלאכים לנשמות דבנשמות בחי' נשמה הוא בחי' עצמות המוחין כו' ומדרי' האצי' הוא מה שלמע' מהשגת הנבראים והן חב\"ד של א\"ס ב\"ה כו' וכמ\"ש בסש\"ב פל\"ט, ובד\"כ הוא העבודה שלמע' מטו\"ד המושג ובחי' ראי' דחכ' כו')."],[3601330303,"<span data-k=\"ks\"><b>קיצור.</b> והנה אימא אוזיפת לברתא מאנהא וקשיטת לה, והוא המשכה משרש הנשמה לנשמה המלובשת בגוף להיות ובקשתם משם בהמחדו\"מ דנה\"ב, ונעשה עי\"ז הצעקה והיציאה בתוקף הרצוא, וגם הנה\"ב מתהפך עי\"ז, ובפרט כאשר הצעקה היא מנה\"ב, והכח ע\"ז מיגמה\"ר דאלול שנק' קישוטין מפני שאינן מתעצמין, גם ענין המשכה הנ\"ל הוא להיות קבעומ\"ש דר\"ה בהתגלות פנימי ועצמי, ואז נק' המל' היינו הנשמה שבגוף אדון ל' דכר שממשיך בחי' עצמות אוא\"ס, ואדון עוזנו זהו בחי' המקיף דמל' כמו שהוא באצי', וצור מגן ומשגב הן מקיפים דנר\"ן, נפש קיום המצות בעשי' בפו\"מ, רוח העבודה באהוי\"ר בהרגש פנימי שע\"י התבוננות, נשמה העבודה דבחי' מוחין והמדות באין ממילא.</span>\nעח) <b>וכשם</b> שהמה מחולקים בעבודתם כמו\"כ יש חילוקי מדרי' בתשו' בג' מדרי' נר\"ן, תשו' דבחי' נפש וכמ\"ש הנפש החוטאת והתשו' היא שמדרי' נפש תשוב בתשו' כו', ותשו' דבחי' רוח וכמ\"ש והרוח תשוב אל האלקי' כו', ותשו' דבחי' נשמה כמ\"ש רוחי ונשמתי אליו יאסוף כו'. והענין הוא דהנה נפש הוא בחי' עשי' בפו\"מ כנ\"ל וכמו\"כ התשו' בזה הוא בסומ\"ר בפו\"מ כו', כאשר מתמרמר מאד בנפשו על החטא ועון וצר לו מאד מזה ונעשה אצלו הסכם חזק מאד בלבו לסור מדרכי הרע ולעזוב כל דרכי רשע כמ\"ש יעזוב רשע דרכו כו', ונק' עזיבת החטא בפו\"מ לשנות דרכיו הקודמים מההיפך אל ההיפך כו', דכאשר מרירות נפשו הוא באמת שמתחרט על העבר אז הקבלה וההסכם הוא אמיתי ומשנה דרכו לגמרי כו'. וכמו\"כ התשו' על התגברו' החומריו' בכלל גם בדברים המותרי' כו', והיינו לא על חטא ועון בפו\"מ ר\"ל רק על החומריו' מה שנמשך מאד אחר טבע נפשו הבהמיו' ואינו יכול ליפרד מזה כו', שזהו מצד התקשרות נפשו שמקושר מאד בענינים החומריים אינו יכול ליפרד מהם (ער קען זעך ניט א(זאגין\nדערפון), וע\"י המרירו' ע\"ז ה\"ה פועל ישועות בנפשו שלא תהי' מקושרת בענינים החומרים ולא תומשך אחר הטבע וישנה דרכו בזה כו'. וכמו\"כ התשו' על העדר קבעומ\"ש ובפרט כשיש פר\"ע שאין פחד אלקים עליו כו' שצ\"ל תשובה ע\"ז ולהמשיך עליו עומ\"ש כו', שכ\"ז הוא בכלל תשובה דבחי' נפש כו'. ותשו' דבחי' רוח הוא התשובה על העדר התעוררו' אהוי\"ר כו', שהרי יש חיוב על כאו\"א להיות התעוררות אהוי\"ר שזהו מצוה ממצות התורה שמחוייב כאו\"א מישראל, וגם שעי\"ז הוא בירור ותיקון הנה\"ב שע\"ז הוא תכלית ירידתו למט' לזכך את הנה\"ב שלכך נוצר כו'. ובכדי שיהי' ציור פנימי בנה\"ב שיהי' בבחי' אדם א\"א כ\"א ע\"י התעוררו' אהוי\"ר בהתגלו' הלב הבאה ע\"י התבוננות דוקא כו', דהנה כפיית והכנעת הנה\"ב יכול להיות גם בלא אהוי\"ר (וכ\"ש בלא אהוי\"ר הבאה ע\"י התבוננות כו') ע\"י התוקף שבנפש להתגבר על הנה\"ב, ועי\"ז נעשה ג\"כ חלישו' הנה\"ב הן מצד העדר הפעולה דעניני' החומריים שנחלש עי\"ז הטבע החומריו', וביותר ע\"י הכפי' גופא כו'. אבל אינו נעשה עי\"ז חקיקה וציור פנימי בהנה\"ב כו', כ\"א\nע\"י האהבה שע\"י התבוננו' נעשה ציור פנימי בהנה\"ב, לפי שבההתבוננו' מבין השכל הטבעי ג\"כ את הענין האלקי, והעיקר שבהתעוררו' אהבה זאת דנה\"א מתעורר גם הנה\"ב באהבה לאלקו' כו', ועל העדר ההתעוררו' דאהוי\"ר ה\"ה מצטער בנפשו שאינה נשלמת הכוונה בירידתו למט' כו', ובפרט שהסיבה היא מצד התגברות הנה\"ב הגורם טמטום הלב, דמדו'"],[3601330304,"דנה\"א הן בהתעלמות ואינו מתפעל מענין אלקי כו', ומצטער מאד ע\"ז שהרי במשך הזמן בהעדר עבודה מתגבר הנה\"ב ביותר והנה\"א נחלש כו' ומי יודע למה שיכול לבא ח\"ו עי\"ז כו'. וע\"ז היא התשובה דוהרוח תשוב להיו' התפעלו' המדות כו', ותשו' במדרי' זו היא בהתפעלו' בנפש יותר מתשו' דבחי' נפש (והיינו שהתשובה גופא היא בבחי' רוח כו'). והגם דתשו' דבחי' נפש היא על המעשה בפו\"מ (וכן על התגברו' החומריו' שזהו בפו\"מ שמעשיו הם כמעשה בהמה ובפרט בפר\"ע שזהו מקור כל המיני הרע ר\"ל וכמ\"ש במ\"א), ובודאי כאשר יערה עליו רוח טהרה ויתעורר בתשובה ע\"ז נוגע לו הענינים בפנימיו' נפשו ממש יותר מהעדר העבודה בהתעוררו' אהוי\"ר, דמ\"מ זהו בדקות יותר שהרי עכ\"פ אינו מעוברי עבירה ח\"ו (ואינו נחשב כבהמה רק שאינו אדם כו'). ומ\"מ התשובה בזה היא בבחי' התפעלות יותר מתשו' דנפש, להיות דמי שהוא רק בבחי' נפש אין בו ענין ההתפעלות בנפשו כ\"כ, וע\"כ התשו' הגם שהיא בהתעוררו' פנימי בעצמו' נפשו מפני שהעניני' נוגעים לו באמת בפנימי' נפשו עד שמשתנה עי\"ז בכל דרכיו\nוהילוכיו כו', מ\"מ אין בזה התפעלו' כ\"כ (ואין הכוונה שאין בזה התפעלות כלל שהרי כאו\"א כלול מכל המדרי' ויש בו גם בחי' רוח כו', אבל אין ההתפעלות בתוקף כ\"כ כו'), ובד\"כ התשובה היא ששייך לעשי' בפו\"מ לבד לעזוב דרכו הקודמת ולשנות דרכיו לגמרי בהסכם חזק מאד כו', אבל הכל רק בהנוגע לפו\"מ לבד כו'. ומי שהוא בבחי' רוח יש בו טבע ההתפעלות בנפשו והתשובה היא על העדר התגלו' כחות הנה\"א כו', וע\"כ התשובה היא בהתפעלות גדולה כו'. ויש מעלה בזה שהתשו' היא בהתפעלו' כמו שיש מעלה בהתפעלות דרעו\"ד על קבעומ\"ש, הגם שהביטול הוא שם בבחי' ביטול פנימי ועצמי יותר כו' וכמשנת\"ל (ובאמת העדר האהוי\"ר הגם שהיא בדקות מגיע מזה הפגם למע' יותר להיותו במדרי' גבוה יותר כו', דהנה כתי' כי האדם עץ השדה כו' ועד\"מ עץ פרי הרי הפירות שהן בגובה האילן כשנופלים על הארץ ה\"ה נופלי' במרחק יותר מן האילן כו', וכמו\"כ בעץ החיים דנשמות מי שהוא במדרי' גבוה הרי הנפילה ר\"ל היא למטה יותר כו', וע\"כ במי שמצד מעלת נשמתו ה\"ה שייך לעבוד' דאהוי\"ר הנה העדר העבוד'\nעושה בו ריחוק גדול יותר ועלול ח\"ו יותר לרע ר\"ל, והיינו לבד זאת שהכתם על בגד חשוב גרוע יותר כו' הנה הוא עלול ח\"ו ליפול יותר ברע ר\"ל, וע\"כ צ\"ל באמת תשו' גדולה יותר כו'). וזהו דתשו' דרוח להיותו במעלת ומדרי' הרוח ע\"כ התשובה היא בהתפעלו' יותר כו' (ובפרט אם יש בו איזה חטא ח\"ו התשו' היא בתוקף ההתפעלו' ביותר כו'), ותשוב' דבחי' נשמה היא על העדר ההשגה האלקי' וההתבוננו' האלקי כו', שגם בזה הוא החיוב על כאו\"א וכמו בעסק התורה בכלל והעסק בפנימיות התו' בפרט כו', וכמ\"ש באגה\"ק בקו\"א ד\"ה להבין מ\"ש בפע\"ח שידיעת ההשתל' היא מצוה רבה ונשאה ואדרבה עולה על כולנה כמ\"ש וידעת היום כו' דע את אלקי אביך כו', ומביאה ללב שלם כו'. ועל ההעדר צ\"ל תשובה כו', והעיקר הוא על העדר ההרגש במוחו, שגם כשמתבונן בענין אלקי אין הענין נרגש במוחו (עס לייגט זעך בא עם דער ענין ניט א(במוחו און עס ווערט ניט דערהערט) ואינו מתפעל במוחו כו', שזהו מצד טמטום המוח כו' (ויש בזה כמה חילוקי מדרי' בהעדר ההנחה וההרגש ובהעדר ההתפעלות כו'), ומתמרמר\nבנפשו ע\"ז שהוא ריק מענין אלקי שאינו מאיר בנפשו וממילא גם התפעלו' המדות הוא בחיצוניו' לגמרי כו', ותשובה זו היא בבחי' פנימיו' יותר מתשו' דבחי' רוח כו' (וזהו"],[3601330305,"שהתשו' היא בבחי' נשמה דהיינו בבחי' פנימיו' ובעומק יותר כו', דכשם שהעבודה דנשמה היא בעומק יותר שהיא בחי' עצמו' המוחין כנ\"ל, כמו\"כ התשובה היא בבחי' פנימיו' ועומק בנפש כו'). דהנה להיותו במדרי' נשמה הרי יש בו עכ\"פ ידיעה והשגה אלקית, וכאשר מתעורר בתשו' על העדר ההרגש כו' ה\"ה יודע ממה שנתרחק כו', וע\"כ הריחוק נוגע לו באמת בפנימיו' נפשו ביותר, וה\"ה בעיני עצמו כמו חוטא ופושע ממש ומצטער בנפשו מאד כמו שהי' עובר עבירה ר\"ל, דמפני הידיעה באלקות (ובהתשו' ההרגש הוא ביותר וכמו הכרה פנימי' באלקו' כו') ע\"כ נרגש מאד איך שרע ומר עזבו את ה' כו', וה\"ה שב בכל לבו ובכל נפשו מעומק ופנימיו' נפשו כו', ועי\"ז מסיר ההעלמו' וההסתרי' ויהי' באמת כלי לאור אלקי שיאיר בגילוי בנפשו במוחו ולבו כו'. ועל כל אלו המדרי' בתשו' נמשך כח וסיוע מלמע' הן על עצם התשו' והן על השמירה אח\"כ כו', וכמו בתשו' דבחי' נפש נמשך לו הכח מלמע' להתמרמר באמת על דרכיו ועניניו ולהיות אצלו הסכם חזק לשנות דרכיו כו', וה' בוחן לב וכליות יודע היטב הסכם החזק\nהטוב ועוזר לו להתהלך תמיד בדרך הטוב כו', וכה\"ג הוא בתשו' דבחי' רוח ונשמה נמשך הסיוע מלמע' הן ע\"ז שיתעורר בתשובה והן אח\"כ שתהי' העבודה תמידית כו'. וז\"ע צור משגבינו מגן ישענו כו', דאדון עוזנו הוא כללות כח התשו' שבנפש הבאה מצד הריחוק כו', דהיינו מה שמצד עצם נקודת היהדות שלו (שזהו בחי' נקודת הלב שנק' כנס\"י שזהו בחי' נקודת המל' שיש בכאו\"א מישראל כו') נוגע לו מאד בנפשו ריחוקו מאלקו', ומתעורר בתשובה שלימה להיו' בבחי' קירוב כו', ומש\"א צור משגבינו כו' זהו בדרך פרט במדרי' נר\"ן שהן בחי' בי\"ע כל חו\"ח לפי מדריגתו כו', וכ\"ז הוא בחי' המקיף דמל' שנמשך על מדרי' נשמתו אם היא מברי' או יצי' ועשי' כו'. וזהו בחי' הכתרים הפרטים בד' עולמו' אבי\"ע בכלל ובפרט כו'.\n<span data-k=\"ks\"><b>קיצור.</b> יבאר חלקי התשובה דנר\"ן, נפש החוטאת היא תשוב בסו\"מ בפו\"מ בחרטה אמיתית ואז גם הקבלה אמיתית, גם התשובה על התגברות החומריות שלא יומשך אחר הטבע, גם על העדר קבעומ\"ש, ותשו' דרוח היא על העדר העבודה דאהוי\"ר שזהו מ\"ע וגם שעי\"ז דוקא תיקון הנה\"ב בציור פנימי, ותשו' זו היא בהתפעלות יותר מפני שרוח הוא התפעלות, הגם שמעשה נוגע יותר, ובאמת ג\"ז נוגע מאד כמשל פרי שבראש האילן נופלת מרחוק יותר, ותשו' דנשמה היא על העדר ההשגה האלקית והתבוננות, והיא בבחי' הרגש פנימי ביותר, והכח על כ\"ז הוא מבחי' המקיפים דצור מגן משגב, וזהו המקיפים פרטים ופעולתם.</span>\nעט) <b>ובכ\"ז</b> הגם שנמשך הכתר דהיינו בחי' הרצון לכל עולם בפרט כפי מהות ומדרי' העולם כו', מ\"מ אין בזה התחלקו' מדרי' בעצם דהכל הוא בחי' רצון והיינו דהכל הוא מהות א' בעצם כו'. ואין זה כמו בע\"ס דהע\"ס דברי' הן בבחי' מהות אחר מהע\"ס דאצי' וכמשנת\"ל פמ\"ה, משא\"כ הרצון אינו מהות אחר דהכל הוא רצון א' כו'. ועם היות שבודאי בחי' כתר דאצי' הוא בבחי' גילוי יותר מכתר דברי' כו', מ\"מ בעצם מהותם הוא מדרי' א' כו', ויכול להיות ההגדלה בבחי' כתר דברי' וגם בבחי' כתר דעשי' להיות יותר גם מבחי' כתר דאצי' כו', דהרי בבחי' אור פנימי הרי בחי' חכ' דעשי' הוא כמו עד\"מ שכל המעשי וחכ' דאצי' זהו"],[3601330306,"עד\"מ עצמות החכ' כו', הרי כמה שתהי' ההגדלה והגילוי בשכל המעשי הרי לא יהי' במעלת ומדרי' עצמי' החכ' כ\"א במדרי' שכל המעשי כו'. וכמו אומן חכם גדול שמופלא הוא בחכמתו כמו במלאכת הציור או במלאכת הריקום וכה\"ג, הרי כל חכמתו היא באין ערוך לגבי חכם גדול במושכלות נעלות בעצם החכ' כו', והיינו מפני שבכללות הוא שכל המעשי לבד כו'. וכמו\"כ יובן דחכ' דעשי' להיות שבעצם המדרי' היא במהות אחר מחכ' דאצי', הנה גם אם יהי' בזה הגדלה ותוס' אור הכל הוא במדרי' חכ' דעשי' ואינה בערך בחי' חכ' דאצי' כו', ולכן בחי' היותר אחרונה דאצי' שבעשי' ה\"ז למע' באין ערוך מהמדרי' היותר עליונה דעשי' עצמה כו' וכמ\"ש במ\"א (רק בחכ' דתורה אין התחלקו' מדרי' שגם כמו שבאה בחכ' דעשי' היא באותו המהות ממש דבחי' חכ' דאצי' וכמו באור פניך נתת לנו כו', ויכול להיות בזה ההגדלה להיות באותו בחי' האור והגילוי ממש כו', דבאמת המשכה דתורה היא בעצם למע' מס' השתל' כו'). אבל בבחי' הכתר יכול להיות הגדלת האור והגילוי דבחי' כתר דעשי' להיות כמו כתר דאצי' כו'. וכמו\nברצון הרי יכול להיות תוקף הרצון במעשה כמו בשכל כו', וכמו\"כ יכול להיו' הגדלה בכתר דעשי' להיות כמו כתר דאצי' וגם למע' מזה כו'. ובאמת יש בבחי' כתר דעשי' כח נעלה יותר דבכדי שבמדרי' נפש תהי' התשובה באמת זהו ממדרי' עליונה יותר כו', וגם ע\"י תשובתו האמיתי' מאיר אור עליון יותר כו'. וכידוע בענין אז אתם, א' תם דתמים במעשיו בעשי' בפו\"מ מגיע בבחי' אלף שזהו תמימות הרצון פשוט וכמשי\"ת. וכמו\"כ הוא בענין התשובה ג\"כ דתשו' דבחי' נפש מגיע למע' יותר כו'. וז\"ע דהשתל' הכתרים זמ\"ז דכתר דברי' וגם כתר דעשי' יש לו שייכות לבחי' כתר דאצי' יותר מבחי' חכ' דאצי', דהחכ' מאין תמצא כעין יש מאין מבחי' הכתר כו', והמשכת הכתרים הוא בבחי' השתל' זמ\"ז כו'. וענין ההשתל' בזה אינו בס' והדרגה דהשתל' להיות בחי' הארה זמ\"ז כו', דההשתל' באופן כזה הוא רק במדרי' שבאים בבחי' התלבשו' כו' וכמשנת\"ל פנ\"א, ובהמשכת הכתרים הוא שעצם המהות נמשך בכל מקום והכל הוא מהות א' ממש כו'. ונמצא דבחי' הרצון אין בו התחלקות מדרי' שזהו בחי' האור שבבחי' א\"ס\nובבחי' בל\"ג דא\"ס ממש להתפשטותו שנמשך בכל מקום כו', ובכ\"מ שנמשך אינו בבחי' התלבשות והוא בבחי' א\"ס ממש כו'.\n<b>וע\"פ</b> מה שנת\"ל הג' תשובו' דנר\"ן יובן מ\"ש שובה ישראל כו' דחשיב כאן ג' תשובו' הנ\"ל, דמ\"ש שובה ישראל היא תשובה דנפש, ועז\"א כי כשלת בעוניך שהיא התשובה להיות סו\"מ בפ\"מ כו'. ומ\"ש קחו עמכם דברים ושובו אל הוי' היא תשובה דרוח, דדבור הוא בחי' רוח וכמ\"ש לנפש חי' ות\"א לרוח ממללא כו', דתשו' זו אינו על עשי' בפו\"מ כ\"א על העבודה דאהוי\"ר, ולכן אינו אומר כי כשלת כו' כ\"א קחו עמכם דברים כו'. ואח\"כ או' אמרו אליו כל תשא עון היא תשו' דנשמה, ואומר בזה אמרו אליו להיות שזהו בבחי' קירוב שהרי יש בו ידיעת והשגת אלקו' כו', וגם דאמירה היא בלב בחי' מחשבה וזהו בחי' נשמה כו'. ואומרו כל תשא עון הוא בחי' המקיף שז\"ע כל בחי' התכללו' כו', והיינו שכל התשובו' האלו הן בכח האו\"מ שנמשך בכל המדרי' דבי\"ע כו'. וידוע דמ\"ש כל תשא עון קאי על בחי' סובב ומקיף הכללי כו', והוא שהמקיפי' הפרטים הן בבחי' אחדות ממש בבחי' סובב ומקיף הכללי שהכל הוא מהות א' ממש כו' כנ\"ל, ולכן נמשך משם סליחת"],[3601330307,"עוונות שזהו מבחי' המקיף דוקא ובפרט מבחי' המקיף הכללי כו'. וזהו שובה ישראל עד ה' אלקיך תשו' דבחי' נפש כו', קחו עמכם דברים ושובו כו' תשובה דבחי' רוח כו', אמרו אליו כל תשא עון הוא תשובה דבחי' נשמה כו', שכ\"ז הוא מבחי' המקיף, וכל המקיפים הם בבחי' אחדות ממש בבחי' סובב ומקיף הכללי ונמשך משם להיות נושא עון כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ומ\"מ כל המקיפים הפרטים הכל מהות א' הוא, דבאו\"פ הרי בי\"ע מהות אחר, וגם אם יהי' הגדלה בחכ' דעשי' ה\"ז באין ערוך לגבי אצי' וכמו שכל המעשי לגבי עצם, משא\"כ הרצון יכול להיות בתוקף במעשה כמו בשכל, וכמו בכתר דעשי' יכול להיות הגדלה כמו בכתר דאצי' (ובאמת יש בזה כח נעלם נעלה יותר), דהשתל' הכתרים זמ\"ז, וההשתל' היא שנמשך ממהות למהות, וע\"כ הכל באמת מהות א' בלי התחלקות. ובהנ\"ל פע\"ח יובן מ\"ש שובה ישראל, דכי כשלת היא תשובה דנפש, קחו עמכם דברים תשו' דרוח ממללא, אמרו אליו תשו' דנשמה בחי' מח', וכ\"ז הוא בכח האו\"מ זהו כל תשא עון.</span>"]]});
